class ActiveHookCall {
public:
    explicit ActiveHookCall(HookStatusRecord* status) noexcept
        : status_(status)
    {
        if (status_) {
            dluma_atomic_increment(&status_->active_calls);
            ++g_current_thread_hook_call_depth;
        }
    }

    ~ActiveHookCall()
    {
        if (status_) {
            --g_current_thread_hook_call_depth;
            dluma_atomic_decrement(&status_->active_calls);
        }
    }

    bool publish() const noexcept
    {
        return dluma_atomic_compare_exchange(&g_trace_live, 0, 0) != 0 &&
               dluma_atomic_compare_exchange(&g_trace_stopping, 0, 0) == 0;
    }

private:
    HookStatusRecord* status_;
};

class RetainingObservationCall {
public:
    RetainingObservationCall(
        cold::ContentDomainId domain,
        cold::RetainingObservationOrigin origin,
        const cold::ReplayOperationIdentity* observed = nullptr) noexcept
        : admitted_(false)
    {
        std::memset(&token_, 0, sizeof(token_));
        /* Before tracking starts there cannot be an active registry
         * transaction. Ordinary game calls retain their native behavior. */
        if (!g_fix_enabled || !g_cold_reboot_registry.sealed ||
            dluma_atomic_compare_exchange(&g_content_live, 0, 0) == 0) {
            admitted_ = !observed && origin == cold::RetainingObservationOrigin::ExternalProducer;
        } else {
            cold::RegistryReplayPermitToken permit = {};
            const bool replay_active = cold::CurrentRegistryReplayPermit(
                &g_cold_reboot_registry, domain, &permit);
            if (replay_active || observed) {
                // Missing/mismatched actual arguments never fall back to
                // ordinary admission or borrow the expected manifest fields.
                admitted_ = replay_active && observed && observed->domain == domain &&
                    cold::BeginRetainingReplayObservation(
                        &g_cold_reboot_registry, &permit, observed, &token_);
            } else {
                admitted_ = cold::BeginRetainingObservation(
                    &g_cold_reboot_registry, domain, origin, &token_);
            }
        }
        if (!admitted_) {
            char reason[160] = {};
            dluma_str_copy(reason, sizeof(reason), "retaining producer admission rejected: ");
            dluma_str_append(reason, sizeof(reason), cold::ContentDomainName(domain));
            (void)dluma_frontend_error_present(reason, g_cold_reboot_registry.prepared_content_epoch);
        }
    }

    ~RetainingObservationCall()
    {
        if (token_.active)
            (void)cold::EndRetainingObservation(
                &g_cold_reboot_registry, &token_);
    }

    bool admitted() const noexcept { return admitted_; }

    RetainingObservationCall(
        const RetainingObservationCall&) = delete;
    RetainingObservationCall& operator=(
        const RetainingObservationCall&) = delete;

private:
    cold::RetainingObservationToken token_;
    bool admitted_;
};

bool ResolveProductionAudioIdentity(std::uint32_t,std::uintptr_t,const char*,bool,
    cold::ReplayOperationIdentity*) noexcept;
thread_local std::uint32_t g_audio_replay_observed_ordinal;
class AudioReplayInvocation;
thread_local AudioReplayInvocation* g_audio_replay_invocation;
class AudioReplayInvocation {
    cold::ReplayOperationIdentity actual_ = {};
    bool replay_ = false;
    AudioReplayInvocation* parent_ = nullptr;
    RetainingObservationCall retaining_;
    const cold::ReplayOperationIdentity* Observe(std::uint32_t operation,std::uintptr_t owner,
        const char* path,bool localized) noexcept {
        cold::RegistryReplayPermitToken permit = {};
        replay_ = cold::CurrentRegistryReplayPermit(&g_cold_reboot_registry,cold::ContentDomainId::Audio,&permit);
        if (!replay_) return nullptr;
        parent_ = g_audio_replay_invocation;
        (void)ResolveProductionAudioIdentity(operation,owner,path,localized,&actual_);
        actual_.ordinal = ++g_audio_replay_observed_ordinal;
        actual_.parent_ordinal = parent_ ? parent_->actual_.ordinal : 0;
        return &actual_;
    }
public:
    AudioReplayInvocation(std::uint32_t operation,std::uintptr_t owner,const char* path=nullptr,bool localized=false) noexcept
        : retaining_(cold::ContentDomainId::Audio,cold::RetainingObservationOrigin::ExternalProducer,
            Observe(operation,owner,path,localized)) {
        if (replay_ && retaining_.admitted()) g_audio_replay_invocation = this;
    }
    ~AudioReplayInvocation() {
        if (replay_ && retaining_.admitted()) g_audio_replay_invocation = parent_;
    }
    bool admitted() const noexcept { return retaining_.admitted(); }
    const cold::ReplayOperationIdentity* actual() const noexcept { return replay_ && admitted() ? &actual_ : nullptr; }
};

