int AssetModRefreshNamespace(const char* path)
{
    if (!g_filesystem_full_profile_valid || !g_context.filesystem_base || !path) return 0;
    using RefreshFn = void (__cdecl*)(const char*);
    void* const entry = reinterpret_cast<void*>(GetProcAddress(
        reinterpret_cast<HMODULE>(g_context.filesystem_base), "?refresh@fs@@YAXPEBD@Z"));
    if (entry != reinterpret_cast<void*>(g_context.filesystem_base + 0x17610U)) return 0;
    reinterpret_cast<RefreshFn>(entry)(path);
    return 1;
}

