bool ReadBytes(std::uintptr_t address, void* output, std::size_t size) noexcept
{
    if (!address || !output || !size ||
        size > static_cast<std::size_t>(UINTPTR_MAX - address) ||
        !dluma_is_readable(reinterpret_cast<const void*>(address), size))
        return false;
    std::memcpy(output, reinterpret_cast<const void*>(address), size);
    return true;
}

bool ReadPlayerInventoryBootstrapMemory(
    void*, std::uintptr_t address, void* output,
    std::size_t size) noexcept
{
    return ReadBytes(address, output, size);
}

bool ReadLoadedModuleIdentity(HMODULE module, std::uintptr_t* base_output,
                              std::uint32_t* timestamp_output,
                              std::uint32_t* image_size_output) noexcept
{
    const std::uintptr_t base = reinterpret_cast<std::uintptr_t>(module);
    std::uint16_t dos_signature = 0;
    std::uint32_t nt_offset = 0;
    std::uint32_t nt_signature = 0;
    std::uint16_t optional_magic = 0;
    std::uint32_t timestamp = 0;
    std::uint32_t image_size = 0;
    if (!base || !ReadBytes(base, &dos_signature, sizeof(dos_signature)) ||
        dos_signature != 0x5A4D ||
        !ReadBytes(base + 0x3C, &nt_offset, sizeof(nt_offset)) ||
        nt_offset < 0x40 || nt_offset > 0x00100000U ||
        !ReadBytes(base + nt_offset, &nt_signature,
                   sizeof(nt_signature)) ||
        nt_signature != 0x00004550U ||
        !ReadBytes(base + nt_offset + 24, &optional_magic,
                   sizeof(optional_magic)) || optional_magic != 0x020B ||
        !ReadBytes(base + nt_offset + 8, &timestamp, sizeof(timestamp)) ||
        !ReadBytes(base + nt_offset + 24 + 56, &image_size,
                   sizeof(image_size)) || image_size < 0x1000U)
        return false;
    if (base_output) *base_output = base;
    if (timestamp_output) *timestamp_output = timestamp;
    if (image_size_output) *image_size_output = image_size;
    return true;
}

bool ValidateLoadedModuleSha256(HMODULE module,
                                const char* expected_sha256) noexcept
{
    if (!module || !expected_sha256) return false;
    WCHAR path[DLUMA_MAX_WPATH];
    if (!dluma_get_module_path_checked(
            module, path, DLUMA_ARRAY_COUNT(path)))
        return false;
    char actual[DLUMA_SHA256_HEX_CAPACITY];
    if (!dluma_sha256_file_hex(path, 512ULL * 1024ULL * 1024ULL,
                             actual))
        return false;
    return dluma_stricmp(actual, expected_sha256) == 0;
}

bool BytesEqual(std::uintptr_t address, const void* expected,
                std::size_t size) noexcept
{
    std::uint8_t actual[64];
    if (!expected || !size || size > sizeof(actual) ||
        !ReadBytes(address, actual, size))
        return false;
    return std::memcmp(actual, expected, size) == 0;
}

bool AsciiEqualsInsensitive(const char* left, const char* right) noexcept
{
    if (!left || !right) return left == right;
    while (*left && *right) {
        char a = *left++;
        char b = *right++;
        if (a >= 'A' && a <= 'Z') a = static_cast<char>(a + ('a' - 'A'));
        if (b >= 'A' && b <= 'Z') b = static_cast<char>(b + ('a' - 'A'));
        if (a != b) return false;
    }
    return *left == *right;
}

bool AsciiEquals(const char* left, const char* right) noexcept
{
    if (!left || !right) return left == right;
    while (*left && *right) {
        if (*left++ != *right++) return false;
    }
    return *left == *right;
}

bool CustomMainMenuBankOwnerIndex(
    const char* owner_id, unsigned int* index_out) noexcept
{
    const char prefix[] = DLUMA_SOURCE_OWNER_ID_CUSTOM_MAIN_MENU_BANK;
    const std::size_t prefix_length = sizeof(prefix) - 1U;
    unsigned int value = 0;
    if (index_out) *index_out = 0;
    if (!owner_id || !index_out) return false;
    for (std::size_t index = 0; index < prefix_length; ++index) {
        char left = owner_id[index];
        char right = prefix[index];
        if (!left) return false;
        if (left >= 'A' && left <= 'Z') left = static_cast<char>(left + 32);
        if (right >= 'A' && right <= 'Z') right = static_cast<char>(right + 32);
        if (left != right) return false;
    }
    if (owner_id[prefix_length] != '.' ||
        !owner_id[prefix_length + 1U] ||
        !owner_id[prefix_length + 2U] ||
        owner_id[prefix_length + 3U])
        return false;
    for (unsigned int digit = 0; digit < 2U; ++digit) {
        const char character = owner_id[prefix_length + 1U + digit];
        unsigned int nibble;
        if (character >= '0' && character <= '9')
            nibble = static_cast<unsigned int>(character - '0');
        else if (character >= 'a' && character <= 'f')
            nibble = static_cast<unsigned int>(character - 'a' + 10);
        else if (character >= 'A' && character <= 'F')
            nibble = static_cast<unsigned int>(character - 'A' + 10);
        else
            return false;
        value = (value << 4U) | nibble;
    }
    if (value >= DLUMA_CUSTOM_MENU_MAX_BANKS) return false;
    *index_out = value;
    return true;
}

bool BoundedContainsInsensitive(const char* text, const char* needle) noexcept
{
    if (!text || !needle || !*needle) return false;
    for (std::size_t i = 0; text[i] && i < 4096; ++i) {
        std::size_t j = 0;
        while (needle[j] && text[i + j]) {
            char a = text[i + j];
            char b = needle[j];
            if (a == '/') a = '\\';
            if (b == '/') b = '\\';
            if (a >= 'A' && a <= 'Z') a = static_cast<char>(a + 32);
            if (b >= 'A' && b <= 'Z') b = static_cast<char>(b + 32);
            if (a != b) break;
            ++j;
        }
        if (!needle[j]) return true;
    }
    return false;
}

bool NormalizedPathWithinRoot(const char* path, const char* root) noexcept
{
    char normalized_path[content::kSourcePathCapacity];
    char normalized_root[content::kSourcePathCapacity];
    if (!path || !root || path[0] == '<' || root[0] == '<' ||
        !content::NormalizePhysicalPath(
            path, normalized_path, sizeof(normalized_path)) ||
        !content::NormalizePhysicalPath(
            root, normalized_root, sizeof(normalized_root)))
        return false;
    return content::PathWithinRoot(normalized_path, normalized_root);
}

void CopyLiteral(char* output, std::size_t capacity,
                 const char* value) noexcept
{
    if (!output || !capacity) return;
    output[0] = 0;
    if (!value) return;
    std::size_t length = 0;
    while (length + 1 < capacity && value[length]) ++length;
    if (length) std::memcpy(output, value, length);
    output[length] = 0;
}

std::uint64_t FingerprintBoundedText(const char* text,
                                     std::size_t capacity) noexcept
{
    if (!text || !capacity || !text[0]) return 0;
    std::uint64_t hash = 1469598103934665603ULL;
    for (std::size_t index = 0; index < capacity; ++index) {
        const unsigned char value =
            static_cast<unsigned char>(text[index]);
        if (!value) return hash ? hash : 1U;
        hash ^= value;
        hash *= 1099511628211ULL;
    }
    return 0;
}

void MarkTextTruncated(char* output, std::size_t capacity) noexcept
{
    static const char marker[] = "<truncated>";
    if (!output || capacity <= sizeof(marker)) return;
    const std::size_t offset = capacity - sizeof(marker);
    std::memcpy(output + offset, marker, sizeof(marker));
}

void CopyLoaderText(char* output, std::size_t capacity,
                    const char* value) noexcept
{
    CopyLiteral(output, capacity, value ? value : "<null>");
}

bool EncodeRawBytesHex(
    const char* input, std::size_t length,
    char* output, std::size_t capacity) noexcept
{
    static constexpr char kHex[] = "0123456789ABCDEF";
    if (!input || !output || !capacity ||
        length > (capacity - 1U) / 2U) {
        if (output && capacity) output[0] = 0;
        return false;
    }
    for (std::size_t index = 0; index < length; ++index) {
        const std::uint8_t value =
            static_cast<std::uint8_t>(input[index]);
        output[index * 2U] = kHex[value >> 4U];
        output[index * 2U + 1U] = kHex[value & 0x0FU];
    }
    output[length * 2U] = 0;
    return true;
}

bool CopyLoaderTextComplete(char* output, std::size_t capacity,
                            const char* value) noexcept
{
    CopyLiteral(output, capacity, value ? value : "<null>");
    if (!value || !output || !capacity) return false;
    std::size_t length = 0;
    while (length < capacity && value[length]) ++length;
    return length < capacity;
}

trace::AssetTraceStringCopyResult CopyEngineText(
    char* output, std::size_t capacity, const char* value) noexcept
{
    return trace::CopyReadableCString(output, capacity, value, 4096);
}

void CopyTtlText(char* output, std::size_t capacity,
                 const TtlStringView* value) noexcept
{
    TtlStringView local = {};
    if (!ReadBytes(reinterpret_cast<std::uintptr_t>(value), &local,
                   sizeof(local))) {
        CopyLiteral(output, capacity, "<unreadable>");
        return;
    }
    if (local.size > 0x00100000U || local.capacity < local.size ||
        local.size >= 4096U) {
        CopyLiteral(output, capacity, "<invalid-ttl-string>");
        return;
    }
    trace::CopyReadableCString(output, capacity, local.data,
                               static_cast<std::size_t>(local.size) + 1U);
}

struct TtlVectorView {
    void* data;
    std::uint32_t size;
    std::uint32_t capacity;
};

bool CopyCampaignTtlText(char* output, std::size_t capacity,
                         std::uintptr_t address) noexcept
{
    if (!output || !capacity) return false;
    output[0] = 0;
    TtlStringView value = {};
    if (!ReadBytes(address, &value, sizeof(value)) ||
        value.capacity < value.size || value.size >= 4096U) {
        CopyLiteral(output, capacity, "<unreadable>");
        return false;
    }
    if (!value.size) return true;
    if (!value.data ||
        trace::CopyReadableCString(
            output, capacity, value.data,
            static_cast<std::size_t>(value.size) + 1U) !=
            trace::AssetTraceStringCopyResult::Copied) {
        if (!output[0]) CopyLiteral(output, capacity, "<unreadable>");
        return false;
    }
    return true;
}

bool ReadCampaignVector(std::uintptr_t campaign,
                        std::uintptr_t offset,
                        TtlVectorView* output) noexcept
{
    if (!output || !ReadBytes(campaign + offset, output, sizeof(*output)) ||
        output->capacity < output->size ||
        output->size > kMaximumCampaignTableEntries)
        return false;
    return output->size == 0 || output->data != nullptr;
}

bool BuildCampaignStateSnapshot(
    void* manager_interface, trace::CampaignSnapshotPhase phase,
    trace::CampaignStateSnapshot* output,
    std::uint32_t requested_campaign_index = UINT32_MAX) noexcept
{
    if (!output) return false;
    std::memset(output, 0, sizeof(*output));
    output->phase = phase;
    output->manager = reinterpret_cast<std::uintptr_t>(manager_interface);
    if (!manager_interface) return false;

    const std::uintptr_t manager =
        reinterpret_cast<std::uintptr_t>(manager_interface);
    void* table = nullptr;
    std::uint32_t table_count = 0;
    std::uint32_t manager_selected_index = UINT32_MAX;
    if (!ReadBytes(manager + kCampaignInterfaceTableOffset,
                   &table, sizeof(table)) ||
        !ReadBytes(manager + kCampaignInterfaceTableCountOffset,
                   &table_count, sizeof(table_count)) ||
        !ReadBytes(manager + kCampaignInterfaceSelectedIndexOffset,
                   &manager_selected_index,
                   sizeof(manager_selected_index)) ||
        table_count == 0 || table_count > kMaximumCampaignTableEntries ||
        manager_selected_index >= table_count || !table ||
        !dluma_is_readable(
            table, static_cast<SIZE_T>(table_count * kCampaignStride)))
        return false;

    const std::uint32_t selected_index =
        requested_campaign_index == UINT32_MAX
            ? manager_selected_index : requested_campaign_index;
    if (selected_index >= table_count) return false;

    output->campaign_table_count = table_count;
    output->selected_campaign_index = selected_index;
    output->manager_selected =
        selected_index == manager_selected_index;
    output->selected_campaign =
        reinterpret_cast<std::uintptr_t>(table) +
        static_cast<std::uintptr_t>(selected_index) * kCampaignStride;
    output->completeness_flags |=
        trace::CampaignSnapshotSelectedIndex;
    const std::uintptr_t campaign = output->selected_campaign;

    bool identity_complete =
        ReadBytes(campaign, &output->campaign_id,
                  sizeof(output->campaign_id)) &&
        CopyCampaignTtlText(output->campaign_name,
                            sizeof(output->campaign_name),
                            campaign + kCampaignNameOffset) &&
        CopyCampaignTtlText(output->campaign_source,
                            sizeof(output->campaign_source),
                            campaign + kCampaignSourceOffset);
    if (identity_complete)
        output->completeness_flags |=
            trace::CampaignSnapshotCampaignName;

    const bool rewards_complete = CopyCampaignTtlText(
        output->rewards, sizeof(output->rewards),
        campaign + kCampaignRewardsOffset);
    output->rewards_count =
        rewards_complete && output->rewards[0] ? 1U : 0U;
    if (rewards_complete)
        output->completeness_flags |= trace::CampaignSnapshotRewards;

    const bool after0_complete = CopyCampaignTtlText(
        output->after_respawn0, sizeof(output->after_respawn0),
        campaign + kCampaignAfterRespawn0Offset);
    const bool after1_complete = CopyCampaignTtlText(
        output->after_respawn1, sizeof(output->after_respawn1),
        campaign + kCampaignAfterRespawn1Offset);
    output->after_respawn_count =
        (after0_complete && output->after_respawn0[0] ? 1U : 0U) +
        (after1_complete && output->after_respawn1[0] ? 1U : 0U);
    if (after0_complete && after1_complete)
        output->completeness_flags |=
            trace::CampaignSnapshotAfterRespawn;

    std::uint32_t flag_word = 0;
    std::uint8_t flag0 = 0;
    std::uint8_t flag1 = 0;
    const bool flags_complete =
        ReadBytes(campaign + kCampaignFlagsOffset,
                  &flag_word, sizeof(flag_word)) &&
        ReadBytes(campaign + kCampaignFlagsOffset + 4U,
                  &flag0, sizeof(flag0)) &&
        ReadBytes(campaign + kCampaignFlagsOffset + 5U,
                  &flag1, sizeof(flag1));
    output->campaign_flags = flag_word;
    output->campaign_flag0 = flag0;
    output->campaign_flag1 = flag1;
    if (flags_complete)
        output->completeness_flags |= trace::CampaignSnapshotFlags;

    TtlVectorView names = {};
    TtlVectorView levels = {};
    TtlVectorView ids = {};
    bool maps_complete =
        ReadCampaignVector(campaign, kCampaignMapsOffset, &names) &&
        ReadCampaignVector(campaign, kCampaignLevelNamesOffset, &levels) &&
        ReadCampaignVector(campaign, kCampaignMapIdsOffset, &ids) &&
        names.size == levels.size && names.size == ids.size;
    output->map_count = maps_complete ? names.size : 0;
    if (maps_complete && names.size > trace::kMaximumObservedCampaignMaps) {
        maps_complete = false;
        output->completeness_flags |=
            trace::CampaignSnapshotFingerprintPartial;
    }
    const std::uint32_t copy_count =
        names.size < trace::kMaximumObservedCampaignMaps
            ? names.size
            : static_cast<std::uint32_t>(
                  trace::kMaximumObservedCampaignMaps);
    if (names.size &&
        (!dluma_is_readable(names.data,
                          static_cast<SIZE_T>(names.size *
                                              sizeof(TtlStringView))) ||
         !dluma_is_readable(levels.data,
                          static_cast<SIZE_T>(levels.size *
                                              sizeof(TtlStringView))) ||
         !dluma_is_readable(ids.data,
                          static_cast<SIZE_T>(ids.size *
                                              sizeof(std::int32_t)))))
        maps_complete = false;
    if (names.size && names.data && levels.data && ids.data) {
        for (std::uint32_t index = 0; index < copy_count; ++index) {
            trace::BoundedCampaignMap* map = &output->maps[index];
            map->registration_order = index;
            const bool name_ok = CopyCampaignTtlText(
                map->map_name, sizeof(map->map_name),
                reinterpret_cast<std::uintptr_t>(names.data) +
                    index * sizeof(TtlStringView));
            const bool level_ok = CopyCampaignTtlText(
                map->level_name, sizeof(map->level_name),
                reinterpret_cast<std::uintptr_t>(levels.data) +
                    index * sizeof(TtlStringView));
            const bool id_ok = ReadBytes(
                reinterpret_cast<std::uintptr_t>(ids.data) +
                    index * sizeof(std::int32_t),
                &map->map_id, sizeof(map->map_id));
            map->complete = name_ok && level_ok && id_ok;
            if (!map->complete) maps_complete = false;
        }
    }
    if (maps_complete)
        output->completeness_flags |= trace::CampaignSnapshotMaps;

    const std::uint32_t required =
        trace::CampaignSnapshotSelectedIndex |
        trace::CampaignSnapshotCampaignName |
        trace::CampaignSnapshotMaps |
        trace::CampaignSnapshotRewards |
        trace::CampaignSnapshotAfterRespawn |
        trace::CampaignSnapshotFlags;
    if ((output->completeness_flags & required) == required)
        output->completeness_flags |= trace::CampaignSnapshotComplete;
    else
        output->completeness_flags |=
            trace::CampaignSnapshotFingerprintPartial;
    output->logical_fingerprint =
        trace::FingerprintCampaignState(*output);
    return (output->completeness_flags &
            trace::CampaignSnapshotComplete) != 0;
}

