struct SerializedFrameRouteEvidence {
    std::uint64_t route_token;
    std::uint64_t authority_sequence;
    std::uint32_t current_frame_thread_id;
    bool route_active;
    bool authority_conflict;
};

statefive::RejectReason CurrentSerializedGameFrameRouteMatches(
    std::uint64_t expected_route_token,
    std::uint32_t current_thread,
    SerializedFrameRouteEvidence* evidence) noexcept
{
    if (evidence) std::memset(evidence, 0, sizeof(*evidence));
    DlumaGameFrameAuthorityState authority = {};
    if (!evidence || !current_thread ||
        !dluma_engine_game_frame_hook_owned(&g_dluma.engine) ||
        !dluma_engine_snapshot_game_frame_authority(
            &g_dluma.engine, &authority))
        return statefive::RejectReason::C10FrameRouteUnavailable;
    evidence->route_token =
        authority.exact_route_serialization_token;
    evidence->authority_sequence =
        authority.game_frame_authority_sequence;
    evidence->current_frame_thread_id =
        static_cast<std::uint32_t>(
            authority.current_dispatch_thread_id);
    evidence->authority_conflict =
        authority.game_frame_authority_conflict != 0;
    const std::uint32_t active_thread =
        static_cast<std::uint32_t>(dluma_atomic_compare_exchange(
            &g_dluma.engine.game_frame_callback_active_thread_id,
            0, 0));
    evidence->route_active =
        authority.exact_route_identity_seeded != 0 &&
        evidence->route_token != 0 &&
        evidence->authority_sequence != 0 &&
        active_thread == current_thread &&
        evidence->current_frame_thread_id == current_thread;
    if (evidence->authority_conflict)
        return statefive::RejectReason::C10FrameAuthorityConflict;
    if (!evidence->route_active)
        return statefive::RejectReason::C10FrameRouteUnavailable;
    if (expected_route_token &&
        expected_route_token != evidence->route_token)
        return statefive::RejectReason::C10FrameRouteChanged;
    return statefive::RejectReason::C10ScopeMatched;
}

bool SnapshotPleaseWaitOwnerToken(
    statefive::PleaseWaitOwnerToken* output) noexcept
{
    if (output) std::memset(output, 0, sizeof(*output));
    if (!output) return false;
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_please_wait_token.sequence, 0, 0);
        if (before & 1) continue;
        const statefive::PleaseWaitOwnerToken observed =
            g_cold_reboot_please_wait_token.token;
        const LONG after = dluma_atomic_compare_exchange(
            &g_cold_reboot_please_wait_token.sequence, 0, 0);
        if (before != after || (after & 1)) continue;
        *output = observed;
        return true;
    }
    return false;
}

bool StorePleaseWaitOwnerToken(
    const statefive::PleaseWaitOwnerToken& token,
    statefive::PleaseWaitOwnerToken* stored_token) noexcept
{
    if (stored_token)
        std::memset(stored_token, 0, sizeof(*stored_token));
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_please_wait_token.sequence, 0, 0);
        if (before & 1) continue;
        if (dluma_atomic_compare_exchange(
                &g_cold_reboot_please_wait_token.sequence,
                before + 1, before) != before)
            continue;
        g_cold_reboot_please_wait_token.token = token;
        (void)dluma_atomic_increment(
            &g_cold_reboot_please_wait_token.sequence);
        if (stored_token) *stored_token = token;
        return true;
    }
    return false;
}

bool PublishPleaseWaitCompletion(
    void* game_di, std::uint32_t content_epoch,
    const SerializedFrameRouteEvidence& frame,
    statefive::PleaseWaitOwnerToken* published_token) noexcept
{
    if (!game_di || !content_epoch) return false;
    const std::uint64_t generation =
        static_cast<std::uint64_t>(
            _InterlockedIncrement64(
                &g_cold_reboot_destroy_generation));
    LARGE_INTEGER qpc = {};
    const std::uint64_t published_qpc =
        QueryPerformanceCounter(&qpc) && qpc.QuadPart > 0
            ? static_cast<std::uint64_t>(qpc.QuadPart)
            : 0;
    const statefive::PleaseWaitOwnerToken token =
        statefive::PublishPleaseWaitStateTwoOwnerToken(
            game_di, content_epoch, generation,
            frame.route_token, frame.authority_sequence,
            published_qpc, GetCurrentThreadId(),
            true, frame.authority_conflict);
    return StorePleaseWaitOwnerToken(
        token, published_token) && token.completed;
}

void InvalidatePleaseWaitCompletion(
    void* game_di, bool exact_state_two,
    const SerializedFrameRouteEvidence& frame,
    statefive::PleaseWaitOwnerToken* invalidated_token) noexcept
{
    const statefive::PleaseWaitOwnerToken token =
        statefive::PublishPleaseWaitStateTwoOwnerToken(
            game_di, 0, 0, frame.route_token,
            frame.authority_sequence, 0,
            GetCurrentThreadId(), exact_state_two,
            frame.authority_conflict);
    (void)StorePleaseWaitOwnerToken(
        token, invalidated_token);
}

statefive::RejectReason ConsumePleaseWaitCompletion(
    const statefive::C10AttemptEvidence& evidence,
    statefive::PleaseWaitOwnerToken* consumed_token) noexcept
{
    if (consumed_token)
        std::memset(consumed_token, 0, sizeof(*consumed_token));
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        statefive::PleaseWaitOwnerToken token = {};
        if (!SnapshotPleaseWaitOwnerToken(&token))
            continue;
        const std::uint64_t last_consumed =
            static_cast<std::uint64_t>(
                _InterlockedCompareExchange64(
                    &g_cold_reboot_last_consumed_destroy_generation,
                    0, 0));
        const statefive::RejectReason authorization =
            statefive::AuthorizeStateFiveC10AcrossWorkerMigration(
                &token, evidence, last_consumed);
        if (authorization !=
            statefive::RejectReason::C10ScopeMatched)
            return authorization;

        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_please_wait_token.sequence, 0, 0);
        if (before & 1) continue;
        const statefive::PleaseWaitOwnerToken current =
            g_cold_reboot_please_wait_token.token;
        if (current.destroy_generation !=
                token.destroy_generation ||
            current.game_di != token.game_di ||
            current.content_epoch != token.content_epoch ||
            current.frame_route_token != token.frame_route_token ||
            current.consumed)
            continue;
        if (dluma_atomic_compare_exchange(
                &g_cold_reboot_please_wait_token.sequence,
                before + 1, before) != before)
            continue;
        const std::uint64_t current_last_consumed =
            static_cast<std::uint64_t>(
                _InterlockedCompareExchange64(
                    &g_cold_reboot_last_consumed_destroy_generation,
                    0, 0));
        if (token.destroy_generation <= current_last_consumed) {
            (void)dluma_atomic_increment(
                &g_cold_reboot_please_wait_token.sequence);
            return statefive::RejectReason::C08TokenStale;
        }
        g_cold_reboot_please_wait_token.token.consumed = true;
        _InterlockedExchange64(
            &g_cold_reboot_last_consumed_destroy_generation,
            static_cast<LONGLONG>(token.destroy_generation));
        (void)dluma_atomic_increment(
            &g_cold_reboot_please_wait_token.sequence);
        token.consumed = true;
        if (consumed_token) *consumed_token = token;
        return statefive::RejectReason::C10ScopeMatched;
    }
    return statefive::RejectReason::C10ScopeBeginRejected;
}

bool BeginDestroyOwnerDiagnosticsWrite(LONG* sequence) noexcept
{
    if (sequence) *sequence = 0;
    if (!sequence) return false;
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_destroy_owner_diagnostics.sequence, 0, 0);
        if (before & 1) continue;
        if (dluma_atomic_compare_exchange(
                &g_cold_reboot_destroy_owner_diagnostics.sequence,
                before + 1, before) == before) {
            *sequence = before + 1;
            return true;
        }
    }
    return false;
}

void EndDestroyOwnerDiagnosticsWrite(LONG sequence) noexcept
{
    if (sequence & 1)
        dluma_atomic_exchange(
            &g_cold_reboot_destroy_owner_diagnostics.sequence,
            sequence + 1);
    MarkContentDirty();
}

void IncrementDestroyOwnerCounter(std::uint64_t* value) noexcept
{
    if (value && *value != UINT64_MAX) ++*value;
}

bool SnapshotDestroyOwnerDiagnostics(
    ColdRebootDestroyOwnerDiagnosticsSnapshot* output) noexcept
{
    if (!output) return false;
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_destroy_owner_diagnostics.sequence,
            0, 0);
        if (before & 1) continue;
        const ColdRebootDestroyOwnerDiagnosticsSnapshot observed =
            g_cold_reboot_destroy_owner_diagnostics.snapshot;
        const LONG after = dluma_atomic_compare_exchange(
            &g_cold_reboot_destroy_owner_diagnostics.sequence,
            0, 0);
        if (before != after || (after & 1)) continue;
        *output = observed;
        return true;
    }
    return false;
}

void RecordC08DestroyOwnerDiagnostics(
    void* game_di, std::uint32_t state,
    const statefive::PleaseWaitOwnerToken& token,
    bool exact_state_two, bool token_published) noexcept
{
    LONG sequence = 0;
    if (!BeginDestroyOwnerDiagnosticsWrite(&sequence)) return;
    ColdRebootDestroyOwnerDiagnosticsSnapshot& snapshot =
        g_cold_reboot_destroy_owner_diagnostics.snapshot;
    IncrementDestroyOwnerCounter(&snapshot.c08_callback_count);
    if (exact_state_two)
        IncrementDestroyOwnerCounter(
            &snapshot.c08_exact_state_two_count);
    if (token_published)
        IncrementDestroyOwnerCounter(
            &snapshot.c08_token_publish_count);
    snapshot.c08_last_game_di =
        reinterpret_cast<std::uintptr_t>(game_di);
    snapshot.c08_last_state = state;
    snapshot.c08_last_epoch = token.content_epoch;
    snapshot.c08_last_destroy_generation =
        token.destroy_generation;
    snapshot.c08_last_thread =
        token.c08_callback_thread_id;
    snapshot.c08_last_frame_route_token =
        token.frame_route_token;
    snapshot.c08_last_frame_authority_sequence =
        token.frame_authority_sequence;
    snapshot.c08_last_frame_authority_conflict =
        token.frame_authority_conflict;
    EndDestroyOwnerDiagnosticsWrite(sequence);
}

void RecordC10DestroyOwnerDiagnostics(
    const statefive::C10AttemptEvidence& evidence,
    const statefive::PleaseWaitOwnerToken& token,
    statefive::RejectReason reason,
    bool token_consume_attempted,
    bool token_consumed,
    bool scope_started,
    bool arm_attempted,
    bool armed) noexcept
{
    LONG sequence = 0;
    if (!BeginDestroyOwnerDiagnosticsWrite(&sequence)) return;
    ColdRebootDestroyOwnerDiagnosticsSnapshot& snapshot =
        g_cold_reboot_destroy_owner_diagnostics.snapshot;
    IncrementDestroyOwnerCounter(&snapshot.c10_callback_count);
    if (evidence.content_tracking_live &&
        evidence.exact_hook_profile &&
        evidence.caller_rva ==
            statefive::kExactStateFiveCallerRva &&
        evidence.state_readable && evidence.state == 5U)
        IncrementDestroyOwnerCounter(
            &snapshot.c10_exact_owner_count);
    if (token_consumed)
        IncrementDestroyOwnerCounter(
            &snapshot.c10_token_consume_count);
    else if (token_consume_attempted)
        IncrementDestroyOwnerCounter(
            &snapshot.c10_token_consume_failure_count);
    if (scope_started)
        IncrementDestroyOwnerCounter(
            &snapshot.c10_scope_begin_count);
    if (arm_attempted) {
        IncrementDestroyOwnerCounter(
            armed ? &snapshot.c10_arm_success_count
                  : &snapshot.c10_arm_failure_count);
    }
    snapshot.c10_last_game_di =
        reinterpret_cast<std::uintptr_t>(evidence.game_di);
    snapshot.c10_last_caller_rva = evidence.caller_rva;
    snapshot.c10_last_state = evidence.state;
    snapshot.c10_last_epoch = evidence.content_epoch;
    snapshot.c10_last_thread =
        evidence.c10_callback_thread_id;
    snapshot.c10_last_current_frame_thread =
        evidence.current_frame_thread_id;
    snapshot.c10_last_frame_route_token =
        evidence.frame_route_token;
    snapshot.c10_last_frame_authority_sequence =
        evidence.frame_authority_sequence;
    snapshot.c10_last_frame_authority_conflict =
        evidence.frame_authority_conflict;
    snapshot.c10_last_outgoing_session =
        reinterpret_cast<std::uintptr_t>(
            evidence.outgoing_session);
    statefive::PersistC10Result(
        &snapshot.persisted_result, reason);
    snapshot.c10_worker_migrated =
        token.c08_callback_thread_id &&
        token.c08_callback_thread_id !=
            evidence.c10_callback_thread_id;
    EndDestroyOwnerDiagnosticsWrite(sequence);
}

void RecordSessionOnDestroyC10Diagnostics(
    statefive::RejectReason reason) noexcept
{
    LONG sequence = 0;
    if (!BeginDestroyOwnerDiagnosticsWrite(&sequence)) return;
    ColdRebootDestroyOwnerDiagnosticsSnapshot& snapshot =
        g_cold_reboot_destroy_owner_diagnostics.snapshot;
    statefive::PersistSessionOnDestroyResult(
        &snapshot.persisted_result, reason);
    EndDestroyOwnerDiagnosticsWrite(sequence);
}

