    if (!game_di || !ReadBytes(
            reinterpret_cast<std::uintptr_t>(game_di) +
                coldwin::kCurrentSessionOffset,
            &session, sizeof(session)))
        return reinterpret_cast<void*>(~std::uintptr_t{0});
