void* FindLiveCustomPlayerOwner() noexcept
{
    playerstate::OwnerRecord owners[playerstate::kOwnerCapacity] = {};
    const std::uint32_t count = playerstate::CaptureLiveOwners(
        &g_player_state_ledger, owners,
        playerstate::kOwnerCapacity);
    for (std::uint32_t index = 0; index < count; ++index) {
        if (!owners[index].live) continue;
        if (owners[index].owner_kind == playerstate::OwnerKind::PlayerDi ||
            owners[index].owner_kind ==
                playerstate::OwnerKind::TutorialPlayerDi)
            return reinterpret_cast<void*>(owners[index].owner_object);
    }
    return nullptr;
}

bool ColdRebootNextProjectStagingStarted() noexcept
{
    return g_change_depth || g_after_fade_depth || g_load_level_depth ||
        g_update_dlc_depth || g_pending_source_add.depth;
}

std::uint64_t ReadSourceRegistryGeneration() noexcept
{
    return static_cast<std::uint64_t>(
        _InterlockedCompareExchange64(
            &g_source_registry_generation, 0, 0));
}

bool ReadStableSourceRegistryGeneration(
    std::uint64_t* generation) noexcept
{
    if (generation) *generation = 0;
    const std::uint64_t before = ReadSourceRegistryGeneration();
    const LONG active = dluma_atomic_compare_exchange(
        &g_source_registry_active_calls, 0, 0);
    const std::uint64_t after = ReadSourceRegistryGeneration();
    if (!generation || active != 0 || before != after) return false;
    *generation = after;
    return true;
}

struct PostC10PhaseStamp {
    std::uint64_t sequence;
    std::uint64_t qpc;
    std::uint32_t thread_id;
};

PostC10PhaseStamp CapturePostC10PhaseStamp() noexcept
{
    PostC10PhaseStamp stamp = {};
    stamp.sequence = static_cast<std::uint64_t>(
        _InterlockedIncrement64(
            &g_cold_reboot_post_c10_phase_sequence));
    LARGE_INTEGER qpc = {};
    if (QueryPerformanceCounter(&qpc) && qpc.QuadPart > 0)
        stamp.qpc = static_cast<std::uint64_t>(qpc.QuadPart);
    stamp.thread_id = GetCurrentThreadId();
    return stamp;
}

std::uint64_t MixPostC10SourceIdentity(
    std::uint64_t hash, std::uint64_t value) noexcept
{
    if (!hash) return 0;
    for (unsigned int shift = 0; shift < 64; shift += 8) {
        hash ^= static_cast<std::uint8_t>(value >> shift);
        hash *= 1099511628211ULL;
    }
    return hash ? hash : 1U;
}

std::uint64_t ComputePostC10SourceSetIdentity(
    const FrontendEpochBinding& binding,
    std::uint64_t source_registry_generation) noexcept
{
    if (!binding.epoch || !binding.session ||
        !binding.outgoing_level || !source_registry_generation)
        return 0;
    std::uint64_t identity = FingerprintBoundedText(
        "post_c10_bound_source_set_v1", 64U);
    identity = MixPostC10SourceIdentity(
        identity, binding.epoch);
    identity = MixPostC10SourceIdentity(
        identity,
        reinterpret_cast<std::uintptr_t>(binding.session));
    identity = MixPostC10SourceIdentity(
        identity,
        reinterpret_cast<std::uintptr_t>(binding.outgoing_level));
    identity = MixPostC10SourceIdentity(
        identity, binding.owner_thread_id);
    identity = MixPostC10SourceIdentity(
        identity, source_registry_generation);
    identity = MixPostC10SourceIdentity(
        identity, FingerprintBoundedText(
            binding.selected_content_name,
            sizeof(binding.selected_content_name)));
    identity = MixPostC10SourceIdentity(
        identity, FingerprintBoundedText(
            binding.normalized_project_root,
            sizeof(binding.normalized_project_root)));
    identity = MixPostC10SourceIdentity(
        identity, FingerprintBoundedText(
            binding.outgoing_map, sizeof(binding.outgoing_map)));
    return identity;
}

statefive::PostC10Expectation BuildPostC10Expectation(
    const ColdRebootStateFiveScope& scope,
    const FrontendEpochBinding& binding,
    std::uint64_t source_set_identity,
    std::uint64_t source_registry_generation) noexcept
{
    statefive::PostC10Expectation expectation = {};
    expectation.game_di = scope.game_di;
    expectation.outgoing_session = scope.outgoing_session;
    expectation.outgoing_level = binding.outgoing_level;
    expectation.baseline_generation =
        g_cold_reboot.baseline_generation;
    expectation.destroy_generation =
        scope.please_wait_generation;
    expectation.frame_route_token = scope.frame_route_token;
    expectation.frame_authority_sequence =
        scope.frame_authority_sequence;
    expectation.source_set_identity = source_set_identity;
    expectation.source_registry_generation =
        source_registry_generation;
    expectation.content_epoch = scope.epoch;
    expectation.c10_callback_thread_id =
        scope.c10_callback_thread_id;
    expectation.owner_callback_depth =
        scope.owner_callback_depth;
    return expectation;
}

bool ClearPendingPostC10Token() noexcept
{
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_pending_post_c10_token.sequence, 0, 0);
        if (before & 1) continue;
        if (dluma_atomic_compare_exchange(
                &g_cold_reboot_pending_post_c10_token.sequence,
                before + 1, before) != before)
            continue;
        std::memset(
            &g_cold_reboot_pending_post_c10_token.token, 0,
            sizeof(g_cold_reboot_pending_post_c10_token.token));
        (void)dluma_atomic_increment(
            &g_cold_reboot_pending_post_c10_token.sequence);
        return true;
    }
    return false;
}

bool SnapshotPendingPostC10Token(
    statefive::PendingPostC10Token* output) noexcept
{
    if (output) std::memset(output, 0, sizeof(*output));
    if (!output) return false;
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_pending_post_c10_token.sequence, 0, 0);
        if (before & 1) continue;
        const statefive::PendingPostC10Token observed =
            g_cold_reboot_pending_post_c10_token.token;
        const LONG after = dluma_atomic_compare_exchange(
            &g_cold_reboot_pending_post_c10_token.sequence, 0, 0);
        if (before != after || (after & 1)) continue;
        *output = observed;
        return true;
    }
    return false;
}

bool StorePendingPostC10Token(
    const statefive::PendingPostC10Token& token) noexcept
{
    if (!token.active) return false;
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_pending_post_c10_token.sequence, 0, 0);
        if (before & 1) continue;
        if (dluma_atomic_compare_exchange(
                &g_cold_reboot_pending_post_c10_token.sequence,
                before + 1, before) != before)
            continue;
        statefive::PendingPostC10Token& current =
            g_cold_reboot_pending_post_c10_token.token;
        const statefive::PostC10Failure publication =
            statefive::PublishPendingPostC10Token(
                &current, token);
        (void)dluma_atomic_increment(
            &g_cold_reboot_pending_post_c10_token.sequence);
        return publication ==
            statefive::PostC10Failure::None;
    }
    return false;
}

statefive::PostC10Failure ConsumePendingPostC10Token(
    const statefive::PostC10Expectation& expectation,
    const statefive::PostC10Environment& environment,
    statefive::PendingPostC10Token* consumed_token) noexcept
{
    if (consumed_token)
        std::memset(consumed_token, 0, sizeof(*consumed_token));
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        statefive::PendingPostC10Token token = {};
        if (!SnapshotPendingPostC10Token(&token))
            continue;
        const statefive::PostC10Failure failure =
            statefive::ValidatePostC10PreflightOwner(
                &token, expectation, &environment);
        if (failure == statefive::PostC10Failure::TokenMissing ||
            failure == statefive::PostC10Failure::TokenReplayed)
            return failure;

        const LONG before = dluma_atomic_compare_exchange(
            &g_cold_reboot_pending_post_c10_token.sequence, 0, 0);
        if (before & 1) continue;
        const statefive::PendingPostC10Token& current =
            g_cold_reboot_pending_post_c10_token.token;
        if (current.token_publication_sequence !=
                token.token_publication_sequence ||
            current.game_di != token.game_di ||
            current.outgoing_session != token.outgoing_session ||
            current.content_epoch != token.content_epoch)
            continue;
        if (current.consumed)
            return statefive::PostC10Failure::TokenReplayed;
        if (dluma_atomic_compare_exchange(
                &g_cold_reboot_pending_post_c10_token.sequence,
                before + 1, before) != before)
            continue;
        g_cold_reboot_pending_post_c10_token.token.consumed = true;
        (void)dluma_atomic_increment(
            &g_cold_reboot_pending_post_c10_token.sequence);
        token.consumed = true;
        if (consumed_token) *consumed_token = token;
        return failure;
    }
    return statefive::PostC10Failure::TokenMismatch;
}

bool PreparedSourceRegistryIdentityStillStable() noexcept
{
    if (!g_prepared_source_reset.prepared ||
        ColdRebootNextProjectStagingStarted())
        return false;
    const std::uint64_t generation_before =
        ReadSourceRegistryGeneration();
    const LONG active_calls = dluma_atomic_compare_exchange(
        &g_source_registry_active_calls, 0, 0);
    const std::uint64_t generation_after =
        ReadSourceRegistryGeneration();
    return active_calls == 0 && generation_before == generation_after &&
        generation_after ==
            g_prepared_source_reset.source_registry_generation;
}

bool PreparedSourceRegistryPlanStillStable() noexcept
{
    return !g_dluma.stop_requested &&
        dluma_atomic_compare_exchange(
            &g_frontend_reset_stopping, 0, 0) == 0 &&
        PreparedSourceRegistryIdentityStillStable();
}

