bool BeginColdRebootStateFiveScope(
    void* game_di, void* outgoing_session, std::uint32_t epoch,
    std::uint64_t please_wait_generation,
    std::uint64_t frame_route_token,
    std::uint64_t frame_authority_sequence,
    std::uint32_t c08_callback_thread_id,
    std::uint32_t c10_callback_thread_id) noexcept
{
    if (!game_di || !outgoing_session || !epoch ||
        !please_wait_generation || !frame_route_token ||
        !c08_callback_thread_id || !c10_callback_thread_id ||
        !g_destroying_session_callback_depth ||
        g_cold_reboot_state_five_scope.active ||
        c10_callback_thread_id != GetCurrentThreadId() ||
        g_dluma.stop_requested || ColdRebootNextProjectStagingStarted() ||
        !ClearPendingPostC10Token())
        return false;
    std::memset(&g_cold_reboot_state_five_scope, 0,
                sizeof(g_cold_reboot_state_five_scope));
    std::memset(&g_prepared_source_reset, 0,
                sizeof(g_prepared_source_reset));
    g_cold_reboot_state_five_scope.game_di = game_di;
    g_cold_reboot_state_five_scope.outgoing_session =
        outgoing_session;
    g_cold_reboot_state_five_scope.please_wait_generation =
        please_wait_generation;
    g_cold_reboot_state_five_scope.frame_route_token =
        frame_route_token;
    g_cold_reboot_state_five_scope.frame_authority_sequence =
        frame_authority_sequence;
    g_cold_reboot_state_five_scope.epoch = epoch;
    g_cold_reboot_state_five_scope.c08_callback_thread_id =
        c08_callback_thread_id;
    g_cold_reboot_state_five_scope.c10_callback_thread_id =
        c10_callback_thread_id;
    g_cold_reboot_state_five_scope.owner_callback_depth =
        g_destroying_session_callback_depth;
    g_cold_reboot_state_five_scope.active = true;
    dluma_atomic_exchange(&g_post_c10_boundary_failure, 0);
    std::memset(
        &g_post_destroy_preflight_report, 0,
        sizeof(g_post_destroy_preflight_report));
    return true;
}

statefive::RejectReason MatchColdRebootStateFiveScopeSession(
    void* session, bool allow_claimed = false) noexcept
{
    const ColdRebootStateFiveScope& scope =
        g_cold_reboot_state_five_scope;
    if (g_dluma.stop_requested)
        return statefive::RejectReason::C10Shutdown;
    if (!scope.active) {
        if (g_c10_scope_result !=
            statefive::RejectReason::C08NotObserved)
            return g_c10_scope_result;
        ColdRebootDestroyOwnerDiagnosticsSnapshot diagnostics = {};
        if (SnapshotDestroyOwnerDiagnostics(&diagnostics) &&
            diagnostics.c10_callback_count &&
            diagnostics.c10_last_outgoing_session ==
                reinterpret_cast<std::uintptr_t>(session))
            return diagnostics.persisted_result.c10_reject_reason;
        return statefive::RejectReason::C08NotObserved;
    }
    if (scope.deferred_source_reset || scope.barrier_attempted ||
        (scope.on_destroy_claimed && !allow_claimed))
        return statefive::RejectReason::SessionScopeConsumed;
    const std::uint64_t last_consumed_generation =
        static_cast<std::uint64_t>(
            _InterlockedCompareExchange64(
                &g_cold_reboot_last_consumed_destroy_generation,
                0, 0));
    if (!scope.armed ||
        g_cold_reboot.armed_epoch != scope.epoch ||
        last_consumed_generation !=
            scope.please_wait_generation)
        return statefive::RejectReason::C10ScopeBeginRejected;
    statefive::StateFiveScope identity = {};
    identity.game_di = scope.game_di;
    identity.outgoing_session = scope.outgoing_session;
    identity.content_epoch = scope.epoch;
    identity.destroy_generation =
        scope.please_wait_generation;
    identity.frame_route_token = scope.frame_route_token;
    identity.frame_authority_sequence =
        scope.frame_authority_sequence;
    identity.c08_callback_thread_id =
        scope.c08_callback_thread_id;
    identity.c10_callback_thread_id =
        scope.c10_callback_thread_id;
    identity.owner_callback_depth =
        scope.owner_callback_depth;
    identity.active = scope.active;
    identity.on_destroy_claimed = scope.on_destroy_claimed;
    identity.armed = scope.armed;
    return statefive::BindSessionOnDestroyToStateFiveScope(
        &identity, session, GetCurrentThreadId(),
        g_destroying_session_callback_depth, allow_claimed);
}

bool DeferFrontendSourceResetAtOnDestroy(
    const FrontendEpochBinding& binding) noexcept
{
    ColdRebootStateFiveScope& scope =
        g_cold_reboot_state_five_scope;
    if (MatchColdRebootStateFiveScopeSession(
            binding.session, true) !=
                statefive::RejectReason::C10ScopeMatched ||
        scope.epoch != binding.epoch || scope.deferred_source_reset ||
        binding.outgoing_level != g_frontend_unload_level ||
        binding.owner_thread_id != scope.c10_callback_thread_id ||
        !g_frontend_on_destroy_unload_observed ||
        !g_frontend_outgoing_level_release_observed ||
        !lifecycle::ReadyForReset(&g_frontend_lifecycle))
        return false;
    scope.deferred_binding = binding;
    scope.release_level = g_frontend_release_level;
    scope.deferred_source_reset = true;
    return true;
}

