bool PublishPendingPostC10PreflightToken(
    const FrontendEpochBinding& binding,
    statefive::PendingPostC10Token* published_token) noexcept
{
    if (published_token)
        std::memset(published_token, 0, sizeof(*published_token));
    ColdRebootStateFiveScope& scope =
        g_cold_reboot_state_five_scope;
    std::uint64_t source_registry_generation = 0;
    const bool source_registry_stable =
        ReadStableSourceRegistryGeneration(
            &source_registry_generation);
    const std::uint64_t source_set_identity =
        source_registry_stable
            ? ComputePostC10SourceSetIdentity(
                  binding, source_registry_generation)
            : 0;
    const bool exact_scope =
        scope.active && scope.armed &&
        scope.on_destroy_claimed &&
        scope.deferred_source_reset &&
        !scope.post_c10_token_consumed &&
        scope.epoch == binding.epoch &&
        scope.outgoing_session == binding.session &&
        scope.c10_callback_thread_id == GetCurrentThreadId() &&
        scope.owner_callback_depth ==
            g_destroying_session_callback_depth &&
        FrontendEpochBindingsEqual(
            binding, scope.deferred_binding) &&
        lifecycle::ReadyForReset(&g_frontend_lifecycle);

    const PostC10PhaseStamp original_return_stamp =
        CapturePostC10PhaseStamp();
    const PostC10PhaseStamp publication_stamp =
        CapturePostC10PhaseStamp();
    const statefive::PostC10Expectation expectation =
        BuildPostC10Expectation(
            scope, binding, source_set_identity,
            source_registry_generation);
    statefive::PendingPostC10Token token =
        statefive::MakePendingPostC10Token(
            expectation, scope.c08_callback_thread_id,
            GetCurrentThreadId(),
            original_return_stamp.sequence,
            original_return_stamp.qpc,
            publication_stamp.sequence,
            g_frontend_lifecycle.release_enter_count,
            g_frontend_lifecycle.release_exit_count,
            g_frontend_on_destroy_unload_observed,
            g_frontend_lifecycle.original_unload_returned);
    if (!exact_scope) token.active = false;
    const bool stored = token.active &&
        StorePendingPostC10Token(token);
    statefive::PendingPostC10Token recorded_token = token;
    if (!stored)
        (void)SnapshotPendingPostC10Token(&recorded_token);

    const void* const unreadable =
        reinterpret_cast<void*>(~std::uintptr_t{0});
    void* const nested_current_session =
        ReadGameDiCurrentSession(scope.game_di);
    LONG diagnostic_sequence = 0;
    if (BeginDestroyOwnerDiagnosticsWrite(
            &diagnostic_sequence)) {
        ColdRebootDestroyOwnerDiagnosticsSnapshot& diagnostics =
            g_cold_reboot_destroy_owner_diagnostics.snapshot;
        diagnostics.session_original_return_sequence =
            original_return_stamp.sequence;
        diagnostics.session_original_return_qpc =
            original_return_stamp.qpc;
        diagnostics.session_original_return_thread =
            original_return_stamp.thread_id;
        diagnostics.nested_current_session_readable =
            nested_current_session != unreadable;
        diagnostics.nested_current_session =
            nested_current_session != unreadable
                ? reinterpret_cast<std::uintptr_t>(
                      nested_current_session)
                : 0;
        diagnostics.
            nested_outgoing_session_expected_still_published =
                nested_current_session != unreadable &&
                nested_current_session == scope.outgoing_session;
        if (stored)
            IncrementDestroyOwnerCounter(
                &diagnostics.post_c10_token_publish_count);
        else
            IncrementDestroyOwnerCounter(
                &diagnostics.
                    post_c10_token_publish_failure_count);
        diagnostics.last_post_c10_token = recorded_token;
        diagnostics.post_c10_last_failure =
            stored
                ? statefive::PostC10Failure::None
                : statefive::PostC10Failure::TokenMismatch;
        EndDestroyOwnerDiagnosticsWrite(diagnostic_sequence);
    }
    if (!stored) return false;

    scope.post_c10_token_publication_sequence =
        token.token_publication_sequence;
    scope.post_c10_source_set_identity =
        token.source_set_identity;
    scope.post_c10_source_registry_generation =
        token.source_registry_generation;
    if (published_token) *published_token = token;
    PublishSimple(
        AssetTraceEventType::PendingPostC10TokenPublished,
        reinterpret_cast<std::uintptr_t>(binding.session),
        reinterpret_cast<std::uintptr_t>(binding.outgoing_level),
        reinterpret_cast<std::uintptr_t>(scope.game_di),
        binding.epoch, token.token_publication_sequence,
        "destroy_session_nested_transitional",
        nested_current_session == scope.outgoing_session
            ? "outgoing-session-expected-still-published"
            : "nested-session-publication-observational");
    return true;
}

