std::uint32_t AudioObservationActiveCallCount() noexcept
{
    HookStatusRecord* const statuses[] = {
        g_audio_script_load_status,
        g_audio_script_clear_status,
        g_audio_script_reload_status,
        g_tools_load_audio_banks_status,
        g_audio_voice_factory_status,
        g_audio_named_execute_status,
        g_audio_user_stream_factory_status,
        g_audio_speech_start_status,
        g_audio_speech_data_status,
        g_audio_speech_update_status,
        g_audio_fmod_load_banks_status,
        g_sound_bank_manager_load_status,
        g_fs_open_native_audio_status,
        g_fs_full_path_audio_provider_status,
        g_tools_audio_script_execute_status,
        g_speech_bank_load_status,
        g_speech_bank_remove_localised_status,
        g_speech_bank_remove_all_status,
        g_speech_manager_create_status,
        g_speech_manager_destroy_status,
    };
    std::uint32_t total = 0;
    for (HookStatusRecord* status : statuses) {
        if (!status || !status->installed) {
            if (total != UINT32_MAX) ++total;
            continue;
        }
        const LONG active = dluma_atomic_compare_exchange(
            &status->active_calls, 0, 0);
        if (active <= 0) continue;
        const std::uint32_t value = static_cast<std::uint32_t>(active);
        total = value > UINT32_MAX - total ? UINT32_MAX : total + value;
    }
    return total;
}

