const char* ProductionAudioMinimumB0FailureName(
    ProductionAudioMinimumB0Failure failure) noexcept
{
    switch (failure) {
    case ProductionAudioMinimumB0Failure::NotRecorded:
        return "not_recorded";
    case ProductionAudioMinimumB0Failure::None:
        return "none";
    case ProductionAudioMinimumB0Failure::MinimumHookPlanIncomplete:
        return "minimum_hook_plan_incomplete";
    case ProductionAudioMinimumB0Failure::ObservationActive:
        return "minimum_observation_active";
    case ProductionAudioMinimumB0Failure::SemanticPairIncomplete:
        return "minimum_semantic_pair_incomplete";
    case ProductionAudioMinimumB0Failure::BaselineCommitRejected:
        return "minimum_baseline_commit_rejected";
    default:
        return "unknown";
    }
}

