void RecordAudioMinimumB0FirstFailure(
    ProductionAudioMinimumB0Failure failure) noexcept
{
    (void)dluma_atomic_compare_exchange(
        &g_player_audio_wiring_diagnostics.
            audio_minimum_b0_first_failure,
        static_cast<LONG>(failure), -1);
}

void RecordFirstPlayerB0FailureDiagnostics() noexcept
{
    if (g_player_b0_first_failure_recorded) return;
    const playerrestart::PlayerB0CaptureDiagnostics& candidate =
        g_player_restart_adapter.b0_diagnostics;
    for (std::uint32_t index = 0;
         index < candidate.pass1_owner_count &&
         index < playerrestart::kPlayerStateInventoryCapacity;
         ++index) {
        const playerrestart::PlayerB0StateCaptureDiagnostics& state =
            candidate.states[index];
        if (!state.state || !state.generation || !state.owner_slot ||
            state.snapshot_complete ||
            state.failure_stage ==
                playerrestart::PlayerStateSnapshotFailureStage::None)
            continue;
        g_player_b0_first_failure_diagnostics = candidate;
        g_player_b0_first_failure_recorded = true;
        return;
    }
}

void RecordFirstAudioB0FailureDiagnostics() noexcept
{
    if (!g_audio_script_b0_first_failure_recorded) {
        const auto& script =
            !g_audio_minimum_b0_first.script.complete
                ? g_audio_minimum_b0_first.script
                : g_audio_minimum_b0_second.script;
        if (script.attempted && !script.complete &&
            script.failure_stage !=
                audiosemanticsnapshot::AudioScriptSemanticStage::
                    NotAttempted &&
            script.reason_mask) {
            g_audio_script_b0_first_failure_diagnostics =
                script;
            g_audio_script_b0_first_failure_recorded = true;
        }
    }
    if (!g_audio_bank_b0_first_failure_recorded) {
        const auto& banks =
            !g_audio_minimum_b0_first.banks.complete
                ? g_audio_minimum_b0_first.banks
                : g_audio_minimum_b0_second.banks;
        if (banks.attempted && !banks.complete &&
            banks.failure_stage !=
                audiosemanticsnapshot::AudioBankSemanticStage::
                    NotAttempted &&
            banks.reason_mask) {
            g_audio_bank_b0_first_failure_diagnostics = banks;
            g_audio_bank_b0_first_failure_recorded = true;
        }
    }
}

cold::StartupB0PlayerAudioPermanentFailure
ClassifyPlayerAudioB0PermanentFailure(
    bool player_ready, bool audio_ready) noexcept
{
    if (!player_ready)
        return cold::StartupB0PlayerAudioPermanentFailure::
            PlayerGlobalStateSnapshotFailed;
    if (audio_ready)
        return cold::StartupB0PlayerAudioPermanentFailure::None;
    const audiominimum::AudioMinimumOwnerIdentity& owner =
        g_audio_minimum_b0_second.owner.exact
            ? g_audio_minimum_b0_second.owner
            : g_audio_minimum_b0_first.owner;
    if (owner.conflict || !owner.audio_fmod_receiver ||
        !owner.sound_bank_manager_receiver ||
        !owner.singleton_or_owner_slot ||
        !owner.supported_image_identity ||
        !owner.route_fingerprint ||
        !owner.audio_observation_count ||
        owner.manager_observation_count < 2U)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioManagerIdentityUnresolved;
    if (!owner.observer_revision_observed)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioObserverRevisionUnpublished;
    if (!owner.event_fence_generation_observed)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioEventFenceUnpublished;
    if (!owner.exact)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioManagerIdentityUnresolved;
    if (!g_audio_minimum_b0_first.script.complete ||
        !g_audio_minimum_b0_second.script.complete)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioScriptSnapshotFailed;
    if (!g_audio_minimum_b0_first.banks.complete ||
        !g_audio_minimum_b0_second.banks.complete)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioBankSnapshotFailed;
    if (!g_audio_minimum_b0_first.observer_revision_observed ||
        !g_audio_minimum_b0_second.observer_revision_observed)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioObserverRevisionUnpublished;
    if (!g_audio_minimum_b0_first.event_fence_generation_observed ||
        !g_audio_minimum_b0_second.event_fence_generation_observed)
        return cold::StartupB0PlayerAudioPermanentFailure::
            AudioEventFenceUnpublished;
    return cold::StartupB0PlayerAudioPermanentFailure::
        AudioManagerIdentityUnresolved;
}

void BuildPlayerAudioB0PermanentFailureReason(
    cold::StartupB0PlayerAudioPermanentFailure failure,
    char* output, std::size_t capacity) noexcept
{
    if (!output || !capacity) return;
    output[0] = 0;
    const unsigned int bounded_capacity =
        capacity > UINT_MAX ? UINT_MAX
                            : static_cast<unsigned int>(capacity);
    const auto append_hex_u64 =
        [output, bounded_capacity](std::uint64_t value) noexcept {
            static const char digits[] = "0123456789abcdef";
            char reversed[16] = {};
            char text[19] = {'0', 'x', 0};
            std::size_t count = 0;
            do {
                reversed[count++] = digits[value & 0xFU];
                value >>= 4U;
            } while (value && count < sizeof(reversed));
            std::size_t cursor = 2U;
            while (count && cursor + 1U < sizeof(text))
                text[cursor++] = reversed[--count];
            text[cursor] = 0;
            dluma_str_append(output, bounded_capacity, text);
        };
    const auto append_u64 =
        [output, bounded_capacity](std::uint64_t value) noexcept {
            char text[32] = {};
            dluma_u64_to_text(value, text, DLUMA_ARRAY_COUNT(text));
            dluma_str_append(output, bounded_capacity, text);
        };
    bool appended = false;
    if (g_player_b0_first_failure_recorded ||
        failure ==
            cold::StartupB0PlayerAudioPermanentFailure::
                PlayerGlobalStateSnapshotFailed) {
        const playerrestart::PlayerB0CaptureDiagnostics& diagnostics =
            g_player_b0_first_failure_recorded
                ? g_player_b0_first_failure_diagnostics
                : g_player_restart_adapter.b0_diagnostics;
        const playerrestart::PlayerB0StateCaptureDiagnostics* state =
            nullptr;
        for (std::uint32_t index = 0;
             index < diagnostics.pass1_owner_count &&
             index < playerrestart::kPlayerStateInventoryCapacity;
             ++index) {
            if (!diagnostics.states[index].snapshot_complete) {
                state = &diagnostics.states[index];
                break;
            }
        }
        dluma_str_append(
            output, bounded_capacity,
            "player_snapshot_failed:");
        dluma_str_append(
            output, bounded_capacity,
            state
                ? playerrestart::PlayerStateOwnerKindName(
                      state->owner_kind)
                : "owner_unresolved");
        dluma_str_append(output, bounded_capacity, ":row=");
        if (state) {
            char row[32] = {};
            dluma_u64_to_text(
                state->failed_row_index, row,
                DLUMA_ARRAY_COUNT(row));
            dluma_str_append(output, bounded_capacity, row);
        } else {
            dluma_str_append(output, bounded_capacity, "unknown");
        }
        dluma_str_append(output, bounded_capacity, ":");
        dluma_str_append(
            output, bounded_capacity,
            state
                ? playerrestart::PlayerStateSnapshotFailureStageName(
                      state->failure_stage)
                : playerrestart::PlayerRestartFailureName(
                      g_player_restart_adapter.last_failure));
        if (state &&
            state->failed_row_index <
                playerrestart::kPlayerLogicalTypeCount) {
            const bool pass2_failure =
                state->pass2_first_failed_row_index ==
                    state->failed_row_index &&
                !state->pass2_semantic_snapshot_complete;
            const auto& failed_row =
                pass2_failure
                    ? state->pass2_rows[state->failed_row_index]
                    : state->pass1_rows[state->failed_row_index];
            dluma_str_append(output, bounded_capacity, ":");
            dluma_str_append(
                output, bounded_capacity,
                playerrestart::
                    PlayerGameplayParamsWindowsRowHeaderValidationResultName(
                        failed_row.header_validation_result));
            const auto& traversal = failed_row.definition_traversal;
            dluma_str_append(output, bounded_capacity, ":level=");
            append_u64(traversal.failed_level_index);
            dluma_str_append(output, bounded_capacity, ":property=");
            append_u64(traversal.failed_property_index);
            dluma_str_append(output, bounded_capacity, ":property_id=");
            append_u64(traversal.failed_property_id);
            dluma_str_append(output, bounded_capacity, ":level_stride=");
            append_u64(traversal.configured_level_stride);
            dluma_str_append(output, bounded_capacity, ":property_stride=");
            append_u64(traversal.configured_property_stride);
            dluma_str_append(output, bounded_capacity, ":traversal_reason=");
            dluma_str_append(
                output, bounded_capacity,
                playerrestart::PlayerDefinitionTraversalFailureName(
                    traversal.first_failure));
        }
        dluma_str_append(output, bounded_capacity, ":reason_mask=");
        append_hex_u64(
            state ? state->memory_layout_reason : 0U);
        appended = true;
    }
    if (g_audio_script_b0_first_failure_recorded) {
        if (appended)
            dluma_str_append(output, bounded_capacity, ";");
        dluma_str_append(
            output, bounded_capacity, "audio_script_failed:");
        dluma_str_append(
            output, bounded_capacity,
            audiosemanticsnapshot::AudioScriptSemanticStageName(
                g_audio_script_b0_first_failure_diagnostics.
                    failure_stage));
        dluma_str_append(output, bounded_capacity, ":reason_mask=");
        append_hex_u64(
            g_audio_script_b0_first_failure_diagnostics.
                reason_mask);
        appended = true;
    }
    if (g_audio_bank_b0_first_failure_recorded) {
        if (appended)
            dluma_str_append(output, bounded_capacity, ";");
        dluma_str_append(
            output, bounded_capacity, "audio_bank_failed:");
        dluma_str_append(
            output, bounded_capacity,
            audiosemanticsnapshot::AudioBankSemanticStageName(
                g_audio_bank_b0_first_failure_diagnostics.
                    failure_stage));
        dluma_str_append(output, bounded_capacity, ":reason_mask=");
        append_hex_u64(
            g_audio_bank_b0_first_failure_diagnostics.
                reason_mask);
        appended = true;
    }
    if (!appended)
        CopyLoaderText(
            output, capacity,
            cold::StartupB0PlayerAudioPermanentFailureName(
                failure));
}

bool ExpireUnresolvedPlayerAudioB0OnFrame(
    const cold::StartupB0AdmissionSample& sample,
    std::uint64_t now_ms) noexcept
{
    const std::size_t player_domain_index = static_cast<std::size_t>(
        cold::StartupB0Domain::Player);
    const std::size_t audio_domain_index = static_cast<std::size_t>(
        cold::StartupB0Domain::Audio);
    const bool player_ready =
        g_startup_b0_session.domains[player_domain_index].ready;
    const bool audio_ready =
        g_startup_b0_session.domains[audio_domain_index].ready;
    const cold::StartupB0PlayerAudioPermanentFailure failure =
        ClassifyPlayerAudioB0PermanentFailure(
            player_ready, audio_ready);
    if (!cold::StartupB0StateRequiresOnFramePump(
            g_startup_b0_session.diagnostics.startup_b0_state) ||
        !cold::dluma_expire_unresolved_player_audio_b0_on_frame(
            &g_player_audio_b0_retry_gate, now_ms,
            sample.tick_source == cold::StartupB0TickSource::OnFrame &&
                sample.validated_frame_route,
            player_ready, audio_ready, failure))
        return false;

    BuildPlayerAudioB0PermanentFailureReason(
        g_player_audio_b0_retry_gate.permanent_failure,
        g_player_audio_b0_permanent_failure_reason,
        sizeof(g_player_audio_b0_permanent_failure_reason));
    const cold::StartupB0Domain failed_domain =
        !player_ready ? cold::StartupB0Domain::Player
                      : cold::StartupB0Domain::Audio;
    (void)cold::RecordStartupB0DomainResult(
        &g_startup_b0_session, failed_domain,
        cold::StartupB0DomainCaptureResult::PermanentFailure,
        cold::StartupB0Blocker::PermanentCaptureFailure,
        sample.sequence, g_startup_b0_session.session_generation, 0);
    g_component_status.baseline =
        ComponentRuntimeState::RuntimeFailed;
    g_component_status.frontend_cold_reboot =
        ComponentRuntimeState::RuntimeFailed;
    MarkContentDirty();
    return true;
}

bool CaptureProductionPlayerAbsentSnapshot(
    void* user, playerabsent::PlayerAbsentSnapshot* output) noexcept
{
    if (output) std::memset(output, 0, sizeof(*output));
    playerrestart::PlayerGameplayParamsRestartAdapter* adapter =
        static_cast<playerrestart::PlayerGameplayParamsRestartAdapter*>(
            user);
    playerrestart::PlayerGameplayParamsAbsentEvidence evidence = {};
    if (!output || adapter != &g_player_restart_adapter ||
        !playerrestart::CapturePlayerGameplayParamsAbsentEvidence(
            adapter, &evidence) ||
        !evidence.complete ||
        evidence.live_state_count >
            playerabsent::kPlayerAbsentOwnerCapacity ||
        !g_context.gamedll_base)
        return false;

    const std::uintptr_t local_slot =
        g_context.gamedll_base + kLocalPlayerStateGlobalRva;
    const std::uintptr_t character_slot =
        g_context.gamedll_base + kCharacterPlayerStateGlobalRva;
    if (local_slot < g_context.gamedll_base ||
        character_slot < g_context.gamedll_base)
        return false;
    for (std::uint32_t index = 0;
         index < evidence.live_state_count; ++index) {
        const playerrestart::PlayerStateInventoryRecord& source =
            evidence.live_states[index];
        playerabsent::PlayerAbsentOwnerRecord& destination =
            output->owners[index];
        destination.state = source.pointer;
        destination.generation = source.generation;
        destination.exact = source.live;
        if (source.owner_kind ==
                playerrestart::PlayerStateOwnerKind::
                    LocalProcessGlobal &&
            source.owner_object == local_slot &&
            evidence.environment.local_process_global_state ==
                source.pointer) {
            destination.owner_slot = local_slot;
            destination.kind =
                playerabsent::PlayerAbsentOwnerKind::
                    LocalProcessGlobal;
        } else if (source.owner_kind ==
                       playerrestart::PlayerStateOwnerKind::
                           CharacterManagerGlobal &&
                   source.owner_object == character_slot &&
                   evidence.environment.
                           character_manager_global_state ==
                       source.pointer) {
            destination.owner_slot = character_slot;
            destination.kind =
                playerabsent::PlayerAbsentOwnerKind::
                    CharacterManagerGlobal;
        } else {
            return false;
        }
    }
    output->owner_count = evidence.live_state_count;
    output->local_process_global_state =
        evidence.environment.local_process_global_state;
    output->character_manager_global_state =
        evidence.environment.character_manager_global_state;
    output->local_player_di = evidence.environment.local_player_di;
    output->active_session = evidence.environment.active_session;
    output->active_level = evidence.environment.active_level;
    output->inventory_revision = evidence.inventory_revision;
    output->gameplay_cache_fingerprint =
        evidence.environment.gameplay_cache_fingerprint;
    output->global_slots_readable =
        evidence.environment.global_owner_slots_readable;
    output->inventory_complete =
        evidence.environment.inventory_scan_complete;
    output->observer_loss = false;
    output->complete = true;
    return true;
}

bool CaptureProductionPlayerAbsentBaseline(
    std::uint64_t baseline_generation) noexcept
{
    _InterlockedIncrement(
        &g_player_audio_wiring_diagnostics.
            player_absent_b0_capture_attempt_count);
    const bool captured =
        playerabsent::CapturePlayerAbsentBaseline(
            &g_player_absent_reset_adapter,
            baseline_generation);
    if (!captured) {
        RecordPlayerAbsentB0FirstFailure(
            g_player_absent_reset_adapter.last_failure);
        return false;
    }
    _InterlockedIncrement(
        &g_player_audio_wiring_diagnostics.
            player_absent_b0_capture_success_count);
    _InterlockedExchange64(
        &g_player_audio_wiring_diagnostics.
            player_absent_b0_baseline_generation,
        static_cast<LONGLONG>(baseline_generation));
    _InterlockedExchange64(
        &g_player_audio_wiring_diagnostics.
            player_absent_b0_inventory_revision,
        static_cast<LONGLONG>(
            g_player_absent_reset_adapter.baseline.
                inventory_revision));
    _InterlockedExchange64(
        &g_player_audio_wiring_diagnostics.
            player_absent_b0_cache_fingerprint,
        static_cast<LONGLONG>(
            g_player_absent_reset_adapter.baseline.
                gameplay_cache_fingerprint));
    return true;
}

bool CaptureProductionAudioScriptRegistryForReload(
    void*,
    audiosemanticsnapshot::AudioScriptRegistrySemanticSnapshot* output)
    noexcept
{
    return CaptureAudioScriptSemanticSnapshot(output);
}

std::uint32_t AudioMinimumObservationActiveCallCount() noexcept
{
    HookStatusRecord* const statuses[] = {
        g_audio_script_load_status,
        g_audio_fmod_load_banks_status,
        g_sound_bank_manager_load_status,
    };
    std::uint32_t total = 0;
    for (HookStatusRecord* status : statuses) {
        if (!status || !status->installed)
            return UINT32_MAX;
        const LONG active = dluma_atomic_compare_exchange(
            &status->active_calls, 0, 0);
        if (active <= 0) continue;
        const std::uint32_t value =
            static_cast<std::uint32_t>(active);
        total = value > UINT32_MAX - total
            ? UINT32_MAX : total + value;
    }
    return total;
}

bool TryLockAudioMinimumOwnerPublication() noexcept
{
    return dluma_atomic_compare_exchange(
               &g_audio_minimum_owner_lock, 1, 0) == 0;
}

void UnlockAudioMinimumOwnerPublication() noexcept
{
    dluma_atomic_exchange(&g_audio_minimum_owner_lock, 0);
}

bool CaptureAudioMinimumOwnerIdentity(
    audiominimum::AudioMinimumOwnerIdentity* output) noexcept
{
    if (!output) return false;
    std::memset(output, 0, sizeof(*output));
    if (!TryLockAudioMinimumOwnerPublication())
        return false;
    const bool exact =
        audiominimum::SnapshotAudioMinimumOwnerIdentity(
            &g_audio_minimum_owner_publication, output);
    UnlockAudioMinimumOwnerPublication();
    return exact &&
        dluma_atomic_compare_exchange(
            &g_audio_minimum_owner_publication_loss, 0, 0) == 0;
}

void PublishAudioMinimumAudioOwner(
    void* audio_receiver) noexcept
{
    const std::uintptr_t audio =
        reinterpret_cast<std::uintptr_t>(audio_receiver);
    if (!audio || !g_audio_minimum_hooks_available ||
        !g_engine_full_profile_valid)
        return;
    std::uintptr_t vtable = 0;
    std::uintptr_t manager = 0;
    std::uintptr_t slot = 0;
    if (!CheckedPlayerAddressAdd(
            audio,
            audiosnapshot::kWindowsAudioFmodBankManagerOffset,
            &slot) ||
        !ReadBytes(audio, &vtable, sizeof(vtable)) ||
        vtable != g_context.engine_base +
            audiosnapshot::kWindowsAudioFmodVtableRva ||
        !ReadBytes(slot, &manager, sizeof(manager)) ||
        !manager)
        return;
    if (!TryLockAudioMinimumOwnerPublication()) {
        dluma_atomic_exchange(
            &g_audio_minimum_owner_publication_loss, 1);
        return;
    }
    (void)audiominimum::ObserveAudioMinimumAudioOwner(
        &g_audio_minimum_owner_publication,
        audio, manager, slot);
    UnlockAudioMinimumOwnerPublication();
}

void PublishAudioMinimumBankOwner(void* manager_receiver) noexcept
{
    const std::uintptr_t manager =
        reinterpret_cast<std::uintptr_t>(manager_receiver);
    if (!manager || !g_audio_minimum_hooks_available ||
        !g_engine_full_profile_valid)
        return;
    if (!TryLockAudioMinimumOwnerPublication()) {
        dluma_atomic_exchange(
            &g_audio_minimum_owner_publication_loss, 1);
        return;
    }
    (void)audiominimum::ObserveAudioMinimumBankOwner(
        &g_audio_minimum_owner_publication, manager);
    UnlockAudioMinimumOwnerPublication();
}

void PublishAudioMinimumOperationComplete() noexcept
{
    if (!g_audio_minimum_hooks_available ||
        !g_engine_full_profile_valid)
        return;
    if (!TryLockAudioMinimumOwnerPublication()) {
        dluma_atomic_exchange(
            &g_audio_minimum_owner_publication_loss, 1);
        return;
    }
    const bool completed =
        audiominimum::CompleteAudioMinimumOwnerOperation(
            &g_audio_minimum_owner_publication);
    UnlockAudioMinimumOwnerPublication();
    if (completed) {
        std::uint64_t event_fence = static_cast<std::uint64_t>(
            _InterlockedIncrement64(
                &g_audio_minimum_event_fence_generation));
        if (!event_fence)
            (void)_InterlockedIncrement64(
                &g_audio_minimum_event_fence_generation);
    }
}

bool ResolveAudioMinimumBankManagerUnderLock(
    const audiominimum::AudioMinimumOwnerIdentity& identity,
    std::uintptr_t* output) noexcept
{
    if (output) *output = 0;
    if (!output || !g_context.engine_base ||
        !identity.exact || identity.conflict)
        return false;
    std::uintptr_t audio = 0;
    std::uintptr_t vtable = 0;
    std::uintptr_t manager = 0;
    std::uintptr_t manager_slot = 0;
    if (!ReadBytes(
            g_context.engine_base +
                audiosnapshot::kWindowsAudioSingletonGlobalRva,
            &audio, sizeof(audio)) ||
        !audio ||
        audio != identity.audio_fmod_receiver ||
        !ReadBytes(audio, &vtable, sizeof(vtable)) ||
        vtable != g_context.engine_base +
            audiosnapshot::kWindowsAudioFmodVtableRva ||
        !CheckedPlayerAddressAdd(
            audio,
            audiosnapshot::kWindowsAudioFmodBankManagerOffset,
            &manager_slot) ||
        manager_slot != identity.singleton_or_owner_slot ||
        !ReadBytes(
            manager_slot,
            &manager, sizeof(manager)) ||
        !manager ||
        manager != identity.sound_bank_manager_receiver)
        return false;
    *output = manager;
    return true;
}

void MarkAudioScriptSnapshotSkipped(
    audiosemanticsnapshot::AudioScriptRegistrySemanticSnapshot* output,
    std::uint64_t reason) noexcept
{
    if (!output) return;
    std::memset(output, 0, sizeof(*output));
    output->skipped = true;
    output->failure_stage =
        audiosemanticsnapshot::AudioScriptSemanticStage::
            ContextValidation;
    output->reason_mask = reason;
}

void MarkAudioBankSnapshotSkipped(
    audiosemanticsnapshot::AudioBankTreeSemanticSnapshot* output,
    std::uint64_t reason) noexcept
{
    if (!output) return;
    std::memset(output, 0, sizeof(*output));
    output->skipped = true;
    output->failure_stage =
        audiosemanticsnapshot::AudioBankSemanticStage::
            ContextValidation;
    output->reason_mask = reason;
}

bool CaptureProductionAudioMinimumSemanticPair(
    audiominimum::AudioMinimumSemanticSnapshot* first,
    audiominimum::AudioMinimumSemanticSnapshot* second) noexcept
{
    if (first) std::memset(first, 0, sizeof(*first));
    if (second) std::memset(second, 0, sizeof(*second));
    if (!first || !second)
        return false;
    if (!g_audio_minimum_hooks_available ||
        !g_audio_baseline_layout_validated ||
        !g_engine_full_profile_valid ||
        !g_context.engine_base) {
        const std::uint64_t reason =
            !g_engine_full_profile_valid || !g_context.engine_base
                ? audiosemanticsnapshot::
                      AudioSemanticReasonUnsupportedImage
                : audiosemanticsnapshot::
                      AudioSemanticReasonAudioLockUnavailable;
        MarkAudioScriptSnapshotSkipped(&first->script, reason);
        MarkAudioBankSnapshotSkipped(&first->banks, reason);
        MarkAudioScriptSnapshotSkipped(&second->script, reason);
        MarkAudioBankSnapshotSkipped(&second->banks, reason);
        return false;
    }
    if (AudioMinimumObservationActiveCallCount() != 0U) {
        MarkAudioScriptSnapshotSkipped(
            &first->script,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        MarkAudioBankSnapshotSkipped(
            &first->banks,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        MarkAudioScriptSnapshotSkipped(
            &second->script,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        MarkAudioBankSnapshotSkipped(
            &second->banks,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        return false;
    }
    audiominimum::AudioMinimumOwnerIdentity owner_before = {};
    const bool owner_before_exact =
        CaptureAudioMinimumOwnerIdentity(&owner_before);
    const std::uint64_t revision_before =
        static_cast<std::uint64_t>(
            _InterlockedCompareExchange64(
                &g_audio_startup_observation_ledger.revision, 0, 0));
    if (!revision_before || !TryEnterAudioSemanticOwnerLock()) {
        MarkAudioScriptSnapshotSkipped(
            &first->script,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        MarkAudioBankSnapshotSkipped(
            &first->banks,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        MarkAudioScriptSnapshotSkipped(
            &second->script,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        MarkAudioBankSnapshotSkipped(
            &second->banks,
            audiosemanticsnapshot::
                AudioSemanticReasonAudioLockUnavailable);
        return false;
    }
    const audiosemanticsnapshot::AudioSemanticReadContext read =
        MakeAudioSemanticReadContext();
    std::uintptr_t manager = 0;
    const bool manager_resolved =
        owner_before_exact &&
        ResolveAudioMinimumBankManagerUnderLock(
            owner_before, &manager);
    const bool first_script_captured =
        audiosemanticsnapshot::
            SnapshotAudioScriptRegistrySemanticUnderLock(
                &read, &first->script);
    bool first_bank_captured = false;
    if (manager_resolved)
        first_bank_captured =
            audiosemanticsnapshot::
                SnapshotAudioBankTreeSemanticUnderLock(
                    &read, manager, nullptr, &first->banks);
    else
        MarkAudioBankSnapshotSkipped(
            &first->banks,
            audiosemanticsnapshot::AudioSemanticReasonHeaderInvalid);
    const bool second_script_captured =
        audiosemanticsnapshot::
            SnapshotAudioScriptRegistrySemanticUnderLock(
                &read, &second->script);
    bool second_bank_captured = false;
    if (manager_resolved)
        second_bank_captured =
            audiosemanticsnapshot::
                SnapshotAudioBankTreeSemanticUnderLock(
                    &read, manager, nullptr, &second->banks);
    else
        MarkAudioBankSnapshotSkipped(
            &second->banks,
            audiosemanticsnapshot::AudioSemanticReasonHeaderInvalid);
    LeaveAudioSemanticOwnerLock();
    audiominimum::AudioMinimumOwnerIdentity owner_after = {};
    const bool owner_after_exact =
        CaptureAudioMinimumOwnerIdentity(&owner_after);
    const std::uint64_t revision_after =
        static_cast<std::uint64_t>(
            _InterlockedCompareExchange64(
                &g_audio_startup_observation_ledger.revision, 0, 0));
    first->owner = owner_after;
    second->owner = owner_after;
    first->observer_revision = owner_after.observer_revision;
    second->observer_revision = owner_after.observer_revision;
    first->active_event_fence_generation =
        owner_after.event_fence_generation;
    second->active_event_fence_generation =
        owner_after.event_fence_generation;
    first->observer_revision_observed =
        owner_after.observer_revision_observed;
    second->observer_revision_observed =
        owner_after.observer_revision_observed;
    first->event_fence_generation_observed =
        owner_after.event_fence_generation_observed;
    second->event_fence_generation_observed =
        owner_after.event_fence_generation_observed;
    const bool stable =
        owner_before_exact && owner_after_exact &&
        audiominimum::AudioMinimumOwnerIdentitiesEqual(
            owner_before, owner_after) &&
        revision_before == revision_after &&
        AudioMinimumObservationActiveCallCount() == 0U;
    first->complete = stable && first_script_captured &&
        first_bank_captured;
    second->complete = stable && second_script_captured &&
        second_bank_captured;
    g_audio_minimum_owner_snapshot = owner_after;
    return first->complete && second->complete;
}

bool CaptureAudioSpeechRegistryEqualsBaseline() noexcept
{
    if (!g_audio_baseline_windows_snapshot.
            speech_owner_synchronization_proven ||
        !g_speech_registry_observation_available)
        return false;
    audiosnapshot::AudioBaselineWindowsSnapshot current = {};
    const audiosnapshot::AudioBaselineWindowsReadContext context = {
        g_context.engine_base,
        &ReadAudioBaselineMemory,
        &ReadAudioBaselineFence,
        &TryEnterAudioBaselineLock,
        &LeaveAudioBaselineLock,
        nullptr,
        true,
        true,
    };
    if (!audiosnapshot::SnapshotAudioBaselineWindows(
            &context, &current) ||
        !current.speech_owner_synchronization_proven ||
        current.speech_manager !=
            g_audio_baseline_windows_snapshot.speech_manager ||
        current.speech_bank_count !=
            g_audio_baseline_windows_snapshot.speech_bank_count ||
        current.speech_bank_manifest_fingerprint !=
            g_audio_baseline_windows_snapshot.
                speech_bank_manifest_fingerprint)
        return false;
    return std::memcmp(
               current.speech_banks,
               g_audio_baseline_windows_snapshot.speech_banks,
               sizeof(current.speech_banks)) == 0;
}

audiominimum::AudioMinimumOperationCoverage
CaptureAudioMinimumOperationCoverage(std::uint32_t epoch) noexcept
{
    audiominimum::AudioMinimumOperationCoverage coverage = {};
    coverage.minimum_hook_plan_complete =
        g_audio_minimum_hooks_available &&
        g_audio_baseline_layout_validated &&
        g_engine_full_profile_valid;
    coverage.event_fence_complete =
        AudioMinimumObservationActiveCallCount() == 0U;
    coverage.script_evidence_complete = true;
    coverage.bank_evidence_complete = true;
    coverage.bank_reference_evidence_complete = true;
    coverage.speech_evidence_complete = true;
    coverage.full_path_attribution_complete = true;
    coverage.observer_loss =
        dluma_atomic_compare_exchange(
            &g_audio_semantic_contention_loss, 0, 0) != 0;
    if (TryLockAudioSemanticDelta()) {
        const audiosemantic::AudioSemanticEpochEvidence& evidence =
            g_audio_semantic_delta_ledger.evidence;
        if (epoch && evidence.initialized &&
            evidence.epoch == epoch) {
            coverage.script_observation_count =
                evidence.script_observation_count;
            coverage.bank_observation_count =
                evidence.bank_observation_count;
            coverage.speech_observation_count =
                evidence.speech_observation_count;
            coverage.script_evidence_complete =
                (evidence.reason_mask &
                 audiosemantic::
                     AudioSemanticDeltaReasonScriptEvidenceIncomplete) ==
                0U;
            coverage.bank_evidence_complete =
                (evidence.reason_mask &
                 audiosemantic::
                     AudioSemanticDeltaReasonBankEvidenceIncomplete) ==
                0U;
            coverage.bank_reference_evidence_complete =
                !evidence.bank_reference_evidence_incomplete;
            coverage.bank_reference_delta_detected =
                evidence.bank_reference_delta;
            coverage.speech_evidence_complete =
                !evidence.speech_evidence_incomplete;
            coverage.full_path_attribution_required =
                evidence.full_path_attribution_required;
            coverage.full_path_attribution_complete =
                !evidence.full_path_attribution_incomplete;
            coverage.observer_loss = coverage.observer_loss ||
                evidence.observation_loss;
        } else if (epoch && evidence.initialized &&
                   !evidence.assessed) {
            coverage.observer_loss = true;
        }
        UnlockAudioSemanticDelta();
    } else {
        coverage.observer_loss = true;
    }
    if (coverage.speech_observation_count != 0U)
        coverage.speech_evidence_complete =
            coverage.speech_evidence_complete &&
            CaptureAudioSpeechRegistryEqualsBaseline();
    coverage.exact_release_available =
        audio::IsDestructiveAdapterAvailable(&g_audio_reset);
    coverage.baseline_replay_available =
        coverage.exact_release_available;
    return coverage;
}

bool CaptureProductionAudioMinimumBaseline(
    std::uint64_t baseline_generation) noexcept
{
    if (g_audio_minimum_semantic_state.baseline_captured)
        return g_audio_minimum_semantic_state.baseline.
            baseline_generation == baseline_generation;
    _InterlockedIncrement(
        &g_player_audio_wiring_diagnostics.
            audio_minimum_b0_capture_attempt_count);
    audiominimum::AudioMinimumSemanticSnapshot first = {};
    audiominimum::AudioMinimumSemanticSnapshot second = {};
    audiominimum::AudioMinimumOperationCoverage coverage =
        CaptureAudioMinimumOperationCoverage(0);
    coverage.script_observation_count = 0;
    coverage.bank_observation_count = 0;
    coverage.speech_observation_count = 0;
    coverage.script_evidence_complete = true;
    coverage.bank_evidence_complete = true;
    coverage.bank_reference_evidence_complete = true;
    coverage.bank_reference_delta_detected = false;
    coverage.speech_evidence_complete = true;
    const bool pair_captured =
        CaptureProductionAudioMinimumSemanticPair(
            &first, &second);
    first.baseline_generation = baseline_generation;
    second.baseline_generation = baseline_generation;
    g_audio_minimum_last_first = first;
    g_audio_minimum_last_second = second;
    g_audio_minimum_b0_first = first;
    g_audio_minimum_b0_second = second;
    if (!pair_captured) {
        RecordFirstAudioB0FailureDiagnostics();
        const ProductionAudioMinimumB0Failure failure =
            !g_audio_minimum_hooks_available ||
                    !g_audio_baseline_layout_validated ||
                    !g_engine_full_profile_valid
                ? ProductionAudioMinimumB0Failure::
                      MinimumHookPlanIncomplete
                : AudioMinimumObservationActiveCallCount() != 0U
                    ? ProductionAudioMinimumB0Failure::
                          ObservationActive
                    : ProductionAudioMinimumB0Failure::
                          SemanticPairIncomplete;
        RecordAudioMinimumB0FirstFailure(failure);
        return false;
    }
    if (!audiominimum::CaptureAudioMinimumSemanticBaseline(
            &g_audio_minimum_semantic_state,
            baseline_generation, first, second, coverage)) {
        RecordAudioMinimumB0FirstFailure(
            ProductionAudioMinimumB0Failure::
                BaselineCommitRejected);
        return false;
    }
    (void)audioscriptreload::CaptureAudioScriptReloadBaseline(
        &g_audio_script_reload_adapter, baseline_generation,
        g_audio_minimum_semantic_state.baseline.script);
    _InterlockedIncrement(
        &g_player_audio_wiring_diagnostics.
            audio_minimum_b0_capture_success_count);
    _InterlockedExchange64(
        &g_player_audio_wiring_diagnostics.
            audio_minimum_b0_baseline_generation,
        static_cast<LONGLONG>(baseline_generation));
    _InterlockedExchange64(
        &g_player_audio_wiring_diagnostics.
            audio_minimum_b0_observer_revision,
        static_cast<LONGLONG>(
            g_audio_minimum_semantic_state.baseline.
                observer_revision));
    _InterlockedExchange64(
        &g_player_audio_wiring_diagnostics.
            audio_minimum_b0_event_fence_generation,
        static_cast<LONGLONG>(
            g_audio_minimum_semantic_state.baseline.
                active_event_fence_generation));
    return true;
}

audiominimum::AudioMinimumAssessment
AssessProductionAudioMinimumAtResetBoundary(
    std::uint64_t baseline_generation, std::uint32_t epoch) noexcept
{
    audiominimum::AudioMinimumSemanticSnapshot first = {};
    audiominimum::AudioMinimumSemanticSnapshot second = {};
    audiominimum::AudioMinimumOperationCoverage coverage =
        CaptureAudioMinimumOperationCoverage(epoch);
    if (!CaptureProductionAudioMinimumSemanticPair(&first, &second)) {
        first.complete = false;
        second.complete = false;
    }
    first.baseline_generation = baseline_generation;
    second.baseline_generation = baseline_generation;
    g_audio_minimum_last_first = first;
    g_audio_minimum_last_second = second;
    g_last_audio_minimum_assessment =
        audiominimum::AssessAudioMinimumSemanticState(
            &g_audio_minimum_semantic_state,
            baseline_generation, first, second, coverage);
    return g_last_audio_minimum_assessment;
}

bool TryLockAudioSemanticDelta() noexcept
{
    return dluma_atomic_compare_exchange(
               &g_audio_semantic_delta_lock, 1, 0) == 0;
}

void UnlockAudioSemanticDelta() noexcept
{
    dluma_atomic_exchange(&g_audio_semantic_delta_lock, 0);
}

void RecordAudioSemanticScript(
    const audiosemantic::AudioSemanticScriptObservation& observation)
    noexcept
{
    if (!observation.epoch) return;
    if (g_audio_replay_invocation && g_audio_replay_invocation->actual()) return;
    if (!TryLockAudioSemanticDelta()) {
        dluma_atomic_exchange(
            &g_audio_semantic_contention_loss, 1);
        return;
    }
    if (!audiosemantic::RecordAudioSemanticScriptObservation(
            &g_audio_semantic_delta_ledger, observation))
        dluma_atomic_exchange(
            &g_audio_semantic_contention_loss, 1);
    UnlockAudioSemanticDelta();
}

void RecordAudioSemanticBank(
    const audiosemantic::AudioSemanticBankObservation& observation)
    noexcept
{
    if (!observation.epoch) return;
    if (g_audio_replay_invocation && g_audio_replay_invocation->actual()) return;
    if (!TryLockAudioSemanticDelta()) {
        dluma_atomic_exchange(
            &g_audio_semantic_contention_loss, 1);
        return;
    }
    if (!audiosemantic::RecordAudioSemanticBankObservation(
            &g_audio_semantic_delta_ledger, observation))
        dluma_atomic_exchange(
            &g_audio_semantic_contention_loss, 1);
    UnlockAudioSemanticDelta();
}

void RecordAudioSemanticSpeech(
    std::uint32_t epoch, bool evidence_complete) noexcept
{
    if (!epoch) return;
    if (g_audio_replay_invocation && g_audio_replay_invocation->actual()) return;
    if (!TryLockAudioSemanticDelta()) {
        dluma_atomic_exchange(
            &g_audio_semantic_contention_loss, 1);
        return;
    }
    if (!audiosemantic::RecordAudioSemanticSpeechObservation(
            &g_audio_semantic_delta_ledger, epoch,
            evidence_complete))
        dluma_atomic_exchange(
            &g_audio_semantic_contention_loss, 1);
    UnlockAudioSemanticDelta();
}

audiosemantic::AudioSemanticEpochAssessment
AssessAudioSemanticTouchAtResetBoundary(std::uint32_t epoch) noexcept
{
    audiosemantic::AudioSemanticEpochAssessment result = {};
    result.disposition =
        audiosemantic::AudioSemanticEpochDisposition::Incomplete;
    result.epoch = epoch;
    const bool hook_plan_complete =
        g_audio_touch_hooks_available &&
        g_audio_baseline_layout_validated &&
        g_engine_full_profile_valid;
    result.hook_plan_complete = hook_plan_complete;
    if (!TryLockAudioSemanticDelta()) {
        result.reason_mask =
            audiosemantic::AudioSemanticDeltaReasonObservationLoss;
        dluma_atomic_exchange(
            &g_audio_semantic_contention_loss, 1);
        return result;
    }
    if (dluma_atomic_compare_exchange(
            &g_audio_semantic_contention_loss, 0, 0) != 0)
        (void)audiosemantic::RecordAudioSemanticObservationLoss(
            &g_audio_semantic_delta_ledger, epoch,
            audiosemantic::
                AudioSemanticDeltaReasonObservationLoss);
    result = audiosemantic::AssessAudioSemanticEpoch(
        &g_audio_semantic_delta_ledger, epoch,
        hook_plan_complete);
    g_last_audio_semantic_assessment = result;
    UnlockAudioSemanticDelta();
    return result;
}

enum class StartupAudioCaptureResult : std::uint8_t {
    NotAttempted,
    Retry,
    TerminalIncomplete,
    ObservationalCaptured,
};

enum class CommittedSourceRegistryFenceResult : std::uint8_t {
    Stable,
    NotReady,
    Busy,
    Changed,
};

CommittedSourceRegistryFenceResult SampleCommittedSourceRegistryFence()
    noexcept
{
    if (dluma_atomic_compare_exchange(
            &g_startup_vfs_inventory_ready, 0, 0) == 0 ||
        !g_startup_filesystem_inventory.complete ||
        !g_startup_filesystem_inventory.registry_generation_observed)
        return CommittedSourceRegistryFenceResult::NotReady;
    const std::uint64_t committed = static_cast<std::uint64_t>(
        _InterlockedCompareExchange64(
            &g_startup_vfs_registry_generation, 0, 0));
    const std::uint64_t before = ReadSourceRegistryGeneration();
    const LONG active = dluma_atomic_compare_exchange(
        &g_source_registry_active_calls, 0, 0);
    const std::uint64_t after = ReadSourceRegistryGeneration();
    if (active != 0)
        return CommittedSourceRegistryFenceResult::Busy;
    if (before != after || after != committed ||
        g_startup_filesystem_inventory.registry_generation != committed)
        return CommittedSourceRegistryFenceResult::Changed;
    return CommittedSourceRegistryFenceResult::Stable;
}

const char* StartupAudioCaptureResultName(
    StartupAudioCaptureResult result) noexcept
{
    switch (result) {
    case StartupAudioCaptureResult::NotAttempted:
        return "not_attempted";
    case StartupAudioCaptureResult::Retry:
        return "retry";
    case StartupAudioCaptureResult::TerminalIncomplete:
        return "terminal_incomplete";
    case StartupAudioCaptureResult::ObservationalCaptured:
        return "observational_captured";
    default: return "unknown";
    }
}

StartupAudioCaptureResult CaptureStartupAudioRawInventory() noexcept
{
    std::memset(&g_audio_baseline_windows_snapshot, 0,
                sizeof(g_audio_baseline_windows_snapshot));
    std::memset(&g_audio_startup_baseline_staging, 0,
                sizeof(g_audio_startup_baseline_staging));
    std::memset(&g_audio_startup_observation_snapshot, 0,
                sizeof(g_audio_startup_observation_snapshot));
    g_speech_registry_snapshot_completion_failed = false;
    if (!g_audio_trace_available || !g_audio_baseline_layout_validated ||
        !g_engine_full_profile_valid)
        return StartupAudioCaptureResult::TerminalIncomplete;
    const CommittedSourceRegistryFenceResult source_fence_before =
        SampleCommittedSourceRegistryFence();
    if (source_fence_before !=
        CommittedSourceRegistryFenceResult::Stable)
        return source_fence_before ==
                       CommittedSourceRegistryFenceResult::NotReady ||
                   source_fence_before ==
                       CommittedSourceRegistryFenceResult::Busy
            ? StartupAudioCaptureResult::Retry
            : StartupAudioCaptureResult::TerminalIncomplete;

    const audiosnapshot::AudioBaselineWindowsReadContext context = {
        g_context.engine_base,
        &ReadAudioBaselineMemory,
        &ReadAudioBaselineFence,
        &TryEnterAudioBaselineLock,
        &LeaveAudioBaselineLock,
        nullptr,
        true,
        g_speech_registry_observation_available,
    };
    const bool authorized_snapshot_complete =
        audiosnapshot::SnapshotAudioBaselineWindows(
            &context, &g_audio_baseline_windows_snapshot);
    if (!audiostart::CaptureAudioStartupObservationSnapshot(
            &g_audio_startup_observation_ledger,
            &g_audio_startup_observation_snapshot))
        return StartupAudioCaptureResult::Retry;

    const std::uint64_t retry_reasons =
        audiosnapshot::AudioWindowsReasonFenceUnavailable |
        audiosnapshot::AudioWindowsReasonObserverBusy |
        audiosnapshot::AudioWindowsReasonAudioLockBusy |
        audiosnapshot::AudioWindowsReasonAudioSingletonUnavailable |
        audiosnapshot::AudioWindowsReasonGameUnavailable |
        audiosnapshot::AudioWindowsReasonSpeechManagerUnavailable |
        audiosnapshot::AudioWindowsReasonSnapshotChanged |
        audiosnapshot::AudioWindowsReasonFenceChanged |
        audiosnapshot::AudioWindowsReasonSpeechVectorChanged;
    if (!authorized_snapshot_complete)
        return (g_audio_baseline_windows_snapshot.reason_mask &
                retry_reasons) != 0
            ? StartupAudioCaptureResult::Retry
            : StartupAudioCaptureResult::TerminalIncomplete;
    if (g_audio_startup_observation_snapshot.revision !=
        g_audio_baseline_windows_snapshot.observation_revision)
        return StartupAudioCaptureResult::Retry;

    const bool reconciled =
        audioreconcile::ReconcileAudioStartupBaseline(
            &g_audio_baseline_windows_snapshot,
            &g_audio_startup_observation_snapshot,
            &g_startup_filesystem_inventory,
            &g_audio_startup_baseline_staging);
    audiosnapshot::AudioBaselineWindowsObservationFence final_fence = {};
    if (!ReadAudioBaselineFence(nullptr, &final_fence) ||
        final_fence.active_calls != 0U ||
        final_fence.revision !=
            g_audio_startup_observation_snapshot.revision)
        return StartupAudioCaptureResult::Retry;
    if (final_fence.observation_loss)
        return StartupAudioCaptureResult::TerminalIncomplete;
    const CommittedSourceRegistryFenceResult source_fence_after =
        SampleCommittedSourceRegistryFence();
    if (source_fence_after !=
        CommittedSourceRegistryFenceResult::Stable)
        return source_fence_after ==
                       CommittedSourceRegistryFenceResult::Busy
            ? StartupAudioCaptureResult::Retry
            : StartupAudioCaptureResult::TerminalIncomplete;
    if (!reconciled)
        return StartupAudioCaptureResult::TerminalIncomplete;

    /* This production milestone has no observation seal spanning the final
     * fence through publication and no complete replay owner.  The isolated
     * reconciler is therefore observational only: an unexpected authority
     * claim is rejected instead of entering FrontendBaseline. */
    if (g_audio_startup_baseline_staging.authoritative_b0_complete ||
        g_audio_startup_baseline_staging.reset_ready ||
        g_audio_startup_baseline_staging.reset_owner_proven)
        return StartupAudioCaptureResult::TerminalIncomplete;
    return StartupAudioCaptureResult::ObservationalCaptured;
}

bool ReadAudioSoundPropertyFence(void*, audio_sound_properties::Fence* output) noexcept
{
    if (!output || !g_audio_property_read_lock_owned || !g_engine_full_profile_valid) return false;
    audiominimum::AudioMinimumOwnerIdentity owner = {};
    audiosnapshot::AudioBaselineWindowsObservationFence observed = {};
    if (!CaptureAudioMinimumOwnerIdentity(&owner) || !owner.exact || owner.conflict ||
        !ReadAudioBaselineFence(nullptr, &observed) || observed.active_calls || observed.observation_loss)
        return false;
    std::uintptr_t lifetime_owner = 0;
    std::uint64_t lifetime_generation = 0;
    if (!ReadCurrentAudioOwnerLifetime(&lifetime_owner, &lifetime_generation) ||
        lifetime_owner != owner.audio_fmod_receiver) return false;
    *output = {};
    output->audio_owner = owner.audio_fmod_receiver;
    output->owner_generation = lifetime_generation;
    output->revision = observed.revision;
    output->thread_id = GetCurrentThreadId();
    output->sound_lock_owned = true;
    // This callback attests observational capture only. A destructive native
    // binding must use the separately qualified Audio owner/borrower fence.
    return true;
}

bool ReadProductionAudioSpeechFence(void*,audio_speech_consumers::Fence*) noexcept;
bool CaptureProductionAudioBusesBaseline(std::uint64_t generation) noexcept;
bool CaptureProductionAudioSoundProperties(std::uint64_t generation) noexcept
{
    namespace properties = audio_sound_properties;
    if (!CaptureProductionAudioBusesBaseline(generation)) return false;
    if (g_audio_property_baseline_generation)
        return g_audio_property_baseline_generation == generation && g_audio_property_baseline.complete;
    if (!generation || content::CurrentEpochId(&g_content_ledger) ||
        dluma_atomic_compare_exchange(&g_startup_b0_custom_staging_seen, 0, 0)) return false;
    if (!g_audio_property_baseline.properties) {
        constexpr std::size_t properties_bytes = properties::kMaximumProperties * sizeof(properties::Property);
        constexpr std::size_t aliases_bytes = properties::kMaximumAliases * sizeof(properties::Alias);
        constexpr std::size_t common_bytes = 65536U * sizeof(properties::CommonBorrower);
        constexpr std::size_t stride = properties_bytes + aliases_bytes + common_bytes;
        auto* storage = static_cast<unsigned char*>(VirtualAlloc(nullptr,
            2U * stride, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE));
        if (!storage) return false;
        auto& baseline = g_audio_property_baseline;
        baseline.properties = reinterpret_cast<properties::Property*>(storage);
        baseline.aliases = reinterpret_cast<properties::Alias*>(storage + properties_bytes);
        baseline.property_capacity = properties::kMaximumProperties;
        baseline.alias_capacity = properties::kMaximumAliases;
        g_audio_common_baseline = reinterpret_cast<properties::CommonBorrower*>(storage + properties_bytes + aliases_bytes);
        g_audio_property_scratch = baseline;
        g_audio_property_scratch.properties = reinterpret_cast<properties::Property*>(storage + stride);
        g_audio_property_scratch.aliases = reinterpret_cast<properties::Alias*>(storage + stride + properties_bytes);
        g_audio_common_scratch = reinterpret_cast<properties::CommonBorrower*>(storage + stride + properties_bytes + aliases_bytes);
    }
    if (!TryEnterAudioBaselineLock(nullptr)) return false;
    g_audio_property_read_lock_owned = true;
    const properties::Access access = {nullptr, &ReadAudioBaselineMemory,
        &ReadAudioSoundPropertyFence, g_context.engine_base};
    const audio_speech_consumers::Access speech_access = {g_context.engine_base,
        &ReadAudioBaselineMemory,&ReadProductionAudioSpeechFence,nullptr,g_engine_full_profile_valid};
    const bool captured = properties::CaptureReadOnly(access, &g_audio_property_baseline) == properties::Result::Succeeded &&
        properties::CaptureCommonBorrowers(access, g_audio_property_baseline, g_audio_common_baseline,
            65536U, &g_audio_common_baseline_count) == properties::Result::Succeeded &&
        audio_speech_consumers::Capture(speech_access,&g_audio_speech_consumer_baseline) == audio_speech_consumers::Result::Succeeded;
    g_audio_property_read_lock_owned = false;
    LeaveAudioBaselineLock(nullptr);
    if (captured) g_audio_property_baseline_generation = generation;
    return captured;
}

bool AdvanceFrozenAudioBaselineContent(std::uint64_t baseline_generation) noexcept
{
    using namespace audio_baseline_content;
    auto& capture = g_audio_baseline_content;
    if (!baseline_generation || capture.baseline_generation != baseline_generation ||
        !capture.frozen_revision || g_audio_property_baseline_generation != baseline_generation) return false;
    const auto phase = Step(&capture, 2ULL * 1024ULL * 1024ULL * 1024ULL);
    if (phase != Phase::ContentCaptured) return false;
    // Only frozen startup observations and naturally pinned original bytes
    // are read here. Project/menu state cannot replace any baseline input.
    return capture.inventory_joined ? AllBankContentHeld(capture) :
        Join(&capture, g_audio_startup_observation_snapshot, g_audio_baseline_windows_snapshot);
}

bool AdvanceProductionAudioBaselineContent(std::uint64_t baseline_generation) noexcept
{
    using namespace audio_baseline_content;
    // Called from the qualified clean startup owner on cooperative ticks.
    // A later menu must never replace any frozen startup snapshot or pin.
    if (!baseline_generation || content::CurrentEpochId(&g_content_ledger) ||
        dluma_atomic_compare_exchange(&g_startup_b0_custom_staging_seen, 0, 0) ||
        !g_audio_baseline_windows_snapshot.raw_snapshot_complete ||
        !g_audio_startup_baseline_staging.fully_reconciled_observational_inventory)
        return false;
    audiosnapshot::AudioBaselineWindowsObservationFence fence = {};
    if (!ReadAudioBaselineFence(nullptr, &fence) || fence.active_calls || fence.observation_loss ||
        fence.revision != g_audio_startup_observation_snapshot.revision ||
        SampleCommittedSourceRegistryFence() != CommittedSourceRegistryFenceResult::Stable)
        return false;
    if (!CaptureProductionAudioSoundProperties(baseline_generation)) return false;
    auto& capture = g_audio_baseline_content;
    auto phase = static_cast<Phase>(dluma_atomic_compare_exchange(&capture.phase, 0, 0));
    // The raw tree holds addresses. Join them to the current immutable native
    // file-generation observations before those addresses authorize B0.
    for (std::uint32_t i = 0; i < g_audio_baseline_windows_snapshot.bank_count; ++i) {
        const auto& bank = g_audio_baseline_windows_snapshot.banks[i];
        file_lifetime::FileRecord current = {};
        if (!filebridge::FileIdentity(&g_native_file_bridge, bank.native_file, &current)) return false;
        bool joined = false;
        const LONG count = dluma_atomic_compare_exchange(&capture.count, 0, 0);
        for (LONG j = 0; j < count && static_cast<std::size_t>(j) < kBanks; ++j) {
            const auto& pin = capture.banks[j];
            if (dluma_atomic_compare_exchange(const_cast<volatile LONG*>(&pin.published), 0, 0) != 1) return false;
            if (pin.natural.kind == speechlease::NativeBankFile::Fmod &&
                pin.natural.file.file == bank.native_file && pin.natural.file.generation == current.generation)
                joined = true;
        }
        if (!joined) return false;
    }
    if (phase == Phase::Observing &&
        (!audiostart::SealAudioStartupObservationLedger(&g_audio_startup_observation_ledger,
            &g_audio_runtime_observation_ledger, fence.revision) ||
         !Freeze(&capture, baseline_generation, fence.revision))) return false;
    return AdvanceFrozenAudioBaselineContent(baseline_generation);
}

bool ExactIsolationStartupOwnerAbsence() noexcept
{
    DlumaIsolationScriptEntryObservation observed = {};
    if (!dluma_isolation_snapshot_script_entry(&observed) ||
        observed.thread_id != GetCurrentThreadId() ||
        reinterpret_cast<std::uintptr_t>(observed.return_address) != g_context.engine_base + 0x24B9ABU)
        return false;
    std::uintptr_t callback = 0;
    if (!ReadBytes(g_context.engine_base + 0xACCC58U, &callback, sizeof(callback)) ||
        callback != reinterpret_cast<std::uintptr_t>(observed.callback_address)) return false;
    static const std::uintptr_t absent_owners[] = {0xACA818U, 0xACCC68U, 0xACCC70U};
    for (const auto rva : absent_owners) {
        std::uintptr_t owner = 1;
        if (!ReadBytes(g_context.engine_base + rva, &owner, sizeof(owner)) || owner) return false;
    }
    return true;
}

bool ReadProductionCurveContext(void*, curves::CurveGatewayContext* out) noexcept
{
    if (!out || !g_gamedll_full_profile_valid || g_dluma.stop_requested) return false;
    std::memset(out, 0, sizeof(*out));
    if (!content::TryGetCurrentEpochId(&g_content_ledger, &out->epoch)) return false;
    out->startup_owner_absence = g_curve_startup_install_scope && ExactIsolationStartupOwnerAbsence();
    if (out->startup_owner_absence) return out->epoch == 0;
    if (!dluma_engine_snapshot_game_frame_authority(&g_dluma.engine, &out->authority)) return false;
    const cold::RestartContext* callback = nullptr;
    cold::ContentDomainId callback_domain = cold::ContentDomainId::Count;
    cold::RestartPhase callback_phase = cold::RestartPhase::Idle;
    if (cold::SnapshotRegistryCallbackContext(&g_cold_reboot_registry,
            &callback, &callback_domain, &callback_phase) &&
        callback->content_epoch == out->epoch)
        out->transaction = callback->transaction_generation;
    const auto& scope = g_cold_reboot_state_five_scope;
    std::uint32_t state = 0;
    SerializedFrameRouteEvidence frame = {};
    out->post_c10_consumers_closed = out->epoch && out->transaction &&
        scope.active && scope.armed && scope.on_destroy_claimed && scope.post_c10_token_consumed &&
        scope.barrier_attempted && !scope.runtime_failed && scope.epoch == out->epoch &&
        scope.c10_callback_thread_id == GetCurrentThreadId() && g_project_callbacks_drained &&
        g_project_map_exit_key.project_epoch == out->epoch &&
        ReadGameDiState(scope.game_di, &state) && state == 5U &&
        ReadGameDiCurrentSession(scope.game_di) == nullptr && FindLiveCustomPlayerOwner() == nullptr &&
        CurrentSerializedGameFrameRouteMatches(scope.frame_route_token, GetCurrentThreadId(), &frame) ==
            statefive::RejectReason::C10ScopeMatched && !ColdRebootNextProjectStagingStarted();
    return true;
}

void ObservePotentialNativeDomainWrite(cold::ContentDomainId domain) noexcept
{
    std::uint32_t epoch = 0;
    if (!ContentTrackingLive()) return;
    const bool known_epoch = content::TryGetCurrentEpochId(&g_content_ledger, &epoch);
    if (known_epoch && !epoch) return;
    // Requirement selection is independent of source attribution. An ambiguous
    // producer must not hide the domain by failing filename correlation.
    /* Keep native writer evidence separate from the registry's resulting mask.
     * BF8 reconciles this independent observation, not a copy of the mask it
     * is supposed to verify. It remains conservative across later epochs. */
    _InterlockedOr(&g_native_observed_domain_touch_mask,
        static_cast<LONG>(cold::DomainBit(domain)));
    (void)cold::MarkDomainTouched(&g_cold_reboot_registry, domain);
}

void ObserveProductionCurveWrite(void*, curves::CurveHook hook) noexcept
{
    ObservePotentialNativeDomainWrite(cold::ContentDomainId::Curves);
    if (curves::IsItemDefinitionHook(hook))
        ObservePotentialNativeDomainWrite(cold::ContentDomainId::ItemDefinitions);
}

using NativeFactoryReplayResolverFn = bool(*)(void*, const filebridge::FactoryRequest&,
    cold::ReplayOperationIdentity*) noexcept;
struct NativeFactoryReplayResolver {
    cold::ContentDomainId domain;
    NativeFactoryReplayResolverFn resolve;
    void* user;
};
NativeFactoryReplayResolver g_native_factory_resolvers[cold::kMaximumContentDomainAdapters] = {};
std::size_t g_native_factory_resolver_count;
bool g_native_factory_resolvers_sealed;
thread_local bool g_native_factory_resolution_active;

bool RegisterProductionFactoryReplayResolver(cold::ContentDomainId domain,
    NativeFactoryReplayResolverFn resolve, void* user) noexcept
{
    if (!resolve || g_native_factory_resolvers_sealed ||
        static_cast<unsigned>(domain) >= static_cast<unsigned>(cold::ContentDomainId::Count) ||
        domain == cold::ContentDomainId::VfsSources || domain == cold::ContentDomainId::FrontendVerification ||
        domain == cold::ContentDomainId::UnclassifiedPersistentConsumers) return false;
    for (std::size_t i = 0; i < g_native_factory_resolver_count; ++i)
        if (g_native_factory_resolvers[i].domain == domain)
            return g_native_factory_resolvers[i].resolve == resolve && g_native_factory_resolvers[i].user == user;
    if (g_native_factory_resolver_count == sizeof(g_native_factory_resolvers)/sizeof(g_native_factory_resolvers[0])) return false;
    g_native_factory_resolvers[g_native_factory_resolver_count++] = {domain, resolve, user};
    return true;
}

bool ValidateProductionFactoryReplayAuthorization(void*, const files::FactoryReplayAuthorization& value) noexcept
{
    const cold::ReplayFileAuthority authority = {value.authority, value.authority_generation,
        value.observation, value.transaction, value.epoch, value.thread_id};
    return cold::ValidateReplayFileAuthority(&g_cold_reboot_registry, &authority);
}

bool AuthorizeProductionReplayFactory(void*, const filebridge::FactoryRequest& request,
    files::FactoryReplayAuthorization* output) noexcept
{
    if (output) *output = {};
    if (!output || g_native_factory_resolution_active) return false;
    // Matchers may read their already-qualified native scope and immutable
    // input evidence. They must not open another native file to manufacture it.
    for (std::size_t i = 0; i < g_native_factory_resolver_count; ++i) {
        const auto& resolver = g_native_factory_resolvers[i];
        cold::RegistryReplayPermitToken permit = {};
        if (!cold::CurrentRegistryReplayPermit(&g_cold_reboot_registry, resolver.domain, &permit)) continue;
        cold::ReplayOperationIdentity actual = {};
        g_native_factory_resolution_active = true;
        const bool matched = resolver.resolve(resolver.user, request, &actual);
        g_native_factory_resolution_active = false;
        if (!matched || actual.domain != resolver.domain ||
            actual.identity_kind != cold::ReplayIdentityKind::FileContent) return false;
        cold::ReplayFileAuthority authority = {};
        if (!cold::CaptureReplayFileAuthority(&g_cold_reboot_registry, &actual, &authority)) return false;
        *output = {authority.registry_identity, authority.permit_generation, authority.observation,
            authority.transaction_generation, authority.content_epoch, authority.owner_thread_id};
        return true;
    }
    return false;
}

bool AllocateCurveOwnerStorage() noexcept
{
    if (g_curve_owner.baseline.records) return true;
    constexpr std::size_t record_bytes = curves::kMaximumCurves * sizeof(curves::CurveRecord);
    constexpr std::size_t snapshot_bytes = record_bytes + curves::kMaximumCurveStorage;
    auto* storage = static_cast<std::uint8_t*>(VirtualAlloc(nullptr, snapshot_bytes * 2,
        MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE));
    if (!storage) return false;
    curves::CurveSnapshot baseline = {}, current = {};
    baseline.records = reinterpret_cast<curves::CurveRecord*>(storage);
    baseline.record_capacity = curves::kMaximumCurves;
    baseline.storage = storage + record_bytes;
    baseline.storage_capacity = curves::kMaximumCurveStorage;
    current = baseline;
    current.records = reinterpret_cast<curves::CurveRecord*>(storage + snapshot_bytes);
    current.storage = storage + snapshot_bytes + record_bytes;
    const curves::CurveOwnerOperations operations = {&g_curve_gateway,
        &curves::NativeCurveCompareWrite, &curves::NativeCurveDelete, &g_curve_gateway};
    if (!curves::InitializeCurveOwner(&g_curve_owner, &operations, &baseline, &current)) {
        VirtualFree(storage, 0, MEM_RELEASE); return false;
    }
    return true;
}

cold::DomainResult ColdCurvesBaseline(void*, const cold::RestartContext* context) noexcept
{
    if (!context || !context->baseline_generation || !g_curve_hooks_available ||
        context->owner_thread_id != GetCurrentThreadId() ||
        context->baseline_generation != g_startup_b0_session.session_generation ||
        content::CurrentEpochId(&g_content_ledger) ||
        dluma_atomic_compare_exchange(&g_startup_b0_custom_staging_seen, 0, 0))
        return cold::DomainResult::Unsupported;
    if (g_curve_owner.baseline_captured)
        return context->baseline_generation == g_curve_baseline_generation
            ? cold::DomainResult::Succeeded : cold::DomainResult::Failed;
    if (!g_startup_filesystem_inventory.complete ||
        g_startup_filesystem_inventory.source_count > vfs::kFilesystemSourceInventoryCapacity)
        return cold::DomainResult::Unsupported;
    g_curve_baseline_source_count = 0;
    for (std::size_t i = 0; i < g_startup_filesystem_inventory.source_count; ++i) {
        files::SourceKey key = {};
        if (!filebridge::SourceIdentity(&g_native_file_bridge,
                g_startup_filesystem_inventory.sources[i].source, &key))
            return cold::DomainResult::Unsupported;
        g_curve_baseline_source_keys[g_curve_baseline_source_count++] = key;
    }
    if (!AllocateCurveOwnerStorage()) return cold::DomainResult::Failed;
    if (curves::CaptureCurveOwnerBaseline(&g_curve_owner) != curves::CurveOwnerResult::Succeeded)
        return cold::DomainResult::Unsupported;
    g_curve_baseline_generation = context->baseline_generation;
    return cold::DomainResult::Succeeded;
}

bool ProductionDomainTransactionMatches(const cold::RestartContext* context,
    cold::ContentDomainId expected_domain) noexcept
{
    const cold::RestartContext* actual = nullptr;
    cold::ContentDomainId domain = cold::ContentDomainId::Count;
    cold::RestartPhase phase = cold::RestartPhase::Idle;
    if (!context || !context->transaction_generation || !context->content_epoch ||
        !cold::SnapshotRegistryCallbackContext(&g_cold_reboot_registry,
            &actual, &domain, &phase) || actual != context ||
        (domain != expected_domain && !(domain == cold::ContentDomainId::FrontendVerification &&
            phase == cold::RestartPhase::Verifying)) ||
        g_cold_reboot_registry.runtime_failure_latched) return false;
    if (phase == cold::RestartPhase::Preflighting || phase == cold::RestartPhase::Quiescing)
        return !g_cold_reboot_registry.transaction_prepared &&
            dluma_atomic_compare_exchange(&g_cold_reboot_registry.touch_transaction_state, 0, 0) == 1;
    return g_cold_reboot_registry.transaction_prepared &&
        context->transaction_generation == g_cold_reboot_registry.prepared_transaction_generation &&
        context->content_epoch == g_cold_reboot_registry.prepared_content_epoch;
}

bool ProductionCurveTransactionMatches(const cold::RestartContext* context) noexcept
{
    return context && context->content_epoch && context->transaction_generation &&
        context->owner_thread_id == GetCurrentThreadId() && g_curve_hooks_available &&
        g_curve_retirement_authority_ready &&
        context->baseline_generation == g_curve_baseline_generation &&
        ProductionDomainTransactionMatches(context, cold::ContentDomainId::Curves);
}

cold::DomainResult ColdCurvesPreflight(void*, const cold::RestartContext* context) noexcept
{
    if (!ProductionCurveTransactionMatches(context)) return cold::DomainResult::Unsupported;
    if (curves::PrepareCurveOwner(&g_curve_owner, context->transaction_generation) != curves::CurveOwnerResult::Succeeded)
        return cold::DomainResult::Unsupported;
    // The plan is revalidated at reset. Other domains' preflight readers and
    // baseline reloads must not run behind a gate held from this callback.
    return curves::CancelCurveOwner(&g_curve_owner) == curves::CurveOwnerResult::Succeeded
        ? cold::DomainResult::Succeeded : cold::DomainResult::Failed;
}

cold::DomainResult ColdCurvesQuiesce(void*, const cold::RestartContext* context) noexcept
{
    return ProductionCurveTransactionMatches(context)
        ? cold::DomainResult::Succeeded : cold::DomainResult::Unsupported;
}

cold::DomainResult ColdCurvesReset(void*, const cold::RestartContext* context) noexcept
{
    if (!ProductionCurveTransactionMatches(context) ||
        g_cold_reboot_registry.phase != cold::RestartPhase::Mutating ||
        !g_cold_reboot_registry.mutation_started) return cold::DomainResult::Failed;
    if (curves::PrepareCurveOwner(&g_curve_owner, context->transaction_generation) != curves::CurveOwnerResult::Succeeded)
        return cold::DomainResult::Failed;
    if (curves::ResetCurveOwner(&g_curve_owner) != curves::CurveOwnerResult::Succeeded ||
        curves::RetireCurveOwnerTail(&g_curve_owner) != curves::CurveOwnerResult::Succeeded ||
        curves::CompleteCurveOwner(&g_curve_owner) != curves::CurveOwnerResult::Succeeded)
        return cold::DomainResult::Failed;
    g_curve_completed_transaction = context->transaction_generation;
    g_curve_completed_epoch = context->content_epoch;
    return cold::DomainResult::Succeeded;
}

cold::DomainResult ColdCurvesRestored(void*, const cold::RestartContext* context) noexcept
{
    return ProductionCurveTransactionMatches(context) &&
        g_curve_completed_transaction == context->transaction_generation &&
        g_curve_completed_epoch == context->content_epoch && !g_curve_gateway.lost.load()
        ? cold::DomainResult::Succeeded : cold::DomainResult::Failed;
}

bool CloseRestoredCurvesForFrontendCommit(const cold::RestartContext* context) noexcept
{
    if (!(g_cold_reboot_registry.prepared_required_mask & cold::DomainBit(cold::ContentDomainId::Curves))) return true;
    return ColdCurvesRestored(nullptr, context) == cold::DomainResult::Succeeded &&
        curves::ReverifyCompletedCurveOwner(&g_curve_owner, context->transaction_generation,
            &g_curve_commit_lease) == curves::CurveOwnerResult::Succeeded;
}

bool ReleaseCurveCommitGate() noexcept
{
    if (!g_curve_commit_lease.generation) return true;
    const auto result = curves::OpenCurveGateway(&g_curve_gateway, &g_curve_commit_lease);
    g_curve_commit_lease = {};
    return result == curves::CurveGateResult::Succeeded;
}

bool CaptureProductionTextContext(void*, texts::TextFence* out) noexcept
{
    if (!out || !g_text_hooks_available || !g_text_owner_generation ||
        g_dluma.stop_requested) return false;
    SerializedFrameRouteEvidence frame = {};
    const bool authoritative = CurrentSerializedGameFrameRouteMatches(
        0, GetCurrentThreadId(), &frame) == statefive::RejectReason::C10ScopeMatched;
    *out = {};
    out->owner_generation = g_text_owner_generation;
    out->authoritative_thread = authoritative;
    out->custom_epoch_count = dluma_atomic_compare_exchange(
        &g_startup_b0_custom_staging_seen, 0, 0) ? 1U : 0U;
    out->returned_frontend = out->custom_epoch_count != 0;
    out->first_clean_frontend = g_text_first_baseline_scope &&
        !out->returned_frontend && !content::CurrentEpochId(&g_content_ledger);
    return authoritative && dluma_localization_capture_native_locale(out->locale);
}

bool CaptureProductionTextReplay(void*, texts::TextReplayAuthority* out) noexcept
{
    const cold::RestartContext* context = g_text_callback_context;
    if (!out || !context || g_text_replay_operation == texts::TextReplayOperation::None ||
        context->owner_thread_id != GetCurrentThreadId() ||
        g_cold_reboot_registry.phase != cold::RestartPhase::Mutating ||
        !g_cold_reboot_registry.transaction_prepared ||
        context->transaction_generation != g_cold_reboot_registry.prepared_transaction_generation ||
        context->content_epoch != g_cold_reboot_registry.prepared_content_epoch ||
        context->transaction_generation != g_text_active_transaction ||
        !(g_cold_reboot_registry.prepared_participating_mask &
            cold::DomainBit(cold::ContentDomainId::LocalizedTexts))) return false;
    *out = {context->transaction_generation, g_text_replay_operation};
    return true;
}

bool AllocateTextOwnerStorage() noexcept
{
    if (g_text_baseline_owner.baseline.entries) return true;
    constexpr std::size_t entries_bytes =
        texts::kMaximumTextEntries * sizeof(texts::TextEntry);
    constexpr std::size_t bytes = entries_bytes + texts::kMaximumSnapshotBytes;
    auto* baseline = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, bytes * 2, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE));
    if (!baseline) return false;
    texts::TextSnapshot storage = {}, scratch = {};
    storage.entries = reinterpret_cast<texts::TextEntry*>(baseline);
    storage.storage = baseline + entries_bytes;
    storage.entry_capacity = texts::kMaximumTextEntries;
    storage.storage_capacity = texts::kMaximumSnapshotBytes;
    scratch = storage;
    scratch.entries = reinterpret_cast<texts::TextEntry*>(baseline + bytes);
    scratch.storage = baseline + bytes + entries_bytes;
    g_text_observed_access.gate = &g_text_observation_gate;
    g_text_observed_access.context = &CaptureProductionTextContext;
    g_text_observed_access.replay_authority = &CaptureProductionTextReplay;
    texts::NativeTextAccess access = {};
    if (!texts::MakeObservedTextAccess(&g_text_observed_access, &access) ||
        texts::InitializeOwner(&g_text_baseline_owner, &access, &storage, &scratch) !=
            texts::TextResult::Succeeded) {
        VirtualFree(baseline, 0, MEM_RELEASE);
        return false;
    }
    // Process-owned immutable B0 and reusable scratch; never adopt a returned menu.
    return true;
}

cold::DomainResult ColdTextsBaseline(void*, const cold::RestartContext* context) noexcept
{
    if (!context || !context->baseline_generation || !g_text_hooks_available ||
        context->owner_thread_id != GetCurrentThreadId() ||
        content::CurrentEpochId(&g_content_ledger) ||
        dluma_atomic_compare_exchange(&g_startup_b0_custom_staging_seen, 0, 0) ||
        context->baseline_generation != g_startup_b0_session.session_generation)
        return cold::DomainResult::Unsupported;
    if (g_text_baseline_owner.baseline.complete)
        return g_text_baseline_owner.phase == texts::TextPhase::BaselineCaptured &&
            context->baseline_generation == g_text_owner_generation
            ? cold::DomainResult::Succeeded : cold::DomainResult::Failed;
    g_text_owner_generation = context->baseline_generation;
    if (!AllocateTextOwnerStorage()) return cold::DomainResult::Failed;
    texts::TextGateLease lease = {};
    if (texts::CloseTextGate(&g_text_observation_gate, 50, &lease) !=
        texts::TextGateResult::Succeeded) return cold::DomainResult::Unsupported;
    g_text_first_baseline_scope = true;
    const auto result = texts::CaptureCleanBaseline(&g_text_baseline_owner);
    g_text_first_baseline_scope = false;
    const auto opened = texts::OpenTextGate(&g_text_observation_gate, &lease);
    if (opened != texts::TextGateResult::Succeeded)
        g_text_baseline_owner.phase = texts::TextPhase::Failed;
    return result == texts::TextResult::Succeeded && opened == texts::TextGateResult::Succeeded
        ? cold::DomainResult::Succeeded : cold::DomainResult::Unsupported;
}

bool ProductionTextTransactionMatches(const cold::RestartContext* context) noexcept
{
    return context && context->transaction_generation && context->content_epoch &&
        context->baseline_generation == g_text_owner_generation &&
        context->owner_thread_id == GetCurrentThreadId() && g_text_hooks_available &&
        !g_dluma.stop_requested && g_cold_reboot_state_five_scope.active &&
        g_cold_reboot_state_five_scope.epoch == context->content_epoch &&
        ProductionDomainTransactionMatches(context, cold::ContentDomainId::LocalizedTexts);
}

cold::DomainResult ColdTextsPreflight(void*, const cold::RestartContext* context) noexcept
{
    if (!ProductionTextTransactionMatches(context) ||
        g_cold_reboot_registry.phase != cold::RestartPhase::Preflighting)
        return cold::DomainResult::Unsupported;
    return texts::PreflightTextReset(&g_text_baseline_owner, context->transaction_generation) ==
        texts::TextResult::Succeeded ? cold::DomainResult::Succeeded : cold::DomainResult::Unsupported;
}

cold::DomainResult ColdTextsQuiesce(void*, const cold::RestartContext* context) noexcept
{
    // Audio workers may still read text while draining. Close the gate only
    // around the atomic text replacement after the Audio reset has finished.
    return ProductionTextTransactionMatches(context)
        ? cold::DomainResult::Succeeded : cold::DomainResult::Unsupported;
}

cold::DomainResult ColdTextsReset(void*, const cold::RestartContext* context) noexcept
{
    if (!ProductionTextTransactionMatches(context) || g_text_callback_context ||
        g_text_restoration_watch_active ||
        g_cold_reboot_registry.phase != cold::RestartPhase::Mutating)
        return cold::DomainResult::Failed;
    g_text_reset_lease = {};
    if (texts::CloseTextGate(&g_text_observation_gate, 250, &g_text_reset_lease) !=
        texts::TextGateResult::Succeeded) return cold::DomainResult::Failed;
    const auto transaction = context->transaction_generation;
    g_text_active_transaction = transaction;
    g_text_callback_context = context;
    bool success = texts::PrepareTextReset(&g_text_baseline_owner, transaction) ==
        texts::TextResult::Succeeded && texts::BindObservedTextReplay(
            &g_text_observed_access, &g_text_reset_lease, transaction);
    g_text_replay_operation = texts::TextReplayOperation::Clear;
    if (success) success = texts::ClearCustomTexts(&g_text_baseline_owner, transaction) ==
        texts::TextResult::Succeeded;
    g_text_replay_operation = texts::TextReplayOperation::Insert;
    if (success) success = texts::RestoreBaselineTexts(&g_text_baseline_owner, transaction) ==
        texts::TextResult::Succeeded;
    g_text_replay_operation = texts::TextReplayOperation::None;
    if (success) success = texts::VerifyBaselineTexts(&g_text_baseline_owner, transaction) ==
        texts::TextResult::Succeeded && texts::BeginTextCommitWatch(
            &g_text_observation_gate, &g_text_reset_lease, transaction) == texts::TextGateResult::Succeeded;
    g_text_restoration_watch_active = success;
    g_text_callback_context = nullptr;
    const auto opened = texts::OpenTextGate(&g_text_observation_gate, &g_text_reset_lease);
    g_text_reset_lease = {};
    return success && opened == texts::TextGateResult::Succeeded
        ? cold::DomainResult::Succeeded : cold::DomainResult::Failed;
}

cold::DomainResult ColdTextsRestored(void*, const cold::RestartContext* context) noexcept
{
    const auto state = texts::InspectTextGate(&g_text_observation_gate);
    return ProductionTextTransactionMatches(context) &&
        g_text_restoration_watch_active && !state.late_producer &&
        !state.unknown_borrow && !state.lost_observation &&
        g_text_baseline_owner.phase == texts::TextPhase::Verified &&
        g_text_baseline_owner.transaction_generation == context->transaction_generation
        ? cold::DomainResult::Succeeded : cold::DomainResult::Failed;
}

bool CloseRestoredTextsForFrontendCommit(const cold::RestartContext* context) noexcept
{
    if (!(g_cold_reboot_registry.prepared_required_mask &
          cold::DomainBit(cold::ContentDomainId::LocalizedTexts))) return true;
    if (ColdTextsRestored(nullptr, context) != cold::DomainResult::Succeeded ||
        g_text_commit_lease.generation) return false;
    if (texts::CloseTextGate(&g_text_observation_gate, 250, &g_text_commit_lease) !=
        texts::TextGateResult::Succeeded) return false;
    return texts::ReverifyBaselineTexts(&g_text_baseline_owner, context->transaction_generation) ==
            texts::TextResult::Succeeded &&
        texts::CompleteTextCommitWatch(&g_text_observation_gate, &g_text_commit_lease,
            context->transaction_generation) == texts::TextGateResult::Succeeded;
}

bool ReleaseTextCommitGate() noexcept
{
    if (!g_text_commit_lease.generation) return true;
    const auto result = texts::OpenTextGate(&g_text_observation_gate, &g_text_commit_lease);
    g_text_commit_lease = {};
    g_text_restoration_watch_active = false;
    return result == texts::TextGateResult::Succeeded;
}

