cold::DomainResult ColdVfsReset(
    void*, const cold::RestartContext* context) noexcept
{
    if (!context || !context->content_epoch ||
        !ColdRebootSourceResetAuthorized(context->content_epoch) ||
        !g_prepared_source_reset.prepared ||
        g_prepared_source_reset.binding.epoch !=
            context->content_epoch ||
        !PreparedSourceRegistryPlanStillStable())
        return cold::DomainResult::Failed;
    FrontendResetGate reset_gate;
    if (!reset_gate.locked() || !ContentTrackingLive() ||
        g_dluma.stop_requested ||
        dluma_atomic_compare_exchange(
            &g_frontend_reset_stopping, 0, 0) != 0 ||
        !PreparedSourceRegistryIdentityStillStable())
        return cold::DomainResult::Failed;
    if (!cold::MarkRegistryMutationStarted(
            &g_cold_reboot_registry, context))
        return cold::DomainResult::Failed;
    g_source_retirement_transaction = context->transaction_generation;
    g_source_retirement_epoch = context->content_epoch;
    g_source_retirement_complete = false;
    /*
     * This is the only content-isolation mutation boundary that may freeze
     * frame-route correction. Ordinary UI/native dispatch and read-only B0
     * capture deliberately do not set this state.
     */
    dluma_engine_note_registry_mutation_started(&g_dluma.engine);
    const FrontendEpochBinding binding =
        g_prepared_source_reset.binding;
    const bool binding_consumed =
        ConsumeFrontendEpochBinding(binding);
    const bool epoch_consumed = binding_consumed &&
        content::MarkEpochConsumed(
            &g_content_ledger, binding.epoch,
            content::NextSequence(&g_content_ledger));
    const bool reset_phase_claimed = epoch_consumed &&
        TryBeginFrontendResetPhase(binding.epoch);
    const bool lifecycle_claimed = reset_phase_claimed &&
        lifecycle::ConsumeForReset(&g_frontend_lifecycle) &&
        lifecycle::BeginReset(&g_frontend_lifecycle);
    if (!lifecycle_claimed) {
        if (binding_consumed)
            (void)ClearConsumedFrontendEpochBinding(binding);
        else
            (void)AbandonFrontendEpochBinding(binding);
        lifecycle::MarkRuntimeFailed(&g_frontend_lifecycle);
        g_prepared_source_reset.prepared = false;
        g_component_status.sources =
            ComponentRuntimeState::RuntimeFailed;
        g_component_status.baseline =
            ComponentRuntimeState::RuntimeFailed;
        SetAggregateState(FixState::RuntimeFailed);
        return cold::DomainResult::Failed;
    }
    dluma_atomic_exchange(
        &g_last_consumed_frontend_epoch,
        static_cast<LONG>(binding.epoch));

    const bool publish =
        dluma_atomic_compare_exchange(&g_trace_live, 0, 0) != 0 &&
        dluma_atomic_compare_exchange(&g_trace_stopping, 0, 0) == 0;
    if (publish)
        PublishSimple(
            AssetTraceEventType::FrontendSourceResetBegin,
            reinterpret_cast<std::uintptr_t>(binding.session),
            reinterpret_cast<std::uintptr_t>(binding.outgoing_level),
            reinterpret_cast<std::uintptr_t>(
                g_cold_reboot_state_five_scope.release_level),
            binding.epoch, 0, binding.selected_content_name,
            binding.normalized_project_root);

    const bool sources_removed = PerformFrontendContentReset(
        binding.epoch, g_frontend_on_destroy_unload_observed,
        g_frontend_outgoing_level_release_observed);
    const bool ordering_failed = FrontendLookupWasEarly(binding.epoch);
    const bool succeeded = sources_removed && !ordering_failed;
    if (publish)
        PublishSimple(
            AssetTraceEventType::FrontendSourceResetEnd,
            reinterpret_cast<std::uintptr_t>(binding.session),
            reinterpret_cast<std::uintptr_t>(binding.outgoing_level),
            reinterpret_cast<std::uintptr_t>(
                g_cold_reboot_state_five_scope.release_level),
            binding.epoch, succeeded ? 1U : 0U,
            binding.selected_content_name,
            succeeded ? "source-removal-complete"
                      : "source-removal-failed");
    if (!succeeded) {
        SetFrontendLookupBarrier(
            binding.epoch,
            lifecycle::FrontendRollbackPhase::RuntimeFailed, false);
        lifecycle::CompleteReset(
            &g_frontend_lifecycle, false, true);
        g_component_status.sources =
            ComponentRuntimeState::RuntimeFailed;
        g_component_status.baseline =
            ComponentRuntimeState::RuntimeFailed;
        SetAggregateState(FixState::RuntimeFailed);
    }
    QueueContentDiagnostic(
        succeeded
            ? content::LedgerDiagnosticType::
                  FrontendSourceResetComplete
            : content::LedgerDiagnosticType::
                  FrontendSourceResetFailed,
        binding.epoch, succeeded ? 1U : 0U,
        reinterpret_cast<std::uintptr_t>(binding.session),
        sources_removed ? 1U : 0U,
        ordering_failed ? 1U : 0U,
        sources_removed ? "all-exact-sources-removed"
                        : "one-or-more-source-removals-failed",
        ordering_failed ? "frontend-lookup-before-reset"
                        : "ordering-intact");
    const bool binding_cleared =
        ClearConsumedFrontendEpochBinding(binding);
    if (!binding_cleared) {
        SetFrontendLookupBarrier(
            binding.epoch,
            lifecycle::FrontendRollbackPhase::RuntimeFailed, false);
        lifecycle::MarkRuntimeFailed(&g_frontend_lifecycle);
        g_component_status.sources =
            ComponentRuntimeState::RuntimeFailed;
        g_component_status.baseline =
            ComponentRuntimeState::RuntimeFailed;
        SetAggregateState(FixState::RuntimeFailed);
    }
    g_prepared_source_reset.prepared = false;
    return succeeded && binding_cleared
        ? cold::DomainResult::Succeeded
        : cold::DomainResult::Failed;
}

cold::DomainResult ColdVfsVerify(
    void*, const cold::RestartContext* context) noexcept
{
    if (!context || !context->content_epoch)
        return cold::DomainResult::Failed;
    content::CustomContentEpoch epoch = {};
    const std::uint64_t barrier = ReadFrontendLookupBarrier();
    return context->content_epoch == g_last_frontend_reset_epoch &&
            g_source_retirement_complete &&
            g_source_retirement_epoch == context->content_epoch &&
            g_source_retirement_transaction == context->transaction_generation &&
            content::SnapshotEpoch(
                &g_content_ledger, context->content_epoch, &epoch) &&
            epoch.sources_removed &&
            content::CountActiveCustomSources(&g_content_ledger) == 0 &&
            FrontendLookupBarrierEpoch(barrier) == context->content_epoch &&
            FrontendLookupBarrierPhase(barrier) ==
                lifecycle::FrontendRollbackPhase::ResetInProgress &&
            g_frontend_lifecycle.phase ==
                lifecycle::FrontendRollbackPhase::ResetInProgress &&
            g_frontend_lifecycle.reset_started &&
            !FrontendLookupWasEarly(context->content_epoch)
        ? cold::DomainResult::Succeeded
        : cold::DomainResult::Failed;
}

