bool AudioRetireVerifiedEpoch(const content::VerifiedEpochRetirement& receipt,
    std::uint64_t expected_runtime_revision,const cold::RestartContext* context,
    const cold::RegistryFinalizationToken* finalization) noexcept
{
    // The caller supplies the actual coordinator receipt after every domain
    // verified. This function neither constructs nor promotes that receipt.
    if (!receipt.epoch || !receipt.transaction_verified || !receipt.observer_admission_closed ||
        !receipt.verified_transaction_token || !receipt.observer_quiescence_token ||
        receipt.pending_observer_callbacks || receipt.external_active_references || receipt.quarantined ||
        g_cold_reboot_registry.phase != cold::RestartPhase::Verified ||
        g_cold_reboot_registry.completed_transaction_generation != receipt.verified_transaction_token ||
        !cold::RegistryFinalizationIsCurrent(&g_cold_reboot_registry,context,finalization) ||
        dluma_atomic_compare_exchange(&g_cold_reboot_registry.retaining_observation_active_calls, 0, 0) != 0 ||
        AudioObservationActiveCallCount() != 0 ||
        g_audio_runtime_observation_ledger.revision != static_cast<LONGLONG>(expected_runtime_revision) ||
        !g_audio_runtime_observation_ledger.runtime_occurrences ||
        !audiostart::AudioStartupObservationLossEmpty(g_audio_runtime_observation_ledger.loss)) return false;
    // A successful production FrontendVerification already rechecked the
    // sealed untouched decision when Audio was outside the required set.
    bool audio_verified = !(finalization->required_mask&cold::DomainBit(cold::ContentDomainId::Audio)) &&
        (finalization->verified_mask&cold::DomainBit(cold::ContentDomainId::FrontendVerification));
    for (std::uint32_t i = 0; i < g_cold_reboot_registry.count; ++i) {
        const auto& state = g_cold_reboot_registry.states[i];
        if ((finalization->required_mask&cold::DomainBit(cold::ContentDomainId::Audio)) &&
            g_cold_reboot_registry.adapters[i].id == cold::ContentDomainId::Audio)
            audio_verified = state.verify_result == cold::DomainResult::Succeeded &&
                state.verified_content_epoch == receipt.epoch &&
                state.verified_transaction_generation == receipt.verified_transaction_token &&
                state.verified_baseline_generation == g_audio_baseline_content.baseline_generation;
    }
    if (!audio_verified || !TryEnterAudioBaselineLock(nullptr)) return false;
    if (!TryLockAudioSemanticDelta()) { LeaveAudioBaselineLock(nullptr); return false; }
    const auto& semantic = g_audio_semantic_delta_ledger;
    const auto& runtime = g_audio_runtime_observation_ledger;
    const bool retirement_ready = semantic.evidence.initialized && semantic.evidence.assessed &&
        semantic.evidence.epoch == receipt.epoch && !semantic.evidence.observation_loss &&
        !semantic.evidence.incomplete_evidence &&
        receipt.verified_transaction_token > semantic.retired_transaction &&
        (!runtime.epoch || runtime.epoch == receipt.epoch) && receipt.epoch > runtime.retired_epoch &&
        receipt.verified_transaction_token > runtime.retired_transaction;
    const bool retired = retirement_ready &&
        audiostart::RetireAudioRuntimeObservations(&g_audio_runtime_observation_ledger,
            expected_runtime_revision, receipt) &&
        audiosemantic::RetireAudioSemanticEpoch(&g_audio_semantic_delta_ledger, receipt);
    UnlockAudioSemanticDelta();
    LeaveAudioBaselineLock(nullptr);
    return retired;
}

