cold::DomainResult ColdFrontendPreflight(
    void*, const cold::RestartContext* context) noexcept
{
    const cold::ContentDomainMask minimum =
        cold::DomainBit(cold::ContentDomainId::VfsSources) |
        cold::DomainBit(cold::ContentDomainId::FrontendVerification);
    const cold::ContentDomainMask required =
        g_cold_reboot_registry.mandatory_mask |
        static_cast<cold::ContentDomainMask>(dluma_atomic_compare_exchange(
            &g_cold_reboot_registry.touched_mask, 0, 0));
    return context && context->content_epoch &&
            context->owner_thread_id == GetCurrentThreadId() &&
            (required & minimum) == minimum &&
            (required & ~g_cold_reboot_registry.enabled_mask) == 0 &&
            g_cold_reboot_registry.phase ==
                cold::RestartPhase::Preflighting &&
            g_cold_reboot_state_five_scope.active &&
            g_cold_reboot_state_five_scope.barrier_attempted &&
            g_cold_reboot_state_five_scope.epoch ==
                context->content_epoch &&
            g_cold_reboot_state_five_scope.c10_callback_thread_id ==
                context->owner_thread_id &&
            g_prepared_source_reset.prepared &&
            g_prepared_source_reset.binding.epoch ==
                context->content_epoch &&
            !ColdRebootNextProjectStagingStarted() &&
            !g_dluma.stop_requested &&
            !g_cold_reboot_registry.runtime_failure_latched
        ? cold::DomainResult::Succeeded
        : cold::DomainResult::Unsupported;
}

