const char* ComponentStateName(ComponentRuntimeState state) noexcept
{
    switch (state) {
    case ComponentRuntimeState::Disabled: return "Disabled";
    case ComponentRuntimeState::UnsupportedBuild: return "UnsupportedBuild";
    case ComponentRuntimeState::DiagnosticOnly: return "Diagnostic only";
    case ComponentRuntimeState::Armed: return "Armed";
    case ComponentRuntimeState::Applied: return "Applied";
    case ComponentRuntimeState::Verified: return "Verified";
    case ComponentRuntimeState::ExperimentalArmed:
        return "ExperimentalArmed";
    case ComponentRuntimeState::ExperimentalApplied:
        return "ExperimentalApplied";
    case ComponentRuntimeState::ExperimentalVerified:
        return "ExperimentalVerified";
    case ComponentRuntimeState::RuntimePartial: return "RuntimePartial";
    case ComponentRuntimeState::RuntimeFailed: return "RuntimeFailed";
    default: return "Unknown";
    }
}

bool DomainImplementationAvailable(cold::ContentDomainId id) noexcept
{
    switch (id) {
    case cold::ContentDomainId::NativeFrontendEntries:
        // Capability for completed native-manager closure. A surviving dirty
        // manager still has to pass the adapter's explicit preflight checks.
        return g_xui_manager_observation_ready&&g_xui_instance_observation_ready&&
            !g_xui_manager_ledger.lost.load()&&!g_xui_instances.lost.load()&&
            !g_xui_content_owner.lost.load()&&g_xui_content_owner.baseline_frozen&&
            g_xui_content_owner.baseline_generation.load()!=0&&ProductionXuiHooksCurrent();
    case cold::ContentDomainId::VfsSources:
        return g_cold_reboot_hooks_available;
    case cold::ContentDomainId::PlayerGameplayParams:
        return g_player_restart_adapter.mutation_operations.
            production_enabled;
    case cold::ContentDomainId::LocalizedTexts:
        return g_text_hooks_available;
    case cold::ContentDomainId::Curves:
        return g_curve_hooks_available && g_curve_retirement_authority_ready;
    case cold::ContentDomainId::NativeRetainedResources:
        return g_native_resources.available&&g_native_resources.baseline_generation!=0;
    case cold::ContentDomainId::NativeMaterialDefinitions:
        return g_native_resources.available&&g_native_resources.material.baseline.captured&&
            g_native_resources.material.baseline.generation==g_native_resources.baseline_generation&&
            g_native_resources.material.baseline.local_absent&&!g_native_resources.material.lost.load()&&
            !g_native_resources.material.global_pack_mutated.load();
    case cold::ContentDomainId::FrontendVerification:
        return g_cold_reboot_hooks_available;
    default:
        return false;
    }
}

