bool CopyLobbyContentName(std::uintptr_t offset, char* output,
                          std::size_t capacity) noexcept
{
    if (!output || !capacity) return false;
    output[0] = 0;
    void* storage = nullptr;
    void* vtable = nullptr;
    if (!ReadBytes(g_context.engine_base + kLobbyStorageGlobalRva,
                   &storage, sizeof(storage)) || !storage ||
        !ReadBytes(reinterpret_cast<std::uintptr_t>(storage), &vtable,
                   sizeof(vtable)) ||
        vtable != reinterpret_cast<void*>(
            g_context.engine_base + kLobbyStorageSteamVtableRva)) {
        CopyLiteral(output, capacity, "<storage-owner-unreadable>");
        return false;
    }
    CopyTtlText(output, capacity,
                reinterpret_cast<const TtlStringView*>(
                    reinterpret_cast<std::uintptr_t>(storage) + offset));
    return output[0] != '<';
}

bool CreateFrontendEpochBinding(
    const FrontendEpochBinding& value) noexcept
{
    FrontendEpochBinding canonical = value;
    if (!value.epoch ||
        !content::NormalizeProjectRoot(
            value.normalized_project_root,
            canonical.normalized_project_root,
            sizeof(canonical.normalized_project_root)))
        return false;
    if (dluma_atomic_compare_exchange(
            &g_frontend_epoch_binding.write_lock, 1, 0) != 0) {
        content::RecordOwnershipMutationLoss(
            &g_content_ledger,
            content::LedgerLossReason::BindingContention);
        return false;
    }
    if (dluma_atomic_compare_exchange(
            &g_frontend_epoch_binding.consumed, 0, 0) == 0) {
        dluma_atomic_exchange(&g_frontend_epoch_binding.write_lock, 0);
        return false;
    }
    dluma_atomic_increment(&g_frontend_epoch_binding.sequence);
    g_frontend_epoch_binding.value = canonical;
    dluma_atomic_exchange(&g_frontend_epoch_binding.consumed, 0);
    dluma_atomic_increment(&g_frontend_epoch_binding.sequence);
    dluma_atomic_exchange(&g_frontend_epoch_binding.write_lock, 0);
    return true;
}

bool ReadFrontendEpochBinding(FrontendEpochBinding* output) noexcept
{
    if (!output) return false;
    std::memset(output, 0, sizeof(*output));
    for (unsigned int attempt = 0; attempt < 8; ++attempt) {
        const LONG before = dluma_atomic_compare_exchange(
            &g_frontend_epoch_binding.sequence, 0, 0);
        if (before & 1) continue;
        const LONG consumed = dluma_atomic_compare_exchange(
            &g_frontend_epoch_binding.consumed, 0, 0);
        const FrontendEpochBinding value =
            g_frontend_epoch_binding.value;
        const LONG after = dluma_atomic_compare_exchange(
            &g_frontend_epoch_binding.sequence, 0, 0);
        if (before != after || (after & 1)) continue;
        if (consumed != 0 || !value.epoch) return false;
        *output = value;
        return true;
    }
    return false;
}

bool FrontendEpochBindingsEqual(
    const FrontendEpochBinding& left,
    const FrontendEpochBinding& right) noexcept
{
    return left.epoch == right.epoch &&
        left.session == right.session &&
        left.outgoing_level == right.outgoing_level &&
        left.owner_thread_id == right.owner_thread_id &&
        content::ProjectRootsEqual(
            left.normalized_project_root,
            right.normalized_project_root) &&
        AsciiEquals(left.selected_content_name,
                    right.selected_content_name);
}

