    void* const result = g_original_ctc_parse_file_constructor(
        parser, option, path, owner, final_option);
    WatchedParserScope* scope = CurrentWatchedParserScope();
    void* input = nullptr;
    std::uint32_t count = 0;
    bool observed = false;
    if (scope && scope->owner == WatchedParserOwner::TextFile &&
        result &&
        ReadBytes(reinterpret_cast<std::uintptr_t>(result) + 528U,
                  &input, sizeof(input)) &&
        ReadBytes(reinterpret_cast<std::uintptr_t>(result) + 544U,
                  &count, sizeof(count)))
        observed = ObserveParserInput(scope, input, count, path);
    if (observed && call.publish())
        PublishParserScopeEvent(
            AssetTraceEventType::ScriptLoaderWatchedParse, *scope,
            nullptr, trace::WatchedScriptOutcome::Unknown, 0,
            "exact-CTCParse-file-buffer");
