int Runtime15InventoryRead(
    void*, std::uintptr_t address, void* output,
    std::size_t size) noexcept
{
    return address && output && size &&
        ReadBytes(address, output, size) ? 1 : 0;
}

int Runtime15InventoryQuery(
    void*, std::uintptr_t address,
    DlumaPlayerDiMemoryRegion* output) noexcept
{
    MEMORY_BASIC_INFORMATION region = {};
    if (!output) return 0;
    std::memset(output, 0, sizeof(*output));
    if (!address ||
        VirtualQuery(
            reinterpret_cast<const void*>(address), &region,
            sizeof(region)) != sizeof(region))
        return 0;
    output->base =
        reinterpret_cast<std::uintptr_t>(region.BaseAddress);
    output->size = region.RegionSize;
    output->state = region.State;
    output->protection = region.Protect;
    output->query_succeeded = 1;
    if (output->base <= address &&
        output->size <= ~std::uintptr_t{0} - output->base &&
        address < output->base + output->size)
        output->address_in_region = 1;
    return 1;
}

void CaptureRuntime15InventoryTree(
    DlumaPlayerInventoryPhase phase,
    std::uint64_t destroy_generation,
    std::uint64_t route_token,
    void* session,
    void* level) noexcept
{
    if (!kEnableRuntime15InventoryDiagnostic ||
        !g_gamedll_full_profile_valid)
        return;
    (void)dluma_player_inventory_capture_and_publish_tree(
        static_cast<std::uint32_t>(phase), GetCurrentThreadId(),
        content::CurrentEpochId(&g_content_ledger),
        destroy_generation, route_token,
        reinterpret_cast<std::uintptr_t>(session),
        reinterpret_cast<std::uintptr_t>(level),
        Runtime15InventoryRead, Runtime15InventoryQuery, nullptr);
}

