    DlumaPlayerInventoryStateFiveCrashState state = {};
    dluma_player_inventory_state_five_snapshot(&state);
    statefive::PleaseWaitOwnerToken token = {};
    (void)SnapshotPleaseWaitOwnerToken(&token);
    if (token.frame_route_token)
        state.c08_token = token.frame_route_token;
    if (token.c08_callback_thread_id)
        state.c08_thread_id = token.c08_callback_thread_id;
    state.c10_scope_result =
        static_cast<std::uint32_t>(g_c10_scope_result);
    state.c10_scope_active =
        g_cold_reboot_state_five_scope.active ? 1U : 0U;
    state.c10_scope_armed =
        g_cold_reboot_state_five_scope.armed ? 1U : 0U;
    state.armed_epoch =
        g_cold_reboot_state_five_scope.active
            ? g_cold_reboot_state_five_scope.epoch : 0U;
    state.outgoing_session =
        reinterpret_cast<std::uintptr_t>(
            g_cold_reboot_state_five_scope.outgoing_session);
    if (g_cold_reboot_state_five_scope.c10_callback_thread_id)
        state.c10_thread_id =
            g_cold_reboot_state_five_scope.c10_callback_thread_id;
    dluma_player_inventory_state_five_publish(&state);
