void __fastcall HookPlayerDiOnCreate(void* player_di) noexcept
{
    void* entry_state = nullptr;
    if (player_di)
        (void)ReadBytes(
            reinterpret_cast<std::uintptr_t>(player_di) +
                kPlayerDiStateOffset,
            &entry_state, sizeof(entry_state));
    const std::uint64_t entry_sequence =
        content::NextSequence(&g_content_ledger);
    dluma_atomic_pointer_exchange(
        &g_player_di_on_create_object, player_di);
    dluma_atomic_pointer_exchange(
        &g_player_di_on_create_state, entry_state);
    _InterlockedExchange64(
        &g_player_di_on_create_entry_sequence,
        static_cast<LONGLONG>(entry_sequence));
    _InterlockedExchange64(
        &g_player_di_on_create_return_sequence, 0);
    const std::uintptr_t caller_address =
        reinterpret_cast<std::uintptr_t>(_ReturnAddress());
    const bool exact_writer_owner =
        g_player_writer_chain_scope.depth == 1U &&
        g_player_writer_chain_scope.init_object_seen &&
        reinterpret_cast<std::uintptr_t>(entry_state) ==
            g_player_writer_chain_scope.player_state &&
        !g_player_writer_chain_scope.reentrancy_conflict;
    PlayerWriterEventInput entry = {};
    entry.sequence = entry_sequence;
    entry.route =
        playerpublication::ObserverRoute::PlayerDiOnCreate;
    entry.subphase = playerpublication::WriterSubphase::
        PlayerDiOnCreateEntry;
    entry.player_state =
        reinterpret_cast<std::uintptr_t>(entry_state);
    entry.gameplay_container =
        g_player_writer_chain_scope.depth
            ? g_player_writer_chain_scope.gameplay_container
            : 0U;
    entry.caller_address = caller_address;
    entry.row = UINT32_MAX;
    entry.base_template =
        g_player_writer_chain_scope.depth
            ? g_player_writer_chain_scope.base_template
            : nullptr;
    entry.progression_template =
        g_player_writer_chain_scope.depth
            ? g_player_writer_chain_scope.progression_template
            : nullptr;
    entry.first_exact_failure =
        g_player_writer_chain_scope.depth &&
                !exact_writer_owner
            ? playerpublication::ExactFailure::
                  ReceiverMismatch
            : playerpublication::ExactFailure::None;
    RecordPlayerWriterEvent(entry);
    {
        ActiveHookCall call(g_player_di_on_create_status);
        g_original_player_di_on_create(player_di);
        void* state = nullptr;
        if (player_di)
            (void)ReadBytes(
                reinterpret_cast<std::uintptr_t>(player_di) +
                    kPlayerDiStateOffset,
                &state, sizeof(state));
        const std::uint64_t sequence =
            content::NextSequence(&g_content_ledger);
        dluma_atomic_pointer_exchange(
            &g_player_di_on_create_object, player_di);
        dluma_atomic_pointer_exchange(
            &g_player_di_on_create_state, state);
        _InterlockedExchange64(
            &g_player_di_on_create_return_sequence,
            static_cast<LONGLONG>(sequence));
        const std::uint64_t generation = ObservePlayerState(
            state, playerstate::OwnerKind::PlayerDi,
            player_di, sequence);
        if (kEnableRuntime15InventoryDiagnostic) {
            dluma_player_inventory_publish_player(
                player_di, generation,
                content::CurrentEpochId(&g_content_ledger),
                static_cast<std::uint32_t>(
                    trace::CurrentTransitionGeneration()),
                GetCurrentThreadId());
            CaptureRuntime15InventoryTree(
                DLUMA_PLAYER_INVENTORY_PHASE_PLAYER_ON_CREATE);
        }
        const std::uint64_t restart_generation =
            playerrestart::FindLivePlayerStateGeneration(
                &g_player_restart_adapter,
                reinterpret_cast<std::uintptr_t>(state));
        if (restart_generation)
            (void)playerrestart::ClassifyPlayerStateOwner(
                &g_player_restart_adapter,
                reinterpret_cast<std::uintptr_t>(state),
                restart_generation,
                playerrestart::PlayerStateOwnerKind::PlayerDi,
                reinterpret_cast<std::uintptr_t>(player_di));
        RecordPlayerSideEffect(
            playerstate::SideEffectKind::PlayerDiCreate,
            state, player_di, false, sequence);
        PlayerWriterEventInput returned = entry;
        returned.sequence = sequence;
        returned.subphase = playerpublication::WriterSubphase::
            PlayerDiOnCreateReturn;
        returned.player_state =
            reinterpret_cast<std::uintptr_t>(state);
        returned.first_exact_failure =
            exact_writer_owner &&
                    reinterpret_cast<std::uintptr_t>(state) ==
                        g_player_writer_chain_scope.player_state
                ? playerpublication::ExactFailure::None
                : playerpublication::ExactFailure::
                      ReceiverMismatch;
        RecordPlayerWriterEvent(returned);
        if (call.publish())
            PublishPlayerOwner(
                state, playerstate::OwnerKind::PlayerDi,
                player_di, generation,
                AssetTraceEventType::PlayerStateOwnerObserved,
                g_player_di_on_create_status);
    }
    /*
     * The inventory-stability contract includes the OnCreate hook itself.
     * Capture only after ActiveHookCall has retired this exact return.
     */
    CapturePlayerPublicationCheckpoint(
        playerpublication::Checkpoint::PlayerDiOnCreateReturn);
}

