void __fastcall HookSpeechBankLoad(
    void* speech_bank, const char* bank_name, bool localised) noexcept
{
    ActiveHookCall call(g_speech_bank_load_status);
    AudioReplayInvocation retaining(static_cast<std::uint32_t>(kSpeechBankLoadRva),
        reinterpret_cast<std::uintptr_t>(speech_bank),bank_name,localised);
    if (!retaining.admitted()) return;
    const std::uint32_t semantic_epoch =
        content::CurrentEpochId(&g_content_ledger);
    char copied_name[persistent::kPersistentPathCapacity] = {};
    const bool copied_name_complete = trace::CopyReadableCString(
        copied_name, sizeof(copied_name), bank_name, 4096) ==
        trace::AssetTraceStringCopyResult::Copied;
    if (!copied_name_complete)
        CopyLiteral(copied_name, sizeof(copied_name), "<unreadable>");
    char normalized_name[
        audiostart::kAudioStartupLogicalPathCapacity] = {};
    const bool normalized_name_complete = copied_name_complete &&
        CopyAudioBankStem(normalized_name, sizeof(normalized_name),
                          copied_name);
    std::uint64_t source_registry_generation_enter = 0;
    const bool source_registry_stable_at_enter =
        ReadStableSourceRegistryGeneration(
            &source_registry_generation_enter);
    const std::uint64_t provider_enter_sequence =
        content::NextSequence(&g_content_ledger);
    (void)audio::SetAudioResolvedSourceObservationRequired(
        &g_speech_bank_provider_context,
        g_audio_full_path_provider_probe_available);
    const audio::AudioBankLoadToken provider_token =
        audio::BeginAudioBankLoad(
            &g_speech_bank_provider_context,
            reinterpret_cast<std::uintptr_t>(speech_bank),
            normalized_name, normalized_name_complete, false,
            localised, provider_enter_sequence);
    ArmFullPathProbeForBankLoad(
        &g_speech_bank_provider_context, provider_token,
        audio::AudioFullPathProbeOwner::Speech);
    speechregistry::SpeechRegistryMutationToken mutation = {};
    const bool admitted = speechregistry::BeginSpeechRegistryMutation(
        &g_speech_registry_observation_gate, &mutation);
    if (!admitted)
        dluma_atomic_exchange(
            &g_speech_registry_gate_integrity_failed, 1);
    PublishSpeechRegistryMutation(
        call, AssetTraceEventType::SpeechRegistryMutationEnter,
        static_cast<std::uint32_t>(kSpeechBankLoadRva),
        "speech_bank_load", reinterpret_cast<std::uintptr_t>(speech_bank),
        copied_name, admitted, false, false, localised ? 1U : 0U);
    g_original_speech_bank_load(speech_bank, bank_name, localised);
    DrainFullPathProbeForBankLoad(
        &g_speech_bank_provider_context);
    audio::AudioBankProviderRecord provider_record = {};
    const std::uint64_t provider_exit_sequence =
        content::NextSequence(&g_content_ledger);
    const audio::AudioBankProviderEndResult provider_end =
        audio::EndAudioBankLoad(
            &g_speech_bank_provider_context, provider_token, 0,
            provider_exit_sequence, &provider_record);
    DisarmFullPathProbeForBankLoad(
        &g_speech_bank_provider_context, provider_token);
    std::uint64_t source_registry_generation_exit = 0;
    const bool source_registry_stable =
        source_registry_stable_at_enter &&
        ReadStableSourceRegistryGeneration(
            &source_registry_generation_exit) &&
        source_registry_generation_exit ==
            source_registry_generation_enter;
    /* A resident-name hit returns before fs::open_native.  Coverage which
     * began before SpeechMgr creation already owns the earlier exact load;
     * do not invent a provider or add an incomplete cache record here. */
    if (provider_end == audio::AudioBankProviderEndResult::Completed &&
        provider_record.native_open_count != 0U) {
        audiostart::AudioStartupBankObservation observation = {};
        observation.epoch = semantic_epoch;
        observation.enter_sequence = provider_record.enter_sequence;
        observation.exit_sequence = provider_record.exit_sequence;
        observation.scope_generation = provider_record.generation;
        observation.manager =
            reinterpret_cast<std::uintptr_t>(speech_bank);
        observation.result = provider_record.open_succeeded ? 0 : -1;
        observation.owner =
            audiostart::AudioStartupBankOwner::Speech;
        observation.bank_name_complete =
            provider_record.bank_name_copy_complete;
        observation.localized = localised;
        observation.localized_observed = true;
        observation.reload = false;
        observation.provider.path_complete =
            provider_record.path_copy_complete;
        observation.provider.source =
            provider_record.selected_source;
        observation.native_file = provider_record.first_open.native_file;
        observation.native_file_instance_generation = provider_record.first_open.native_file_instance_generation;
        observation.provider.source_registry_generation =
            source_registry_generation_enter;
        observation.provider.source_registry_generation_observed =
            source_registry_stable;
        observation.provider.exact_source =
            provider_record.exact_source_identity_available &&
            source_registry_stable;
        file_lifetime::SourceKey speech_source_key = {};
        if (observation.provider.exact_source && filebridge::SourceIdentity(
                &g_native_file_bridge, observation.provider.source, &speech_source_key) &&
            speech_source_key.generation == provider_record.first_open.provider_instance_generation)
            observation.provider.instance_generation = speech_source_key.generation;
        CopyLoaderText(observation.bank_name,
                       sizeof(observation.bank_name),
                       provider_record.bank_name);
        CopyLoaderText(observation.provider.path,
                       sizeof(observation.provider.path),
                       provider_record.first_open.provider_path);
        const bool exact_single_open =
            provider_record.native_open_count == 1U &&
            !provider_record.multiple_native_opens &&
            !provider_record.nested_stack_overflow &&
            !provider_record.generation_mismatch &&
            !provider_record.source_identity_loss &&
            provider_record.callsite_matched &&
             provider_record.argument_contract_matched &&
             provider_record.path_copy_complete &&
             source_registry_stable &&
             (!g_audio_full_path_provider_probe_available ||
              provider_record.exact_source_identity_available);
        observation.observation_complete =
            exact_single_open &&
            provider_record.bank_name_copy_complete;
        observation.provider_outcome = !exact_single_open
            ? audiostart::AudioStartupProviderOutcome::
                  ObservationIncomplete
            : provider_record.open_succeeded
                ? audiostart::AudioStartupProviderOutcome::
                      NaturalOpenResolvedPath
                : audiostart::AudioStartupProviderOutcome::LoadFailed;
        (void)audiostart::RecordAudioStartupBank(
            &g_audio_startup_observation_ledger, observation);
    }
    const bool fence_recorded =
        audiostart::RecordAudioStartupMutationFence(
            &g_audio_startup_observation_ledger);
    const bool gate_completed = admitted &&
        speechregistry::EndSpeechRegistryMutation(&mutation);
    if (!fence_recorded || !gate_completed)
        dluma_atomic_exchange(
            &g_speech_registry_gate_integrity_failed, 1);
    RecordAudioSemanticSpeech(
        semantic_epoch,
        admitted && fence_recorded && gate_completed);
    PublishSpeechRegistryMutation(
        call, AssetTraceEventType::SpeechRegistryMutationExit,
        static_cast<std::uint32_t>(kSpeechBankLoadRva),
        "speech_bank_load", reinterpret_cast<std::uintptr_t>(speech_bank),
        copied_name, admitted, fence_recorded, gate_completed,
        localised ? 1U : 0U);
}

