bool TryAudioSourceReaderGate(void*) noexcept
{
    if (!g_audio_bank_name_query_status || !g_audio_bank_name_query_status->installed ||
        g_audio_source_query_depth || !TryAcquireSRWLockExclusive(&g_audio_source_reader_gate)) return false;
    if (!speechregistry::TryAcquireSpeechRegistrySnapshot(&g_speech_registry_observation_gate,&g_audio_worker_speech_token)) {
        ReleaseSRWLockExclusive(&g_audio_source_reader_gate); return false;
    }
    dluma_atomic_exchange(&g_audio_source_reader_owner, static_cast<LONG>(GetCurrentThreadId()));
    return true;
}

void LeaveAudioSourceReaderGate(void*) noexcept
{
    speechregistry::AbandonSpeechRegistrySnapshot(&g_audio_worker_speech_token);
    dluma_atomic_exchange(&g_audio_source_reader_owner, 0);
    ReleaseSRWLockExclusive(&g_audio_source_reader_gate);
}

std::uintptr_t __fastcall HookAudioBankNameQuery(void* owner,const TtlStringView* name,TtlStringView* output) noexcept
{
    ActiveHookCall call(g_audio_bank_name_query_status);
    const bool exclusive_owner = dluma_atomic_compare_exchange(&g_audio_source_reader_owner, 0, 0) ==
        static_cast<LONG>(GetCurrentThreadId());
    const bool acquire = !g_audio_source_query_depth && !exclusive_owner;
    if (acquire) AcquireSRWLockShared(&g_audio_source_reader_gate);
    ++g_audio_source_query_depth;
    const auto result = g_original_audio_bank_name_query(owner, name, output);
    --g_audio_source_query_depth;
    if (acquire) ReleaseSRWLockShared(&g_audio_source_reader_gate);
    return result;
}

class AudioDefinitionWriterScope {
    bool acquired_;
    bool admitted_;
public:
    AudioDefinitionWriterScope() noexcept : acquired_(false), admitted_(!g_audio_definition_read_owned) {
        if (!admitted_) { g_audio_definition_read_violation = true; return; }
        if (!g_audio_definition_writer_depth) { AcquireSRWLockShared(&g_audio_definition_gate); acquired_ = true; }
        ++g_audio_definition_writer_depth;
    }
    ~AudioDefinitionWriterScope() {
        if (!admitted_) return;
        --g_audio_definition_writer_depth;
        if (acquired_) ReleaseSRWLockShared(&g_audio_definition_gate);
    }
    bool admitted() const noexcept { return admitted_; }
};

bool CaptureCurrentAudioDefinition(char* output,std::size_t capacity,std::size_t* length) noexcept
{
    if (length) *length = 0;
    if (!output || !length || capacity < 4096 || !g_audio_definition_target_validated ||
        g_audio_definition_writer_depth || g_audio_definition_read_owned ||
        !TryAcquireSRWLockExclusive(&g_audio_definition_gate)) return false;
    g_audio_definition_read_owned = true; g_audio_definition_read_violation = false;
    struct Exit {
        ~Exit() { g_audio_definition_read_owned = false; ReleaseSRWLockExclusive(&g_audio_definition_gate); }
    } exit;
    struct Keywords { std::uintptr_t data; std::uint32_t count,capacity; } before = {}, after = {};
    if (!ReadBytes(g_context.engine_base + 0xAD5378U, &before, sizeof(before)) || !before.data ||
        !before.count || before.count > 256U || before.count > before.capacity ||
        before.data > UINTPTR_MAX-before.count*sizeof(std::uintptr_t)) return false;
    std::uintptr_t free_import = 0;
    const auto free_pointer = reinterpret_cast<void(__cdecl*)(void*)>(GetProcAddress(GetModuleHandleW(L"MSVCR100.dll"), "free"));
    if (!free_pointer || !ReadBytes(g_context.engine_base + 0x856838U, &free_import, sizeof(free_import)) ||
        free_import != reinterpret_cast<std::uintptr_t>(free_pointer)) return false;
    for (std::uint32_t i = 0; i < before.count; ++i) {
        std::uintptr_t keyword = 0, vtable = 0, methods[3] = {};
        if (!ReadBytes(before.data + i * sizeof(keyword), &keyword, sizeof(keyword)) || !keyword ||
            !ReadBytes(keyword, &vtable, sizeof(vtable)) || !ReadBytes(vtable, methods, sizeof(methods))) return false;
        for (const auto method : methods)
            if (method < g_context.engine_base || method - g_context.engine_base >= g_context.engine_size_of_image) return false;
        using Count = unsigned (__fastcall*)(std::uintptr_t);
        using Name = const char* (__fastcall*)(std::uintptr_t);
        using Type = unsigned (__fastcall*)(std::uintptr_t,unsigned);
        const auto arguments = reinterpret_cast<Count>(methods[1])(keyword);
        char name[256] = {};
        if (arguments > 12 || trace::CopyReadableCString(name, sizeof(name),
                reinterpret_cast<Name>(methods[0])(keyword), sizeof(name)) != trace::AssetTraceStringCopyResult::Copied)
            return false;
        for (unsigned argument = 0; argument < arguments; ++argument)
            if (reinterpret_cast<Type>(methods[2])(keyword, argument) > 2) return false;
    }
    TtlStringView definition = {};
    reinterpret_cast<void(__fastcall*)(TtlStringView*)>(g_context.engine_base + 0x113AF0U)(&definition);
    bool copied = definition.data && definition.size && definition.size < capacity && definition.size <= 65536U &&
        ReadBytes(reinterpret_cast<std::uintptr_t>(definition.data), output, definition.size + 1U) &&
        output[definition.size] == 0 && !std::memchr(output, 0, definition.size);
    const auto bytes = definition.size;
    if (definition.data && free_pointer) free_pointer(const_cast<char*>(definition.data));
    if (!ReadBytes(g_context.engine_base + 0xAD5378U, &after, sizeof(after)) ||
        std::memcmp(&before, &after, sizeof(before)) || g_audio_definition_read_violation) copied = false;
    if (copied) *length = bytes;
    return copied;
}

bool PrepareAudioScriptReplayInput(const audio_baseline_content::Input& baseline,
                                  std::uint64_t deadline,AudioPreparedScriptInput* output) noexcept
{
    if (!output || output->handle || !baseline.script || !baseline.source.address || !baseline.source.generation ||
        !baseline.enter_sequence || !deadline || GetTickCount64() >= deadline || !g_audio_content_filesystem.validated)
        return false;
    *output = {};
    // This chooses the ORIGINAL B0 source, so preflight does not accidentally
    // hash the outgoing project's override before VFS detachment.
    const auto handle = audiocapture::OpenNativeFromSource(&g_audio_content_filesystem,
        baseline.source.address, baseline.logical_path);
    if (!handle) return false;
    struct FileCleanup {
        std::uintptr_t file; bool retained = false;
        ~FileCleanup() { if (!retained) (void)audiocapture::CloseNativeOwned(&g_audio_content_filesystem, file); }
    } cleanup{handle};
    file_lifetime::FileRecord opened = {};
    if (!filebridge::FileIdentity(&g_native_file_bridge, handle, &opened) ||
        opened.source.address != baseline.source.address || opened.source.generation != baseline.source.generation)
        return false;
    const auto bytes = audiocapture::LengthNativeOwned(&g_audio_content_filesystem, handle);
    if (bytes > 32U * 1024U * 1024U || GetTickCount64() >= deadline) return false;
    constexpr std::size_t definition_capacity = 65537U;
    const auto raw_size = static_cast<std::size_t>(bytes);
    const std::size_t raw_offset = definition_capacity;
    const std::size_t wide_offset = (raw_offset + raw_size + 1U) & ~std::size_t{1};
    const std::size_t wide_capacity = raw_size + definition_capacity + 5U;
    auto* memory = static_cast<unsigned char*>(VirtualAlloc(nullptr, wide_offset + wide_capacity * 2U,
        MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE));
    if (!memory) return false;
    struct MemoryCleanup { void* memory; ~MemoryCleanup() { VirtualFree(memory, 0, MEM_RELEASE); } } memory_cleanup{memory};
    auto* definition = reinterpret_cast<char*>(memory);
    auto* raw = memory + raw_offset;
    auto* wide = reinterpret_cast<std::uint16_t*>(memory + wide_offset);
    std::size_t definition_size = 0;
    if (!CaptureCurrentAudioDefinition(definition, definition_capacity, &definition_size)) return false;
    std::size_t position = 0;
    while (position < raw_size) {
        if (GetTickCount64() >= deadline) return false;
        const auto remaining = raw_size - position;
        const auto wanted = remaining < audiocapture::kReadChunk ? remaining : audiocapture::kReadChunk;
        const auto read = audiocapture::ReadNativeOwned(&g_audio_content_filesystem, handle, raw + position, wanted);
        if (!read || read > wanted) return false;
        position += static_cast<std::size_t>(read);
    }
    unsigned char extra = 0;
    if (audiocapture::ReadNativeOwned(&g_audio_content_filesystem, handle, &extra, 1U) != 0 ||
        GetTickCount64() >= deadline) return false;
    audio_script_input::Digest digest = {};
    if (audio_script_input::Compute(definition, definition_size, raw, raw_size, wide, wide_capacity, &digest) !=
            audio_script_input::Result::Succeeded || digest.bytes != baseline.bytes ||
        std::memcmp(digest.sha256, baseline.sha256, sizeof(digest.sha256)) || GetTickCount64() >= deadline) return false;
    file_lifetime::FileRecord after = {};
    if (!filebridge::FileIdentity(&g_native_file_bridge, handle, &after) || after.generation != opened.generation ||
        after.source.address != opened.source.address || after.source.generation != opened.source.generation) return false;
    output->file = after; output->digest = digest; output->handle = handle;
    output->baseline_enter_sequence = baseline.enter_sequence;
    CopyLoaderText(output->logical_path, sizeof(output->logical_path), baseline.logical_path);
    output->ready = true; cleanup.retained = true;
    return true;
}

bool ClosePreparedAudioScriptInputs() noexcept
{
    bool complete = true;
    for (auto& input : g_audio_prepared_script_inputs) {
        if (!input.handle) continue;
        if (!audiocapture::CloseNativeOwned(&g_audio_content_filesystem, input.handle)) { complete = false; continue; }
        input = {};
    }
    return complete;
}

