void __fastcall HookAudioScriptClear() noexcept
{
    ActiveHookCall call(g_audio_script_clear_status);
    AudioReplayInvocation retaining(0x113FB0U,g_context.engine_base+0xAD5308U);
    AudioDefinitionWriterScope definition_scope;
    const bool native_reload = g_audio_reload_owner_depth &&
        reinterpret_cast<std::uintptr_t>(_ReturnAddress())==g_context.engine_base+0x114070U;
    if (!retaining.admitted() || !definition_scope.admitted() || (!native_reload && !retaining.actual())) {
        dluma_atomic_exchange(&g_cold_reboot_registry.runtime_failure_latched,1);
        (void)dluma_frontend_error_present("Audio definition clear has no admitted owning caller",
            g_cold_reboot_registry.prepared_content_epoch);
        return;
    }
    // The sole native caller is admitted for its entire Reload invocation.
    // Production replay independently authenticates the actual clear entry.
    g_original_audio_script_clear();
    (void)audiostart::RecordAudioStartupMutationFence(&g_audio_startup_observation_ledger);
}

