std::uintptr_t __fastcall HookXuiManagerConstructor(void* manager, void* level) noexcept
{
    ActiveHookCall call(g_xui_manager_constructor_status);
    xui::ManagerToken token = {};
    std::uint32_t epoch = 0;
    const bool tracked = g_xui_manager_observation_ready &&
        content::TryGetCurrentEpochId(&g_content_ledger, &epoch) &&
        xui::BeginManagerConstruction(&g_xui_manager_ledger,
            reinterpret_cast<std::uintptr_t>(manager), reinterpret_cast<std::uintptr_t>(level), epoch, &token);
    if (!tracked) g_xui_manager_ledger.lost.store(true);
    // A constructor has no safe substitute return. Observe it and preserve the
    // natural caller; new-level admission is owned by the outer transaction.
    const std::uintptr_t result = g_original_xui_manager_constructor(manager, level);
    if (tracked) {
        xui::Access access = {};
        access.engine_base = g_context.engine_base;
        std::memcpy(access.sha256, xui::kPlayerEngineSha256, sizeof(access.sha256));
        access.read = &ReadProductionPlayerMemory;
        (void)xui::EndManagerConstruction(&g_xui_manager_ledger, &token, access, result);
    }
    return result;
}

std::uintptr_t __fastcall HookXuiManagerDestructor(void* manager) noexcept
{
    ActiveHookCall call(g_xui_manager_destructor_status);
    xui::ManagerToken token = {};
    const bool tracked = g_xui_manager_observation_ready &&
        xui::BeginManagerDestruction(&g_xui_manager_ledger, reinterpret_cast<std::uintptr_t>(manager), &token);
    if (!tracked) g_xui_manager_ledger.lost.store(true);
    const std::uintptr_t result = g_original_xui_manager_destructor(manager);
    if (tracked && xui::EndManagerDestruction(&g_xui_manager_ledger, &token)) {
        (void)xui_content::OwnerDestroyed(&g_xui_content_owner,
            {reinterpret_cast<std::uintptr_t>(manager),token.generation});
        (void)xui_instance::ManagerDestroyed(&g_xui_instances,
            {reinterpret_cast<std::uintptr_t>(manager),token.generation});
    }
    return result;
}

