bool IsRuntime15InventoryHookStatus(
    const HookStatusRecord* status) noexcept
{
    if (!status) return false;
    if (status == g_inventory_base_clear_status ||
        status == g_inventory_base_get_all_items_status)
        return true;
    for (std::size_t index = 0;
         index < DLUMA_ARRAY_COUNT(g_inventory_observer_slot_statuses);
         ++index)
        if (status == g_inventory_observer_slot_statuses[index])
            return true;
    return false;
}

