void BuildPlayerXmlInputObservationPlan() noexcept
{
    g_player_xml_input_route_validated = false;
    if (!g_gamedll_full_profile_valid || !g_load_variables_from_file_status ||
        !g_load_variables_from_file_status->validated)
        return;
    static constexpr std::uint8_t prefix[] = {
        0x48,0x89,0x5C,0x24,0x08,0x48,0x89,0x6C,0x24,0x10,
        0x48,0x89,0x74,0x24,0x18,0x57};
    static constexpr std::uint8_t before[] = {
        0x41,0xB0,0x01,0x48,0x8B,0xD7,0x48,0x8B,0xCE};
    static constexpr std::uint8_t after[] = {
        0x44,0x8B,0x5C,0x24,0x38,0x45,0x85,0xDB};
    g_player_xml_parse_input_status = AddHookStatus(
        "Player XML consumed-input digest", "gamedll_x64_rwdi.dll",
        g_context.gamedll_base + playerxml::kParseRva,
        playerxml::kParseRva, prefix, sizeof(prefix), false);
    g_player_xml_input_route_validated =
        g_player_xml_parse_input_status && g_player_xml_parse_input_status->validated &&
        ValidateRelativeCallSite(g_context.gamedll_base + 0x12CE7FDU,
            g_context.gamedll_base + playerxml::kParseRva, before, after) &&
        AddFunctionDetour(g_player_xml_parse_input_status,
            g_context.gamedll_base + playerxml::kParseRva, 16, 0, 0,
            reinterpret_cast<void*>(&dluma_player_xml_input_parse_probe)) != nullptr;
}

