bool AddVtableHook(HookStatusRecord** output, const char* name,
                   const char* module, std::uintptr_t module_base,
                   std::uintptr_t target_rva, std::uintptr_t vtable_rva,
                   std::uintptr_t slot_offset,
                   const std::uint8_t* prefix, std::size_t prefix_size,
                   void* hook, bool mandatory) noexcept
{
    HookStatusRecord* status = AddHookStatus(
        name, module, module_base + target_rva, target_rva, prefix,
        prefix_size, mandatory);
    if (output) *output = status;
    if (!status || !status->validated ||
        !AddPointerRoute(status, module_base + vtable_rva + slot_offset,
                         reinterpret_cast<void*>(module_base + target_rva),
                         hook))
        return false;
    return true;
}

bool FrontendUiRedirectOperational() noexcept
{
    return dluma_ui_main_menu_redirect_is_applied() != 0;
}

bool AddIatHook(HookStatusRecord** output, const char* name,
                const char* consumer_name, HMODULE consumer,
                HMODULE owner_module, std::uintptr_t owner_base,
                std::uintptr_t target_rva, const char* import_module,
                const char* export_name, const std::uint8_t* prefix,
                std::size_t prefix_size, void* hook,
                bool mandatory) noexcept
{
    FARPROC exported = GetProcAddress(owner_module, export_name);
    HookStatusRecord* status = AddHookStatus(
        name, import_module, reinterpret_cast<std::uintptr_t>(exported),
        target_rva, prefix, prefix_size, mandatory);
    if (status) status->route_module = consumer_name;
    if (output) *output = status;
    const std::uintptr_t slot =
        FindIatSlot(consumer, import_module, export_name);
    if (!status || reinterpret_cast<std::uintptr_t>(exported) !=
                       owner_base + target_rva ||
        !status->validated || !slot ||
        !AddPointerRoute(status, slot, reinterpret_cast<void*>(exported),
                         hook))
        return false;
    return true;
}

bool ValidateRipRelativeReference(
    std::uintptr_t address, const std::uint8_t* expected,
    std::size_t instruction_size, std::size_t displacement_offset,
    std::uintptr_t expected_target) noexcept
{
    std::int32_t displacement = 0;
    if (!address || !expected || instruction_size < 6 ||
        displacement_offset + sizeof(displacement) > instruction_size ||
        !BytesEqual(address, expected, instruction_size))
        return false;
    std::memcpy(&displacement, expected + displacement_offset,
                sizeof(displacement));
    return address + instruction_size +
               static_cast<std::intptr_t>(displacement) ==
           expected_target;
}

bool ValidateFsSourceRegistrySynchronization() noexcept
{
    static const std::uint8_t add_lock[] =
        {0x48,0x8D,0x0D,0x0F,0x01,0x04,0x00};
    static const std::uint8_t add_acquire[] =
        {0xFF,0x15,0x21,0xA8,0x02,0x00};
    static const std::uint8_t add_unlock[] =
        {0x48,0x8D,0x0D,0x8E,0xFF,0x03,0x00};
    static const std::uint8_t add_release[] =
        {0xFF,0x15,0xA8,0xA6,0x02,0x00};
    static const std::uint8_t path_lock[] =
        {0x48,0x8D,0x0D,0x33,0xFC,0x03,0x00};
    static const std::uint8_t path_acquire[] =
        {0xFF,0x15,0x3D,0xA3,0x02,0x00};
    static const std::uint8_t path_unlock[] =
        {0x48,0x8D,0x0D,0xE1,0xFA,0x03,0x00};
    static const std::uint8_t path_release[] =
        {0xFF,0x15,0xFB,0xA1,0x02,0x00};
    static const std::uint8_t object_lock[] =
        {0x48,0x8D,0x0D,0xA0,0xF8,0x03,0x00};
    static const std::uint8_t object_acquire[] =
        {0xFF,0x15,0xB2,0x9F,0x02,0x00};
    static const std::uint8_t object_pointer_compare[] =
        {0x49,0x3B,0x5B,0xF8};
    static const std::uint8_t object_absent_unlock[] =
        {0x48,0x8D,0x0D,0x6B,0xF8,0x03,0x00};
    static const std::uint8_t object_absent_release[] =
        {0xFF,0x15,0x85,0x9F,0x02,0x00};
    static const std::uint8_t object_success_unlock[] =
        {0x48,0x8D,0x0D,0x62,0xF7,0x03,0x00};
    static const std::uint8_t object_success_release[] =
        {0xFF,0x15,0x7C,0x9E,0x02,0x00};
    static const std::uint8_t object_compare_loop[] = {
        0x49,0x3B,0x5B,0xF8,0x74,0x1D,0x4D,0x8B,0x1B,0x4C,0x3B,0xD8,0x75,0xF2};
    static const std::uint8_t object_absent_return[] = {
        0x48,0x8D,0x0D,0x6B,0xF8,0x03,0x00,0xFF,0x15,0x85,0x9F,0x02,0x00,
        0x32,0xC0,0x48,0x83,0xC4,0x20,0x5B,0xC3};
    /* Registry construction and add-source list mutations independently
     * prove the intrusive link layout used by the synchronized B0 walker.
     * The list stores its source pointer at link-8, next at link+0 and prev
     * at link+8; the native fallback is appended last and retained both as
     * the tail and in its dedicated global. */
    static const std::uint8_t init_lock[] =
        {0x48,0x8D,0x0D,0xEE,0x0F,0x04,0x00};
    static const std::uint8_t init_tail_read[] =
        {0x48,0x8B,0x05,0x9A,0x08,0x04,0x00};
    static const std::uint8_t init_head_store[] =
        {0x48,0x89,0x0D,0x73,0x08,0x04,0x00};
    static const std::uint8_t init_count_increment[] =
        {0xFF,0x05,0x7D,0x08,0x04,0x00};
    static const std::uint8_t init_tail_store[] =
        {0x48,0x89,0x0D,0x6E,0x08,0x04,0x00};
    static const std::uint8_t init_fallback_zero[] =
        {0x48,0x89,0x1D,0x8F,0x0F,0x04,0x00};
    static const std::uint8_t fallback_vtable[] =
        {0x48,0x8D,0x05,0xE9,0xCB,0x02,0x00};
    static const std::uint8_t fallback_tail_read[] =
        {0x48,0x8B,0x05,0xB5,0x07,0x04,0x00};
    static const std::uint8_t fallback_head_store[] =
        {0x48,0x89,0x0D,0x84,0x07,0x04,0x00};
    static const std::uint8_t fallback_count_increment[] =
        {0xFF,0x05,0x8E,0x07,0x04,0x00};
    static const std::uint8_t fallback_tail_store[] =
        {0x48,0x89,0x0D,0x7F,0x07,0x04,0x00};
    static const std::uint8_t fallback_global_store[] =
        {0x48,0x89,0x05,0x9D,0x0E,0x04,0x00};
    static const std::uint8_t add_head_read[] =
        {0x48,0x8B,0x3D,0xC7,0xF9,0x03,0x00};
    static const std::uint8_t add_fallback_read[] =
        {0x48,0x8B,0x0D,0xE7,0x00,0x04,0x00};
    static const std::uint8_t add_head_store[] =
        {0x48,0x89,0x0D,0x1E,0xF9,0x03,0x00};
    static const std::uint8_t add_tail_read[] =
        {0x48,0x8B,0x05,0x19,0xF9,0x03,0x00};
    static const std::uint8_t add_tail_store[] =
        {0x48,0x89,0x0D,0xF3,0xF8,0x03,0x00};
    static const std::uint8_t add_count_increment[] =
        {0xFF,0x05,0xF5,0xF8,0x03,0x00};

    const std::uintptr_t lock =
        g_context.filesystem_base + kFsSourceRegistryLockRva;
    const std::uintptr_t head =
        g_context.filesystem_base + kFsSourceRegistryHeadRva;
    const std::uintptr_t tail =
        g_context.filesystem_base + kFsSourceRegistryTailRva;
    const std::uintptr_t count =
        g_context.filesystem_base + kFsSourceRegistryCountRva;
    const std::uintptr_t fallback =
        g_context.filesystem_base + kFsSourceRegistryFallbackRva;
    const std::uintptr_t acquire_slot = FindIatSlot(
        g_context.filesystem_module, "KERNEL32.dll",
        "AcquireSRWLockExclusive");
    const std::uintptr_t release_slot = FindIatSlot(
        g_context.filesystem_module, "KERNEL32.dll",
        "ReleaseSRWLockExclusive");
    if (acquire_slot != g_context.filesystem_base + 0x0003E1E8U ||
        release_slot != g_context.filesystem_base + 0x0003E1F0U) {
        g_fs_source_registry_layout_validated = false;
        return false;
    }

    const bool validated =
        ValidateRipRelativeReference(g_context.filesystem_base + 0x000139BAU,
            add_lock, sizeof(add_lock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x000139C1U,
            add_acquire, sizeof(add_acquire), 2, acquire_slot) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013B3BU,
            add_unlock, sizeof(add_unlock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013B42U,
            add_release, sizeof(add_release), 2, release_slot) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013E96U,
            path_lock, sizeof(path_lock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013EA5U,
            path_acquire, sizeof(path_acquire), 2, acquire_slot) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013FE8U,
            path_unlock, sizeof(path_unlock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013FEFU,
            path_release, sizeof(path_release), 2, release_slot) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00014229U,
            object_lock, sizeof(object_lock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00014230U,
            object_acquire, sizeof(object_acquire), 2, acquire_slot) &&
        BytesEqual(g_context.filesystem_base + 0x00014250U,
                   object_pointer_compare,
                   sizeof(object_pointer_compare)) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x0001425EU,
            object_absent_unlock, sizeof(object_absent_unlock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00014265U,
            object_absent_release, sizeof(object_absent_release), 2,
            release_slot) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00014367U,
            object_success_unlock, sizeof(object_success_unlock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x0001436EU,
            object_success_release, sizeof(object_success_release), 2,
            release_slot) &&
        BytesEqual(g_context.filesystem_base + 0x00014250U,
                   object_compare_loop, sizeof(object_compare_loop)) &&
        BytesEqual(g_context.filesystem_base + 0x0001425EU,
                   object_absent_return, sizeof(object_absent_return)) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012ADBU,
            init_lock, sizeof(init_lock), 3, lock) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012AFFU,
            init_tail_read, sizeof(init_tail_read), 3, tail) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012B1EU,
            init_head_store, sizeof(init_head_store), 3, head) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012B25U,
            init_count_increment, sizeof(init_count_increment), 2, count) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012B2BU,
            init_tail_store, sizeof(init_tail_store), 3, tail) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012B32U,
            init_fallback_zero, sizeof(init_fallback_zero), 3, fallback) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012B58U,
            fallback_vtable, sizeof(fallback_vtable), 3,
            g_context.filesystem_base + kFallbackSourceVtableRva) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012BE4U,
            fallback_tail_read, sizeof(fallback_tail_read), 3, tail) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012C0DU,
            fallback_head_store, sizeof(fallback_head_store), 3, head) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012C14U,
            fallback_count_increment, sizeof(fallback_count_increment), 2,
            count) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012C1AU,
            fallback_tail_store, sizeof(fallback_tail_store), 3, tail) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00012C24U,
            fallback_global_store, sizeof(fallback_global_store), 3,
            fallback) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x000139CAU,
            add_head_read, sizeof(add_head_read), 3, head) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x000139DAU,
            add_fallback_read, sizeof(add_fallback_read), 3, fallback) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013A73U,
            add_head_store, sizeof(add_head_store), 3, head) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013A80U,
            add_tail_read, sizeof(add_tail_read), 3, tail) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013AA6U,
            add_tail_store, sizeof(add_tail_store), 3, tail) &&
        ValidateRipRelativeReference(g_context.filesystem_base + 0x00013AADU,
            add_count_increment, sizeof(add_count_increment), 2, count);
    g_fs_source_registry_layout_validated = validated;
    return validated;
}

bool ValidateIndirectBoundary(std::uintptr_t call_rva,
                              const std::uint8_t expected[6],
                              std::uintptr_t expected_slot) noexcept
{
    const std::uintptr_t callsite = g_context.gamedll_base + call_rva;
    if (!BytesEqual(callsite, expected, 6) || expected[0] != 0xFF ||
        expected[1] != 0x15)
        return false;
    std::int32_t displacement = 0;
    std::memcpy(&displacement, expected + 2, sizeof(displacement));
    return callsite + 6 + static_cast<std::intptr_t>(displacement) ==
           expected_slot;
}

bool ValidateIndirectCallSite(std::uintptr_t callsite,
                              std::uintptr_t expected_slot) noexcept
{
    std::uint8_t call[6] = {};
    std::int32_t displacement = 0;
    if (!callsite || !expected_slot ||
        !ReadBytes(callsite, call, sizeof(call)) ||
        call[0] != 0xFF || call[1] != 0x15)
        return false;
    std::memcpy(&displacement, call + 2, sizeof(displacement));
    return callsite + sizeof(call) +
               static_cast<std::intptr_t>(displacement) ==
           expected_slot;
}

bool ValidateKnownPlayerStateCreatorSites() noexcept
{
    /* These are the four currently named direct RTTI CreateObject sites in
     * the supported Player image.  Generic/name-based RTTI creation remains
     * possible, so validating them is useful owner evidence but is not a
     * closed allocation-set proof.  Class-wide ctor/dtor observers cover
     * later generic creation; pre-install live instances remain unresolved. */
    static const std::uint8_t factory_prefix[] = {
        0x48,0x83,0xEC,0x28,0xB9,0xB0,0x04,0x00,
        0x00,0xFF,0x15,0xE1,0xCE,0x80,0x00,0x48,
        0x85,0xC0,0x74,0x0C,0x48,0x8B,0xC8,0x48,
        0x83,0xC4,0x28,0xE9,0x80,0x6A,0xFF,0xFF,
        0x48,0x83,0xC4,0x28,0xC3};
    static const std::uint8_t game_local_rtti[] =
        {0x48,0x8D,0x15,0xEF,0x8A,0x9C,0x01};
    static const std::uint8_t game_local_call[] =
        {0xFF,0x15,0xC0,0xCD,0x00,0x01};
    static const std::uint8_t game_local_owner_store[] =
        {0x48,0x89,0x86,0x20,0x05,0x00,0x00,
         0x48,0x89,0x05,0xB8,0x77,0x94,0x01};
    static const std::uint8_t game_character_rtti[] =
        {0x48,0x8D,0x15,0x74,0x89,0x9C,0x01};
    static const std::uint8_t game_character_call[] =
        {0xFF,0x15,0x45,0xCC,0x00,0x01};
    static const std::uint8_t game_character_owner_store[] =
        {0x48,0x89,0x86,0x28,0x05,0x00,0x00,
         0x48,0x89,0x05,0x87,0x78,0x94,0x01};
    static const std::uint8_t player_di_rtti[] =
        {0x48,0x8D,0x15,0x57,0x27,0x28,0x01};
    static const std::uint8_t player_di_call[] =
        {0xFF,0x15,0x28,0x6A,0x8C,0x00};
    static const std::uint8_t player_di_owner_store[] =
        {0x48,0x89,0x87,0x50,0x0E,0x00,0x00};
    static const std::uint8_t tutorial_rtti[] =
        {0x48,0x8D,0x15,0xE5,0x21,0x17,0x01};
    static const std::uint8_t tutorial_call[] =
        {0xFF,0x15,0xB6,0x64,0x7B,0x00};
    static const std::uint8_t tutorial_owner_store[] =
        {0x49,0x89,0x84,0x24,0x50,0x0E,0x00,0x00};

    void* factory_slot0 = nullptr;
    void* factory_slot1 = nullptr;
    const std::uintptr_t factory =
        g_context.gamedll_base + kPlayerStateRttiFactoryRva;
    const std::uintptr_t rtti =
        g_context.gamedll_base + kPlayerStateRttiObjectRva;
    const std::uintptr_t create_object_iat =
        g_context.gamedll_base + 0x013CCC90U;
    return g_gamedll_full_profile_valid &&
        BytesEqual(factory, factory_prefix, sizeof(factory_prefix)) &&
        ReadBytes(g_context.gamedll_base +
                      kPlayerStateRttiFactorySlot0Rva,
                  &factory_slot0, sizeof(factory_slot0)) &&
        ReadBytes(g_context.gamedll_base +
                      kPlayerStateRttiFactorySlot1Rva,
                  &factory_slot1, sizeof(factory_slot1)) &&
        factory_slot0 == reinterpret_cast<void*>(factory) &&
        factory_slot1 == reinterpret_cast<void*>(factory) &&
        ValidateRipRelativeReference(
            g_context.gamedll_base + 0x003BFEBAU,
            game_local_rtti, sizeof(game_local_rtti), 3, rtti) &&
        ValidateIndirectBoundary(kGameDiLocalPlayerStateCreateCallRva,
                                 game_local_call, create_object_iat) &&
        BytesEqual(g_context.gamedll_base + 0x003BFED2U,
                   game_local_owner_store,
                   sizeof(game_local_owner_store)) &&
        ValidateRipRelativeReference(
            g_context.gamedll_base + 0x003C0035U,
            game_character_rtti, sizeof(game_character_rtti), 3, rtti) &&
        ValidateIndirectBoundary(
            kGameDiCharacterPlayerStateCreateCallRva,
            game_character_call, create_object_iat) &&
        BytesEqual(g_context.gamedll_base + 0x003C005BU,
                   game_character_owner_store,
                   sizeof(game_character_owner_store)) &&
        ValidateRipRelativeReference(
            g_context.gamedll_base + 0x00B06252U,
            player_di_rtti, sizeof(player_di_rtti), 3, rtti) &&
        ValidateIndirectBoundary(kPlayerDiPlayerStateCreateCallRva,
                                 player_di_call, create_object_iat) &&
        BytesEqual(g_context.gamedll_base + 0x00B06279U,
                   player_di_owner_store,
                   sizeof(player_di_owner_store)) &&
        ValidateRipRelativeReference(
            g_context.gamedll_base + 0x00C167C4U,
            tutorial_rtti, sizeof(tutorial_rtti), 3, rtti) &&
        ValidateIndirectBoundary(kTutorialPlayerStateCreateCallRva,
                                 tutorial_call, create_object_iat) &&
        BytesEqual(g_context.gamedll_base + 0x00C167EDU,
                   tutorial_owner_store,
                   sizeof(tutorial_owner_store));
}

bool ValidateAtomicRouteMutationSafety() noexcept
{
    if (!IsProcessorFeaturePresent(PF_COMPARE_EXCHANGE128)) return false;
    for (std::size_t index = 0; index < g_hook_route_count; ++index) {
        const HookRoute& route = g_hook_routes[index];
        if (!route.enabled) continue;
        if (route.kind == HookRouteKind::Pointer) {
            if ((route.address & (sizeof(void*) - 1)) != 0 ||
                route.byte_count != sizeof(void*))
                return false;
            continue;
        }
        if ((route.kind != HookRouteKind::FunctionDetour && route.kind != HookRouteKind::InteriorEnvelope) ||
            (route.address & (kAtomicDetourSize - 1)) != 0 ||
            route.byte_count != kAtomicDetourSize ||
            route.stolen_size < kAtomicDetourSize ||
            route.stolen_size > kMaximumStolenBytes)
            return false;
    }
    return true;
}

