void BuildCurveHookPlan() noexcept
{
    if (!g_gamedll_full_profile_valid) return;
    std::size_t count = 0;
    const auto* catalog = curves::CurveHookCatalog(&count);
    if (!catalog || count != curves::kCurveHookCount) return;
    for (std::size_t i = 0; i < count; ++i) {
        const auto& d = catalog[i];
        const auto target = g_context.gamedll_base + d.function_rva;
        auto* wrapper = reinterpret_cast<void*>(curves::CurveHookWrapper(d.kind));
        if (d.pointer_slot_rva) {
            g_curve_hook_status[i] = AddHookStatus(d.name, "gamedll_x64_rwdi.dll",
                g_context.gamedll_base + d.pointer_slot_rva, d.pointer_slot_rva,
                reinterpret_cast<const std::uint8_t*>(&target), sizeof(target), false);
            g_curve_hook_routes[i] = AddPointerRoute(g_curve_hook_status[i],
                g_context.gamedll_base + d.pointer_slot_rva, reinterpret_cast<void*>(target), wrapper);
        } else {
            g_curve_hook_status[i] = AddHookStatus(d.name, "gamedll_x64_rwdi.dll",
                target, d.function_rva, d.prefix, d.prefix_size, false);
            g_curve_hook_routes[i] = AddFunctionDetour(g_curve_hook_status[i], target,
                d.stolen_bytes, d.displacement_offset < 0 ? 0U : static_cast<std::size_t>(d.displacement_offset),
                d.instruction_end < 0 ? 0U : static_cast<std::size_t>(d.instruction_end), wrapper,
                d.second_displacement_offset, d.second_instruction_end, d.trailing_branch_offset);
        }
    }
}

void DisableUninstalledCurveRoutes() noexcept
{
    for (std::size_t i = 0; i < curves::kCurveHookCount; ++i) {
        auto* route = g_curve_hook_routes[i];
        if (!route || route->installed) continue;
        route->enabled = false;
        if (route->owner) route->owner->route_count = 0;
        FreeRouteRelay(route);
    }
    g_curve_hooks_prepared = g_curve_hooks_available = false;
    g_curve_startup_install_scope = false;
}

