void PrepareXuiManagerObservation() noexcept
{
    const HookRoute* routes[] = {g_xui_manager_constructor_route, g_xui_manager_destructor_route};
    g_xui_manager_startup_prepared = false;
    for (const auto* route : routes)
        if (!route || !route->enabled || !route->owner || !route->owner->validated || !route->relay) return;
    g_xui_manager_startup_prepared = ExactIsolationStartupOwnerAbsence() &&
        xui::SealManagerStartup(&g_xui_manager_ledger) && xui_content::SealStartup(&g_xui_content_owner);
    if(g_xui_manager_startup_prepared)(void)xui_instance::SealStartup(&g_xui_instances);
}

void SealXuiManagerObservation() noexcept
{
    g_xui_manager_observation_ready = g_xui_manager_startup_prepared &&
        g_xui_manager_constructor_status && g_xui_manager_constructor_status->installed &&
        g_xui_manager_destructor_status && g_xui_manager_destructor_status->installed &&
        ExactIsolationStartupOwnerAbsence();
    if (!g_xui_manager_observation_ready) g_xui_manager_ledger.lost.store(true);
    g_xui_instance_observation_ready=g_xui_manager_observation_ready;
    for(const auto* status:g_xui_factory_statuses)
        if(!status||!status->validated||!status->installed)g_xui_instance_observation_ready=false;
    if(!g_xui_instance_observation_ready)g_xui_instances.lost.store(true);
}

void BuildTextHookPlan() noexcept
{
    if (!g_engine_full_profile_valid) return;
    struct Layout { std::uint8_t stolen, displacement, instruction_end; };
    static constexpr Layout layout[texts::kTextHookCount] = {
        {16,0,0},{20,0,0},{16,0,0},{19,15,19},{16,5,9},{17,13,17},
        {17,0,0},{16,0,0},{21,17,21},{19,0,0},{16,0,0},{16,0,0},
        {20,0,0},{19,15,19},{20,0,0},{17,0,0},{0,0,0}};
    std::size_t count = 0;
    const auto* catalog = texts::TextHookCatalog(&count);
    if (!catalog || count != texts::kTextHookCount) return;
    for (std::size_t i = 0; i < count; ++i) {
        const auto& d = catalog[i];
        const auto target = g_context.engine_base + d.function_rva;
        auto* wrapper = reinterpret_cast<void*>(texts::TextHookWrapper(d.kind));
        if (d.pointer_slot_rva) {
            g_text_hook_status[i] = AddHookStatus(d.name, "engine_x64_rwdi.dll",
                g_context.engine_base + d.pointer_slot_rva, d.pointer_slot_rva,
                reinterpret_cast<const std::uint8_t*>(&target), sizeof(target), false);
            g_text_hook_routes[i] = AddPointerRoute(g_text_hook_status[i],
                g_context.engine_base + d.pointer_slot_rva,
                reinterpret_cast<void*>(target), wrapper);
        } else {
            g_text_hook_status[i] = AddHookStatus(d.name, "engine_x64_rwdi.dll",
                target, d.function_rva, d.original_prefix, sizeof(d.original_prefix), false);
            g_text_hook_routes[i] = AddFunctionDetour(g_text_hook_status[i], target,
                layout[i].stolen, layout[i].displacement, layout[i].instruction_end, wrapper);
        }
    }
}

void DisableUninstalledTextRoutes() noexcept
{
    for (std::size_t i = 0; i < texts::kTextHookCount; ++i) {
        HookRoute* route = g_text_hook_routes[i];
        if (!route || route->installed) continue;
        route->enabled = false;
        if (route->owner) route->owner->route_count = 0;
        FreeRouteRelay(route);
    }
    g_text_hooks_prepared = false;
    g_text_hooks_available = false;
}

void PrepareTextHookBridge() noexcept
{
    std::uintptr_t originals[texts::kTextHookCount] = {};
    DlumaIsolationScriptEntryObservation observed = {};
    if (!g_engine_full_profile_valid || !dluma_isolation_snapshot_script_entry(&observed)) {
        DisableUninstalledTextRoutes(); return;
    }
    for (std::size_t i = 0; i < texts::kTextHookCount; ++i) {
        const HookRoute* route = g_text_hook_routes[i];
        if (!route || !route->enabled || !route->owner || !route->owner->validated ||
            (route->kind == HookRouteKind::FunctionDetour && !route->relay)) {
            DisableUninstalledTextRoutes(); return;
        }
        originals[i] = reinterpret_cast<std::uintptr_t>(
            route->kind == HookRouteKind::FunctionDetour ? route->relay : route->original_target);
    }
    const texts::ObservedTextStartup startup = {
        reinterpret_cast<std::uintptr_t>(observed.return_address),
        reinterpret_cast<std::uintptr_t>(observed.callback_address), observed.thread_id};
    g_text_hooks_prepared = texts::InitializeTextGate(&g_text_observation_gate,
        g_context.engine_base, texts::kPlayerEngineSha256, &ReadAudioBaselineMemory,
        nullptr, originals, texts::kTextHookCount, &startup) == texts::TextGateResult::Succeeded &&
        texts::BindTextHookBridge(&g_text_observation_gate) == texts::TextGateResult::Succeeded;
    if (!g_text_hooks_prepared) DisableUninstalledTextRoutes();
}

void SealTextHookBridge() noexcept
{
    g_text_hooks_available = g_text_hooks_prepared &&
        texts::SealTextHookStartup(&g_text_observation_gate) == texts::TextGateResult::Succeeded;
    // A partial install keeps its valid pass-through relays pinned. It cannot
    // authorize B0 capture or destructive text replacement.
    dluma_log_pair("FIX", "isolation_localized_text_owner",
        g_text_hooks_available ? "startup_sealed" : "unsupported_incomplete_observation");
}

bool ReadNativeFileBridgeMemory(void*, std::uintptr_t address, void* output, std::size_t size) noexcept
{
    return ReadBytes(address, output, size);
}

void PrepareNativeFileBridge() noexcept
{
    g_native_file_bridge_prepared = false;
    std::memset(g_native_file_statuses, 0, sizeof(g_native_file_statuses));
    if (!g_fix_enabled || !g_filesystem_full_profile_valid) return;
    // The loaded file's SHA was independently compared to this exact value
    // by Initialize before this in-memory prefix/vtable validation pass.
    g_native_file_bridge_prepared = filebridge::Prepare(&g_native_file_bridge,
        g_context.filesystem_base, kSupportedFilesystemSha256,
        &ReadNativeFileBridgeMemory, nullptr);
    if (g_native_file_bridge_prepared) {
        g_native_file_bridge_prepared = files::ConfigureFactoryReplayValidator(&g_native_file_bridge.ledger,
            &ValidateProductionFactoryReplayAuthorization, nullptr);
        g_native_file_bridge_prepared = g_native_file_bridge_prepared &&
            filebridge::ConfigureRegistryAdmission(&g_native_file_bridge,&g_cold_reboot_registry,&g_content_live);
        g_native_file_bridge.authorize_factory = &AuthorizeProductionReplayFactory;
        g_archive_input_observer_ready = ConfigureProductionArchiveInputs();
    }
}

bool BuildNativeFileHookPlan() noexcept
{
    if (!g_fix_enabled) return true;
    if (!g_native_file_bridge_prepared) return false;
    static const char* const names[] = {
        "file lifetime: public open", "file lifetime: native open",
        "file lifetime: Win32 factory", "file lifetime: async factory",
        "file lifetime: directory read", "file lifetime: directory write",
        "file lifetime: zip factory", "file lifetime: memory factory",
        "file lifetime: async constructor", "file lifetime: memory constructor",
        "file lifetime: Win32 destructor", "file lifetime: async destructor",
        "file lifetime: gzip destructor", "file lifetime: zip destructor",
        "file lifetime: memory destructor", "file lifetime: base destructor",
        "file lifetime: queue schedule", "file lifetime: cancellation completion",
        "file lifetime: skipped completion", "file lifetime: read completion",
        "file lifetime: directory source destruction", "file lifetime: pack source destruction",
        "file lifetime: fallback source destruction"};
    static_assert(DLUMA_ARRAY_COUNT(names) == static_cast<unsigned>(filewin::Route::Count));
    std::size_t count = 0;
    const auto* specs = filewin::HookPlan(&count);
    for (std::size_t i = 0; i < count; ++i) {
        const auto& spec = specs[i];
        const auto index = static_cast<unsigned>(spec.route);
        const auto target = g_context.filesystem_base + spec.rva;
        void* hook = spec.route == filewin::Route::PublicOpen ? reinterpret_cast<void*>(&HookFsOpen) :
            spec.route == filewin::Route::NativeOpen ? reinterpret_cast<void*>(&HookAudioFsOpenNative) : filebridge::HookTarget(spec.route);
        if (!hook) return false;
        HookRoute* existing = nullptr;
        for (std::size_t n = 0; n < g_hook_route_count; ++n) {
            auto& route = g_hook_routes[n];
            if (!route.enabled || route.kind != HookRouteKind::FunctionDetour || route.address != target) continue;
            if (route.hook_target != hook || existing) return false;
            existing = &route;
        }
        if (existing) {
            existing->owner->mandatory = true;
            g_native_file_statuses[index] = existing->owner;
            continue;
        }
        auto* status = AddHookStatus(names[index], "filesystem_x64_rwdi.dll", target,
            spec.rva, spec.prefix, spec.prefix_size, true);
        g_native_file_statuses[index] = status;
        if (!status || !status->validated) return false;
        if (spec.role == filewin::Role::InteriorCompletion) {
            if (g_hook_route_count >= kMaximumHookRoutes) return false;
            auto& route = g_hook_routes[g_hook_route_count++];
            std::memset(&route, 0, sizeof(route));
            route.owner = status;
            route.kind = HookRouteKind::InteriorEnvelope;
            route.address = target & ~std::uintptr_t{15};
            route.original_target = reinterpret_cast<void*>(target);
            route.hook_target = hook;
            route.byte_count = route.stolen_size = 16;
            route.interior_route = static_cast<std::uint8_t>(spec.route);
            if (!ReadBytes(route.address, route.original_bytes, 16)) return false;
            route.enabled = true;
            ++status->route_count;
        } else {
            filewin::EntryRelocation relocation = {};
            if (!filewin::EntryRelocationFor(spec.route, &relocation) ||
                !AddFunctionDetour(status, target, relocation.stolen_size,
                    relocation.rip_offset, relocation.rip_end, hook)) return false;
        }
    }
    return true;
}

bool SealNativeFileBridge() noexcept
{
    g_native_factory_resolvers_sealed = true;
    if (!g_fix_enabled) return true;
    if (!g_native_file_bridge_prepared) return false;
    std::uint64_t mask = 0;
    for (unsigned i = 0; i < static_cast<unsigned>(filewin::Route::Count); ++i)
        if (g_native_file_statuses[i] && g_native_file_statuses[i]->installed)
            mask |= std::uint64_t{1} << i;
    vfs::FilesystemSourceInventory inventory = {};
    if (!CaptureCurrentFilesystemInventory(&inventory)) {
        files::RecordCoverageLoss(&g_native_file_bridge.ledger, files::Failure::HookCoverage);
        return false;
    }
    for (std::uint32_t i = 0; i < inventory.source_count; ++i)
        if (!filebridge::ExistingSource(&g_native_file_bridge, inventory.sources[i].source)) return false;
    return filebridge::Seal(&g_native_file_bridge, mask);
}

