void AppendIdentity(char* output, std::size_t capacity, const char* name,
                    std::uint32_t timestamp,
                    std::uint32_t image_size) noexcept
{
    char number[32];
    CopyLiteral(output, capacity, name);
    dluma_str_append(output, static_cast<unsigned int>(capacity),
                   " timestamp=0x");
    dluma_u32_hex(timestamp, number, sizeof(number));
    dluma_str_append(output, static_cast<unsigned int>(capacity), number);
    dluma_str_append(output, static_cast<unsigned int>(capacity),
                   " size=0x");
    dluma_u32_hex(image_size, number, sizeof(number));
    dluma_str_append(output, static_cast<unsigned int>(capacity), number);
}

void BuildEnabledHookList(char* output, std::size_t capacity) noexcept
{
    output[0] = 0;
    for (std::size_t i = 0; i < g_hook_status_count; ++i) {
        const HookStatusRecord& status = g_hook_statuses[i];
        if (!status.installed) continue;
        if (output[0])
            dluma_str_append(output, static_cast<unsigned int>(capacity), ",");
        dluma_str_append(output, static_cast<unsigned int>(capacity),
                       status.name);
    }
    dluma_str_append(output, static_cast<unsigned int>(capacity),
                   ";post_unload_return=0x434DD6");
    dluma_str_append(output, static_cast<unsigned int>(capacity),
                   ";optional_asset_manager=unresolved");
    if (!g_on_demand_available)
        dluma_str_append(output, static_cast<unsigned int>(capacity),
                       ";optional_on_demand=unresolved");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_internal_pack_release_available
            ? ";optional_internal_level_pack_release=exact"
            : ";optional_internal_level_pack_release=unresolved");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_campaign_trace_available
            ? ";campaign_manager_load=exact;scampaign_addmap=exact-inlined-sequence"
            : ";campaign_manager_load=unavailable;scampaign_addmap=unavailable");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        ";campaign_natural_lifecycle=unresolved");
    dluma_str_append(output, static_cast<unsigned int>(capacity),
                   ";custom_content_name=unresolved");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_script_trace_available
            ? ";script_parser_observer=exact-watched-only;script_registry_owner=unresolved"
            : ";script_parser_observer=unavailable;script_registry_owner=unresolved");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_player_state_inventory_trace_available
            ? (g_player_inventory_bootstrap_evidence.
                       closed_creator_set_validated
                   ? ";player_state_inventory_observer=classwide-routes-installed;player_state_preinstall_completeness=engine-callback-proof"
                   : ";player_state_inventory_observer=classwide-routes-installed;player_state_preinstall_completeness=unresolved")
            : ";player_state_inventory_observer=unavailable");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_player_progression_trace_available
            ? ";player_progression_observer=exact;effective_fov_observation=unavailable"
            : ";player_progression_observer=unavailable;effective_fov_observation=unavailable");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_audio_trace_available
            ? ";audiodata_audio_bank_observers=exact-filtered;speech_registry_writer_surface=exact-gated;audio_main_menu_procedure_observer=exact-current-registry-only"
            : ";audiodata_audio_bank_observers=unavailable");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_material_trace_available
            ? ";assets_pc_file_observer=exact-watch;material_observer=exact"
            : ";assets_pc_file_observer=exact-watch;material_observer=unavailable");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_engine_full_profile_valid
            ? ";engine_full_sha256_profile=validated"
            : ";engine_full_sha256_profile=unavailable");
    dluma_str_append(
        output, static_cast<unsigned int>(capacity),
        g_gamedll_full_profile_valid
            ? ";gamedll_full_sha256_profile=validated"
            : ";gamedll_full_sha256_profile=unavailable");
    dluma_str_append(output, static_cast<unsigned int>(capacity),
                   ";watched_assets=");
    for (std::uint32_t index = 0;
         index < g_asset_watch_list.count; ++index) {
        if (index)
            dluma_str_append(output, static_cast<unsigned int>(capacity), "|");
        dluma_str_append(output, static_cast<unsigned int>(capacity),
                       g_asset_watch_list.paths[index]);
    }
}

void BuildTraceStartText(char* output, std::size_t capacity) noexcept
{
    char number[32];
    FILETIME file_time = {};
    GetSystemTimeAsFileTime(&file_time);
    const std::uint64_t timestamp =
        (static_cast<std::uint64_t>(file_time.dwHighDateTime) << 32) |
        file_time.dwLowDateTime;
    CopyLiteral(output, capacity, "utc_filetime=");
    dluma_u64_to_text(timestamp, number, sizeof(number));
    dluma_str_append(output, static_cast<unsigned int>(capacity), number);
}

bool WriteTraceHeader() noexcept
{
    AssetTraceHeader header = {};
    LARGE_INTEGER qpc = {};
    LARGE_INTEGER frequency = {};
    char line[8192];
    std::size_t written = 0;
    DWORD file_written = 0;
    header.process_id = GetCurrentProcessId();
    QueryPerformanceFrequency(&frequency);
    QueryPerformanceCounter(&qpc);
    header.qpc_frequency = frequency.QuadPart > 0
                               ? static_cast<std::uint64_t>(frequency.QuadPart)
                               : 0;
    header.trace_start_qpc = qpc.QuadPart > 0
                                 ? static_cast<std::uint64_t>(qpc.QuadPart)
                                 : 0;
    CopyLiteral(header.loader_version, sizeof(header.loader_version),
                DLUMA_VERSION);
    BuildTraceStartText(header.trace_start_time,
                        sizeof(header.trace_start_time));
    AppendIdentity(header.gamedll_identity, sizeof(header.gamedll_identity),
                   "gamedll_x64_rwdi.dll", g_context.gamedll_timestamp,
                   g_context.gamedll_size_of_image);
    AppendIdentity(header.engine_identity, sizeof(header.engine_identity),
                   "engine_x64_rwdi.dll", g_context.engine_timestamp,
                   g_context.engine_size_of_image);
    AppendIdentity(header.filesystem_identity,
                   sizeof(header.filesystem_identity),
                   "filesystem_x64_rwdi.dll", g_context.filesystem_timestamp,
                   g_context.filesystem_size_of_image);
    BuildEnabledHookList(header.enabled_hooks, sizeof(header.enabled_hooks));
    if (!trace::FormatHeaderLine(header, g_watch_list, line, sizeof(line),
                                 &written) ||
        written > 0xFFFFFFFFU)
        return false;
    return WriteFile(g_trace_file, line, static_cast<DWORD>(written),
                     &file_written, nullptr) && file_written == written;
}

bool WriteSummaryFile() noexcept
{
    const content::LedgerLossState losses =
        content::CaptureLossState(&g_content_ledger);
    const bool ownership_complete =
        losses.ownership_mutation_loss == 0;
    trace::ConfigureSummaryObservers(
        &g_summary, g_campaign_trace_available,
        g_internal_pack_release_available);
    const trace::CurrentObserverAdmission admission = {
        dluma_atomic_compare_exchange(&g_trace_live, 0, 0) != 0,
        dluma_atomic_compare_exchange(&g_content_live, 0, 0) != 0,
        g_trace_file != INVALID_HANDLE_VALUE,
        dluma_atomic_compare_exchange(&g_trace_stopping, 0, 0) != 0,
        g_material_trace_available &&
            dluma_atomic_compare_exchange(&g_trace_stopping, 0, 0) == 0,
        g_player_progression_trace_available &&
            dluma_atomic_compare_exchange(&g_trace_stopping, 0, 0) == 0};
    trace::ConfigureSummaryReportState(
        &g_summary, g_installed_observer_capabilities, admission,
        static_cast<std::uint64_t>(_InterlockedCompareExchange64(
            &g_report_generation, 0, 0)),
        g_report_finalized,
        g_trace_records_drained_through_sequence,
        g_ledger_snapshot_sequence, g_trace_summary_sequence);
    const trace::CampaignObservationCompleteness campaign =
        trace::EvaluateCampaignCompleteness(g_summary);
    g_summary.custom_campaign_load_observation_complete =
        campaign.custom_complete;
    g_summary.frontend_campaign_lifecycle_observation_complete =
        campaign.frontend_complete;
    g_summary.base_campaign_observation_complete = campaign.base_complete;
    CopyLiteral(g_summary.frontend_campaign_lifecycle_state,
                sizeof(g_summary.frontend_campaign_lifecycle_state),
                campaign.frontend_state);
    trace::CaptureLossDomainStats(&g_summary);
    trace::ConfigureSummaryLedgerCompleteness(
        &g_summary, ownership_complete, ownership_complete,
        ownership_complete, losses.broad_file_observation_loss,
        losses.broad_file_first_loss_sequence,
        losses.broad_file_last_loss_sequence,
        content::LedgerLossReasonName(
            losses.last_broad_file_reason));
    std::size_t written = 0;
    if (!trace::FormatSummary(g_summary, g_summary_buffer,
                              sizeof(g_summary_buffer), &written) ||
        written > 0xFFFFFFFFU)
        return false;
    HANDLE file = CreateFileW(
        g_summary_path, GENERIC_WRITE,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
        CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) return false;
    DWORD file_written = 0;
    const bool write_succeeded =
        WriteFile(file, g_summary_buffer, static_cast<DWORD>(written),
                  &file_written, nullptr) != FALSE &&
        file_written == written;
    const bool flush_succeeded =
        write_succeeded && FlushFileBuffers(file) != FALSE;
    const bool close_succeeded = CloseHandle(file) != FALSE;
    return write_succeeded && flush_succeeded && close_succeeded;
}

bool OpenTraceOutputs() noexcept
{
    WCHAR runtime_dir[DLUMA_MAX_WPATH];
    dluma_path_join(runtime_dir, DLUMA_ARRAY_COUNT(runtime_dir),
                  g_dluma.module_dir, L"dluma_runtime");
    CreateDirectoryW(runtime_dir, nullptr);
    dluma_path_join(g_trace_path, DLUMA_ARRAY_COUNT(g_trace_path), runtime_dir,
                  L"custom_map_asset_trace.log");
    dluma_path_join(g_summary_path, DLUMA_ARRAY_COUNT(g_summary_path), runtime_dir,
                  L"custom_map_asset_trace_summary.txt");
    g_trace_file = CreateFileW(
        g_trace_path, GENERIC_WRITE,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
        CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (g_trace_file == INVALID_HANDLE_VALUE) return false;
    if (!WriteTraceHeader()) {
        CloseHandle(g_trace_file);
        g_trace_file = INVALID_HANDLE_VALUE;
        return false;
    }
    if (!WriteSummaryFile()) {
        CloseHandle(g_trace_file);
        g_trace_file = INVALID_HANDLE_VALUE;
        return false;
    }
    return true;
}

void DrainTraceRecords(bool final_drain,
                       bool write_summary = true) noexcept
{
    if (g_trace_file == INVALID_HANDLE_VALUE) return;
    if (dluma_atomic_compare_exchange(&g_consumer_lock, 1, 0) != 0) return;
    AssetTraceEvent events[kTraceDrainBatch];
    bool drained_any = false;
    for (;;) {
        const std::size_t count = trace::Drain(events, kTraceDrainBatch);
        if (!count) break;
        drained_any = true;
        std::size_t buffered = 0;
        for (std::size_t i = 0; i < count; ++i) {
            char line[kTraceLineCapacity];
            std::size_t line_size = 0;
            trace::ConsumeSummaryEvent(&g_summary, events[i]);
            if (events[i].type ==
                AssetTraceEventType::ChangeAfterFadeAttestation) {
                const char* const severity =
                    events[i].text3[0] &&
                    AsciiEquals(events[i].text3, "Succeeded")
                        ? "INFO"
                        : "WARN";
                dluma_log_pair(
                    severity, "presenter_root_raw",
                    events[i].text0);
                dluma_log_pair(
                    severity, "presenter_root_canonical",
                    events[i].text1);
                dluma_log_pair(
                    severity, "epoch_root_canonical",
                    events[i].text2);
                dluma_log_u64(
                    severity, "root_equal",
                    events[i].third ? 1U : 0U);
                dluma_log_pair(
                    severity, "source_set_snapshot_result",
                    events[i].text3);
                dluma_log_u64(
                    severity, "active_source_count",
                    events[i].detail3);
                dluma_log_u64(
                    severity, "project_root_count",
                    events[i].detail0);
                dluma_log_u64(
                    severity, "data_directory_count",
                    events[i].detail1);
                dluma_log_u64(
                    severity, "assets_pc_count",
                    events[i].detail2);
                dluma_log_u64(
                    severity, "ownership_complete",
                    events[i].first ? 1U : 0U);
                dluma_log_u64(
                    severity, "exact_handles_complete",
                    events[i].second ? 1U : 0U);
            }
            if (events[i].sequence >
                g_trace_records_drained_through_sequence)
                g_trace_records_drained_through_sequence =
                    events[i].sequence;
            if (!trace::FormatEventLine(events[i], line, sizeof(line),
                                        &line_size)) {
                g_summary.trace_output_incomplete = true;
                continue;
            }
            if (buffered + line_size > sizeof(g_trace_write_buffer)) {
                DWORD file_written = 0;
                if (!WriteFile(g_trace_file, g_trace_write_buffer,
                               static_cast<DWORD>(buffered), &file_written,
                               nullptr) || file_written != buffered)
                    g_summary.trace_output_incomplete = true;
                buffered = 0;
            }
            if (line_size <= sizeof(g_trace_write_buffer) - buffered) {
                std::memcpy(g_trace_write_buffer + buffered, line, line_size);
                buffered += line_size;
            }
        }
        if (buffered) {
            DWORD file_written = 0;
            if (!WriteFile(g_trace_file, g_trace_write_buffer,
                           static_cast<DWORD>(buffered), &file_written,
                           nullptr) || file_written != buffered)
                g_summary.trace_output_incomplete = true;
        }
        if (count < kTraceDrainBatch) break;
    }
    if (!drained_any && !final_drain) {
        dluma_atomic_exchange(&g_consumer_lock, 0);
        return;
    }
    if (final_drain && !FlushFileBuffers(g_trace_file))
        g_summary.trace_output_incomplete = true;
    if (write_summary && !WriteSummaryFile()) {
        g_summary.trace_output_incomplete = true;
        if (!WriteSummaryFile() && !g_trace_output_warning_logged) {
            dluma_log_pair(
                "WARN", "asset_scope_trace_output",
                "trace or summary output incomplete; absence and ordering conclusions are unknown");
            g_trace_output_warning_logged = true;
        }
    } else if (write_summary && g_summary.trace_output_incomplete &&
               !g_trace_output_warning_logged) {
        dluma_log_pair(
            "WARN", "asset_scope_trace_output",
            "trace output incomplete; absence and ordering conclusions are unknown");
        g_trace_output_warning_logged = true;
    }
    dluma_atomic_exchange(&g_consumer_lock, 0);
}

struct ReportBuilder {
    char* data;
    std::size_t capacity;
    std::size_t size;
};

void ReportAppend(ReportBuilder* builder, const char* text) noexcept
{
    if (!builder || !builder->data || !builder->capacity || !text) return;
    while (*text && builder->size + 1 < builder->capacity)
        builder->data[builder->size++] = *text++;
    builder->data[builder->size] = 0;
}

void ReportAppendU64(ReportBuilder* builder, std::uint64_t value) noexcept
{
    char number[32];
    dluma_u64_to_text(value, number, DLUMA_ARRAY_COUNT(number));
    ReportAppend(builder, number);
}

void ReportAppendI32(ReportBuilder* builder, std::int32_t value) noexcept
{
    if (value < 0) {
        ReportAppend(builder, "-");
        const std::uint32_t magnitude =
            static_cast<std::uint32_t>(
                -static_cast<std::int64_t>(value));
        ReportAppendU64(builder, magnitude);
        return;
    }
    ReportAppendU64(
        builder, static_cast<std::uint32_t>(value));
}

void ReportAppendHex(ReportBuilder* builder, std::uint32_t value) noexcept
{
    char number[32];
    dluma_u32_hex(value, number, DLUMA_ARRAY_COUNT(number));
    ReportAppend(builder, number);
}

void ReportAppendPointer(ReportBuilder* builder,
                         std::uintptr_t value) noexcept
{
    static const char digits[] = "0123456789abcdef";
    char reversed[2U * sizeof(std::uintptr_t)];
    char text[3U + 2U * sizeof(std::uintptr_t)] = {'0', 'x', 0};
    std::size_t count = 0;
    do {
        reversed[count++] = digits[value & 0xFU];
        value >>= 4U;
    } while (value && count < sizeof(reversed));
    std::size_t cursor = 2;
    while (count && cursor + 1 < sizeof(text))
        text[cursor++] = reversed[--count];
    text[cursor] = 0;
    ReportAppend(builder, text);
}

void ReportAppendQuoted(ReportBuilder* builder, const char* text) noexcept
{
    ReportAppend(builder, "\"");
    if (text) {
        while (*text && builder->size + 3 < builder->capacity) {
            const char value = *text++;
            switch (value) {
            case '\\': ReportAppend(builder, "\\\\"); break;
            case '\"': ReportAppend(builder, "\\\""); break;
            case '\t': ReportAppend(builder, "\\t"); break;
            case '\r': ReportAppend(builder, "\\r"); break;
            case '\n': ReportAppend(builder, "\\n"); break;
            default:
                builder->data[builder->size++] = value;
                builder->data[builder->size] = 0;
                break;
            }
        }
    }
    ReportAppend(builder, "\"");
}

__declspec(noinline) void ReportAppendNativeXuiManagers(ReportBuilder* builder) noexcept
{
    xui::ManagerRecord records[xui::kMaximumManagers] = {};
    std::size_t count = 0;
    std::uint64_t revision = 0;
    const bool complete = g_xui_manager_observation_ready &&
        xui::CopyManagerInventory(&g_xui_manager_ledger, records,
            xui::kMaximumManagers, &count, &revision);
    ReportAppend(builder, "\r\n\r\n[native_xui_managers]\r\nstartup_observation_ready=");
    ReportAppendU64(builder, g_xui_manager_observation_ready ? 1 : 0);
    ReportAppend(builder, " lifetime_observation_lost=");
    ReportAppendU64(builder, g_xui_manager_ledger.lost.load() ? 1 : 0);
    ReportAppend(builder, " inventory=");
    ReportAppendQuoted(builder, complete ? "complete" : "unavailable");
    ReportAppend(builder, " compiled_entry_restoration=\"unresolved\"\r\n");
    if (!complete) return;
    ReportAppend(builder, "revision="); ReportAppendU64(builder, revision);
    ReportAppend(builder, " live_count="); ReportAppendU64(builder, count);
    ReportAppend(builder, "\r\n");
    for (std::size_t i = 0; i < count; ++i) {
        ReportAppend(builder, "manager="); ReportAppendPointer(builder, records[i].manager);
        ReportAppend(builder, " generation="); ReportAppendU64(builder, records[i].generation);
        ReportAppend(builder, " level="); ReportAppendPointer(builder, records[i].level);
        ReportAppend(builder, " birth_epoch="); ReportAppendU64(builder, records[i].birth_epoch);
        ReportAppend(builder, "\r\n");
    }
}

void ReportAppendPlayerAbsentPass(
    ReportBuilder* builder, const char* prefix,
    const playerabsent::PlayerAbsentSnapshot& snapshot) noexcept
{
    ReportAppend(builder, "\r\n");
    ReportAppend(builder, prefix);
    ReportAppend(builder, "_owner_count=");
    ReportAppendU64(builder, snapshot.owner_count);
    ReportAppend(builder, " inventory_revision=");
    ReportAppendU64(builder, snapshot.inventory_revision);
    ReportAppend(builder, " cache_fingerprint=");
    ReportAppendU64(builder, snapshot.gameplay_cache_fingerprint);
    ReportAppend(builder, " local_process_global=");
    ReportAppendPointer(builder, snapshot.local_process_global_state);
    ReportAppend(builder, " character_manager_global=");
    ReportAppendPointer(
        builder, snapshot.character_manager_global_state);
    ReportAppend(builder, " complete=");
    ReportAppendU64(builder, snapshot.complete ? 1U : 0U);
}

