static std::uint64_t dluma_startup_b0_counter_delta(
    volatile LONG* current, volatile LONG* baseline) noexcept
{
    const std::uint32_t current_value =
        static_cast<std::uint32_t>(
            dluma_atomic_compare_exchange(current, 0, 0));
    const std::uint32_t baseline_value =
        static_cast<std::uint32_t>(
            dluma_atomic_compare_exchange(baseline, 0, 0));
    return current_value >= baseline_value
        ? static_cast<std::uint64_t>(current_value - baseline_value)
        : 0;
}

static void dluma_evaluate_startup_b0_worker_onframe_invariant(void) noexcept
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    if (dluma_atomic_compare_exchange(
            &g_startup_b0_worker_onframe_invariant_failure, 0, 0) != 0 ||
        dluma_atomic_compare_exchange(
            &g_startup_b0_worker_frontend_seen, 0, 0) == 0)
        return;

    DlumaGameThreadLevelSnapshot snapshot = {};
    const ULONGLONG now_ms = GetTickCount64();
    const bool snapshot_read =
        dluma_read_game_thread_level_snapshot(&snapshot) != 0;
    cold::StartupB0WorkerOnFrameInvariantEvidence evidence = {};
    evidence.frames_since_worker_frontend =
        dluma_startup_b0_counter_delta(
            &g_dluma.engine.game_frame_hook_call_count,
            &g_startup_b0_worker_frontend_frame_count);
    evidence.pump_calls_since_worker_frontend =
        dluma_startup_b0_counter_delta(
            &g_dluma.engine.startup_b0_onframe_pump_call_count,
            &g_startup_b0_worker_frontend_pump_count);
    evidence.query_calls_since_worker_frontend =
        dluma_startup_b0_counter_delta(
            &g_dluma.engine.startup_b0_active_level_query_call_count,
            &g_startup_b0_worker_frontend_query_count);
    evidence.query_successes_since_worker_frontend =
        dluma_startup_b0_counter_delta(
            &g_dluma.engine.startup_b0_active_level_query_success_count,
            &g_startup_b0_worker_frontend_query_success_count);
    evidence.query_nulls_since_worker_frontend =
        dluma_startup_b0_counter_delta(
            &g_dluma.engine.startup_b0_active_level_query_null_count,
            &g_startup_b0_worker_frontend_query_null_count);
    evidence.query_invalids_since_worker_frontend =
        dluma_startup_b0_counter_delta(
            &g_dluma.engine.startup_b0_active_level_query_invalid_count,
            &g_startup_b0_worker_frontend_query_invalid_count);
    evidence.worker_frontend_seen = true;
    evidence.on_frame_frontend_seen =
        dluma_atomic_compare_exchange(
            &g_startup_b0_on_frame_frontend_seen, 0, 0) != 0;
    evidence.level_snapshot_stale =
        !snapshot_read || !snapshot.sample_ms ||
        snapshot.sample_ms > now_ms ||
        now_ms - snapshot.sample_ms > 3000U;
    evidence.thread_ownership_validation_failed =
        dluma_atomic_compare_exchange(
            &g_dluma.engine.startup_b0_onframe_last_skip_reason,
            0, 0) ==
        DLUMA_STARTUP_B0_ONFRAME_SKIP_THREAD_OWNERSHIP_VALIDATION_FAILED;
    const cold::StartupB0WorkerOnFrameInvariantFailure failure =
        cold::ClassifyStartupB0WorkerOnFrameInvariant(&evidence);
    if (failure ==
        cold::StartupB0WorkerOnFrameInvariantFailure::None)
        return;
    if (dluma_atomic_compare_exchange(
            &g_startup_b0_worker_onframe_invariant_failure,
            static_cast<LONG>(failure), 0) == 0)
    {
        dluma_log_pair(
            "ERROR", "startup_b0_worker_onframe_invariant",
            cold::StartupB0WorkerOnFrameInvariantFailureName(failure));
        MarkContentDirty();
    }
}

extern "C" int dluma_custom_map_cancelled_presentation_cleanup(
    const DlumaProjectCancelledCleanupPlan* plan,
    DlumaProjectCancelledCleanupResult* result)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    if (result) std::memset(result, 0, sizeof(*result));
    if (!plan || !result) return 0;
    bool cleanup_verification_published = false;
    auto fail = [&](const char* reason) noexcept {
        if (!result->first_failure[0])
            CopyLoaderText(
                result->first_failure,
                sizeof(result->first_failure),
                reason ? reason : "cancelled_cleanup_failed");
    };
    if (plan->first_failure[0]) {
        fail(plan->first_failure);
        goto failed;
    }
    if (!g_initialized || !ContentTrackingLive() || !g_fix_enabled ||
        g_dluma.stop_requested) {
        fail("cancelled_cleanup_isolation_unavailable");
        goto failed;
    }
    if (!plan->prior_token_generation || !plan->prior_epoch ||
        !plan->owner_thread_id ||
        plan->owner_thread_id != GetCurrentThreadId() ||
        !dluma_project_root_is_canonical(
            plan->prior_normalized_project_root)) {
        fail("cancelled_cleanup_plan_invalid_or_wrong_thread");
        goto failed;
    }
    PublishSimple(
        AssetTraceEventType::CancelledPresentationDetected,
        0, 0, 0, plan->prior_epoch,
        plan->prior_token_generation,
        plan->prior_normalized_project_root,
        "pending-confirmation-cancelled");
    PublishSimple(
        AssetTraceEventType::CancelledCleanupBegin,
        0, 0, 0, plan->prior_epoch,
        plan->prior_token_generation,
        plan->prior_normalized_project_root,
        "exact-reverse-source-cleanup");
    if (g_change_depth || g_after_fade_depth || g_load_level_depth ||
        g_update_dlc_depth || g_pending_source_add.depth ||
        dluma_atomic_compare_exchange(
            &g_source_registry_active_calls, 0, 0) != 0) {
        fail("cancelled_cleanup_lifecycle_or_registry_busy");
        goto failed;
    }
    {
        FrontendResetGate reset_gate;
        if (!reset_gate.locked()) {
            fail("cancelled_cleanup_reset_gate_busy");
            goto failed;
        }
        content::CustomContentEpoch epoch = {};
        if (!content::SnapshotEpoch(
                &g_content_ledger, plan->prior_epoch, &epoch) ||
            !epoch.active || !epoch.accepting_records ||
            epoch.consumed || epoch.sources_removed ||
            !epoch.ownership_complete ||
            epoch.ownership_mutation_lost ||
            epoch.project_root_conflict ||
            !content::PathsEqual(
                epoch.normalized_project_root,
                plan->prior_normalized_project_root)) {
            fail("cancelled_cleanup_epoch_ownership_incomplete");
            goto failed;
        }
        content::SourceResetSnapshot
            sources[content::kMaximumSources] = {};
        FsSourceDeletingDestructorFn
            destructors[content::kMaximumSources] = {};
        const content::SourceSnapshotResult snapshot =
            content::SnapshotActiveSourcesForEpochComplete(
                &g_content_ledger, plan->prior_epoch, sources,
                content::kMaximumSources,
                content::NextSequence(&g_content_ledger));
        result->active_source_count_before =
            snapshot.expected_active_count;
        if (!snapshot.complete ||
            snapshot.count != snapshot.expected_active_count) {
            fail("cancelled_cleanup_source_snapshot_incomplete");
            goto failed;
        }
        for (std::size_t index = 0;
             index < snapshot.count; ++index) {
            const content::SourceResetSnapshot& source = sources[index];
            if (!source.source || !source.exact_handle_available ||
                !source.path_created_ownership ||
                source.epoch != plan->prior_epoch ||
                !content::PathWithinRoot(
                    source.normalized_path,
                    plan->prior_normalized_project_root)) {
                fail("cancelled_cleanup_source_identity_incomplete");
                goto failed;
            }
            destructors[index] =
                ResolveSourceDeletingDestructor(source.source);
            if (!destructors[index]) {
                fail("cancelled_cleanup_source_destructor_unvalidated");
                goto failed;
            }
        }

        vfs::FilesystemSourceInventory before = {};
        vfs::FilesystemSourceInventory after = {};
        if (!CaptureCurrentFilesystemInventory(&before)) {
            fail("cancelled_cleanup_live_registry_before_unavailable");
            goto failed;
        }
        for (std::size_t index = 0;
             index < snapshot.count; ++index) {
            std::uint32_t matches = 0;
            for (std::uint32_t live_index = 0;
                 live_index < before.source_count; ++live_index)
                if (before.sources[live_index].source ==
                    reinterpret_cast<std::uintptr_t>(
                        sources[index].source))
                    ++matches;
            if (matches != 1U) {
                fail("cancelled_cleanup_source_not_unique_in_live_registry");
                goto failed;
            }
        }

        for (std::size_t index = 0;
             index < snapshot.count; ++index) {
            const bool removed = RemoveAndDestroyPathCreatedSource(
                sources[index].source, destructors[index]);
            PublishSimple(
                AssetTraceEventType::CancelledCleanupSourceRemoval,
                reinterpret_cast<std::uintptr_t>(
                    sources[index].source),
                sources[index].successful_add_ordinal,
                sources[index].record_index,
                plan->prior_epoch, removed ? 1U : 0U,
                content::SourceKindName(sources[index].kind),
                sources[index].normalized_path);
            if (!content::MarkSourceResetResult(
                    &g_content_ledger, sources[index].record_index,
                    removed, content::NextSequence(&g_content_ledger), &sources[index])) {
                fail("cancelled_cleanup_ledger_remove_result_failed");
                goto failed;
            }
            if (!removed) {
                fail("cancelled_cleanup_exact_source_remove_failed");
                goto failed;
            }
            ++result->removed_source_count;
            if (sources[index].kind ==
                content::CustomSourceKind::AssetsPc)
                (void)persistent::MarkStagedAssetsSourceRemoved(
                    &g_persistent_consumer_ledger,
                    reinterpret_cast<std::uintptr_t>(
                        sources[index].source),
                    plan->prior_epoch,
                    content::NextSequence(&g_content_ledger));
        }
        if (!CaptureCurrentFilesystemInventory(&after)) {
            fail("cancelled_cleanup_live_registry_after_unavailable");
            goto failed;
        }
        result->active_source_count_after =
            content::CountActiveCustomSourcesForEpoch(
                &g_content_ledger, plan->prior_epoch);
        result->live_registry_verified_absent =
            cancelled_cleanup::
                VerifyFilesystemInventoryExactMinusSources(
                    &before, &after, sources, snapshot.count)
                ? 1U
                : 0U;
        result->loader_sources_unchanged =
            result->live_registry_verified_absent;
        result->replacement_source_absent =
            result->live_registry_verified_absent;
        PublishSimple(
            AssetTraceEventType::CancelledCleanupVerification,
            0, 0, 0, plan->prior_epoch,
            (static_cast<std::uint64_t>(
                 result->active_source_count_before) << 32U) |
                static_cast<std::uint64_t>(
                    result->active_source_count_after),
            result->live_registry_verified_absent
                ? "live-registry-exact-minus-source-set"
                : "live-registry-verification-failed",
            result->loader_sources_unchanged &&
                    result->replacement_source_absent
                ? "loader-unchanged-no-replacement"
                : "loader-or-replacement-mismatch");
        cleanup_verification_published = true;
        if (!result->live_registry_verified_absent ||
            result->active_source_count_after != 0U) {
            fail("cancelled_cleanup_live_registry_verification_failed");
            goto failed;
        }
        result->prior_epoch_consumed =
            content::CloseCancelledEpochConsumed(
                &g_content_ledger, plan->prior_epoch,
                content::NextSequence(&g_content_ledger))
                ? 1U
                : 0U;
        if (!result->prior_epoch_consumed) {
            fail("cancelled_cleanup_epoch_consume_failed");
            goto failed;
        }
        PublishSimple(
            AssetTraceEventType::CancelledEpochConsumed,
            0, 0, 0, plan->prior_epoch,
            plan->prior_token_generation,
            plan->prior_normalized_project_root,
            "closed-consumed-zero-active-sources");
        result->succeeded = 1U;
        MarkContentDirty();
        return 1;
    }

failed:
    if (!cleanup_verification_published)
        PublishSimple(
            AssetTraceEventType::CancelledCleanupVerification,
            0, 0, 0, plan ? plan->prior_epoch : 0U, 0,
            result && result->first_failure[0]
                ? result->first_failure
                : "cleanup-failed-before-verification",
            "restart-required");
    cold::LatchRestartRequired(
        &g_cold_reboot,
        cold::BarrierRejectReason::
            CancelledPresentationCleanupFailed,
        plan ? plan->prior_epoch : 0U);
    dluma_project_launch_block(
        result && result->first_failure[0]
            ? result->first_failure
            : "cancelled_presentation_cleanup_failed");
    g_component_status.sources =
        ComponentRuntimeState::RuntimeFailed;
    g_component_status.frontend_cold_reboot =
        ComponentRuntimeState::RuntimeFailed;
    SetAggregateState(dluma::fixes::FixState::RuntimeFailed);
    MarkContentDirty();
    return 0;
}

extern "C" void dluma_custom_map_asset_trace_game_thread_drain(void)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    if (dluma_atomic_compare_exchange(&g_trace_live, 0, 0) != 0)
        DrainTraceRecords(false);
    if (ContentTrackingLive())
        DrainColdRebootCriticalDiagnostics(false);
    if (ContentTrackingLive())
        dluma_evaluate_startup_b0_worker_onframe_invariant();
    if (ContentTrackingLive() &&
        dluma_atomic_compare_exchange(
            &g_bf8_touch_reconciliation_failed, 0, 0) != 0 &&
        dluma_atomic_compare_exchange(
            &g_bf8_touch_reconciliation_log_reported, 1, 0) == 0) {
        dluma_log_pair(
            "ERROR", "candidate_registry_touch_invariant",
            "registry_touched_mask_mismatch");
        dluma_log_u64(
            "ERROR", "sealed_candidate_promote_mask",
            g_bf8_sealed_candidate_promote_mask);
        dluma_log_u64(
            "ERROR", "independent_authoritative_touch_mask",
            g_bf8_independent_authoritative_touch_mask);
        dluma_log_u64(
            "ERROR", "expected_registry_touched_mask",
            g_bf8_expected_registry_touched_mask);
        dluma_log_u64(
            "ERROR", "observed_registry_touched_mask",
            g_bf8_observed_registry_touched_mask);
    }
    if (ContentTrackingLive()) {
        StartupB0WriterGuard startup_reader;
        cold::StartupB0Diagnostics startup = {};
        if (startup_reader.locked() &&
            cold::SnapshotStartupB0Diagnostics(
                &g_startup_b0_session, &startup)) {
            const std::uint64_t source_diagnostic_key =
                g_startup_source_classification_log_key;
            if (source_diagnostic_key &&
                source_diagnostic_key !=
                    g_startup_source_classification_reported_log_key) {
                if (source_diagnostic_key ==
                        kStartupRegistryChangedDiagnosticKey) {
                    dluma_log_pair(
                        "WARN", "startup_b0_source_inventory_rejected",
                        "registry_changed_after_complete_inventory");
                    dluma_log_u64(
                        "WARN",
                        "startup_b0_source_registry_generation_expected",
                        g_startup_source_registry_generation_expected);
                    dluma_log_u64(
                        "WARN",
                        "startup_b0_source_registry_generation_observed",
                        g_startup_source_registry_generation_observed);
                } else {
                    dluma_log_pair(
                        "WARN",
                        "startup_b0_source_classification_rejected",
                        startupsource::
                            StartupSourceClassificationResultName(
                                g_startup_source_classification_log_result));
                    dluma_log_u64(
                        "WARN",
                        "startup_b0_source_rejected_list_ordinal",
                        g_startup_source_classification_log_ordinal);
                    dluma_log_pair(
                        "WARN", "startup_b0_source_rejected_path",
                        g_startup_source_classification_log_path[0]
                            ? g_startup_source_classification_log_path
                            : "<unavailable>");
                    dluma_log_u64(
                        "WARN",
                        "startup_b0_source_rejected_raw_length",
                        g_startup_source_classification_log_raw_length);
                    dluma_log_pair(
                        "WARN",
                        "startup_b0_source_rejected_raw_hex",
                        g_startup_source_classification_log_raw_hex[0]
                            ? g_startup_source_classification_log_raw_hex
                            : "<unavailable>");
                    if (g_startup_source_classification.
                            first_owner_validation_failure_available) {
                        const DlumaNativeCompanionOwnerValidationDiagnostic&
                            owner_failure =
                                g_startup_source_classification.
                                    first_owner_validation_failure;
                        dluma_log_pair(
                            "WARN",
                            "startup_b0_source_owner_validation_result",
                            dluma_native_companion_owner_validation_result_name(
                                owner_failure.result));
                        dluma_log_u64(
                            "WARN",
                            "startup_owner_current_native_registry_revision",
                            owner_failure.
                                current_native_registry_revision);
                        dluma_log_u64(
                            "WARN",
                            "startup_owner_enabled_requested_now",
                            owner_failure.enabled_requested_now);
                        LogNativeAdmissionIdentity(
                            "WARN", false,
                            owner_failure.registered);
                        LogNativeAdmissionIdentity(
                            "WARN", true,
                            owner_failure.observed);
                    }
                }
                g_startup_source_classification_reported_log_key =
                    source_diagnostic_key;
            }
            const bool state_changed =
                startup.startup_b0_state_revision !=
                    g_startup_b0_reported_state_revision;
            if (state_changed) {
                dluma_log_pair(
                    "INFO", "startup_b0_state",
                    cold::StartupB0StateName(startup.startup_b0_state));
                g_startup_b0_reported_state_revision =
                    startup.startup_b0_state_revision;
            }
            const ULONGLONG now_ms = GetTickCount64();
            const bool terminal =
                startup.startup_b0_window_closed ||
                startup.startup_b0_state ==
                    cold::StartupB0State::CompleteAuthorized ||
                startup.startup_b0_state ==
                    cold::StartupB0State::PermanentFailure;
            const bool invariant_report_pending =
                dluma_atomic_compare_exchange(
                    &g_startup_b0_worker_onframe_invariant_failure,
                    0, 0) != 0 &&
                dluma_atomic_compare_exchange(
                    &g_startup_b0_worker_onframe_invariant_reported,
                    0, 0) == 0;
            const bool report_due =
                (startup.startup_b0_diagnostic_revision !=
                     g_startup_b0_reported_diagnostic_revision &&
                 (state_changed || terminal ||
                  !g_startup_b0_last_report_ms ||
                  now_ms - g_startup_b0_last_report_ms >= 1000U)) ||
                invariant_report_pending;
            if (report_due) {
                if (WriteFrontendStartupBaselineReport()) {
                    g_startup_b0_reported_diagnostic_revision =
                        startup.startup_b0_diagnostic_revision;
                    g_startup_b0_last_report_ms = now_ms;
                    if (invariant_report_pending)
                        dluma_atomic_exchange(
                            &g_startup_b0_worker_onframe_invariant_reported,
                            1);
                } else {
                    dluma_log_pair(
                        "WARN", "frontend_startup_baseline",
                        "startup B0 diagnostics report write failed");
                }
            }
        }
    }
    if (ContentTrackingLive() &&
        dluma_atomic_compare_exchange(&g_content_consumer_lock, 1, 0) == 0) {
        DrainContentDiagnostics();
        if (dluma_atomic_exchange(&g_content_dirty, 0) != 0 &&
            !WriteContentLedgerReport())
            dluma_log_pair("WARN", "custom_content_ledger_report",
                         "report write failed; runtime rollback remains fail-open");
        dluma_atomic_exchange(&g_content_consumer_lock, 0);
    }
}

void ReportContentFinalizationAuthority(
    const DlumaContentFinalizationAuthorityEvidence& evidence) noexcept
{
    dluma_log_pair(
        "INFO", "content_finalization_authority_proof",
        dluma_content_finalization_authority_proof_name(
            evidence.selected_proof));
    dluma_log_u64(
        "INFO", "content_finalization_current_thread",
        static_cast<ULONGLONG>(
            static_cast<unsigned long>(
                evidence.current_thread_id)));
    dluma_log_u64(
        "INFO", "content_finalization_serialized_active_thread",
        static_cast<ULONGLONG>(
            static_cast<unsigned long>(
                evidence.serialized_route_active_thread_id)));
    dluma_log_u64(
        "INFO", "content_finalization_serialized_dispatch_thread",
        static_cast<ULONGLONG>(
            static_cast<unsigned long>(
                evidence.serialized_route_dispatch_thread_id)));
    dluma_log_u64(
        "INFO", "content_finalization_serialized_token",
        evidence.serialized_route_token);
    dluma_log_u64(
        "INFO", "content_finalization_inside_serialized_route",
        evidence.inside_serialized_route);
    dluma_log_u64(
        "INFO", "content_finalization_serialized_frontend_latched",
        evidence.serialized_frontend_latched);
    dluma_log_u64(
        "INFO", "content_finalization_serialized_playtest_handoff_latched",
        evidence.serialized_playtest_handoff_latched);
    dluma_log_u64(
        "INFO", "content_finalization_serialized_authority_frozen",
        evidence.serialized_authority_frozen);
    dluma_log_u64(
        "INFO", "content_finalization_serialized_authority_conflict",
        evidence.serialized_authority_conflict);
    dluma_log_u64(
        "INFO", "content_finalization_window_expected_thread",
        static_cast<ULONGLONG>(
            static_cast<unsigned long>(
                evidence.validated_window_owner_thread_id)));
    dluma_log_u64(
        "INFO", "content_finalization_window_observed_thread",
        static_cast<ULONGLONG>(
            static_cast<unsigned long>(
                evidence.observed_window_owner_thread_id)));
    dluma_log_u64(
        "INFO", "content_finalization_window_owner_conflict",
        evidence.window_owner_conflict);
    dluma_log_u64(
        "INFO", "content_finalization_natural_expected_calls",
        evidence.natural_shutdown.expected_exit_owner_calls);
    dluma_log_u64(
        "INFO", "content_finalization_natural_observed_calls",
        evidence.natural_shutdown.observed_exit_owner_calls);
    dluma_log_u64(
        "INFO", "content_finalization_natural_expected_thread",
        static_cast<ULONGLONG>(
            static_cast<unsigned long>(
                evidence.natural_shutdown.expected_thread_id)));
    dluma_log_u64(
        "INFO", "content_finalization_natural_observed_thread",
        static_cast<ULONGLONG>(
            static_cast<unsigned long>(
                evidence.natural_shutdown.observed_thread_id)));
    dluma_log_u64(
        "INFO", "content_finalization_natural_expected_token",
        evidence.natural_shutdown.expected_token);
    dluma_log_u64(
        "INFO", "content_finalization_natural_observed_token",
        evidence.natural_shutdown.observed_token);
    dluma_log_u64(
        "INFO", "content_finalization_natural_owner_conflict",
        evidence.natural_shutdown.owner_conflict);
    dluma_log_u64(
        "INFO", "content_finalization_natural_hook_owned",
        evidence.natural_shutdown.hook_owned);
    dluma_log_u64(
        "INFO", "content_finalization_natural_exact",
        evidence.natural_shutdown.exact);
}

const char* ContentFinalizationAuthorityFailure(
    const DlumaContentFinalizationAuthorityEvidence& evidence,
    bool natural_owner_requested) noexcept
{
    const DlumaNaturalShutdownOwnerProof& natural =
        evidence.natural_shutdown;
    if (natural_owner_requested) {
        if (natural.expected_exit_owner_calls != 1U ||
            natural.observed_exit_owner_calls != 1U)
            return "natural_shutdown_owner_call_count_mismatch";
        if (natural.expected_thread_id !=
                natural.observed_thread_id ||
            natural.expected_thread_id !=
                evidence.current_thread_id)
            return "natural_shutdown_owner_thread_mismatch";
        if (!natural.expected_token ||
            natural.expected_token != natural.observed_token)
            return "natural_shutdown_owner_token_mismatch";
        if (natural.owner_conflict)
            return "natural_shutdown_owner_conflict";
        if (!natural.hook_owned)
            return "natural_shutdown_hook_ownership_lost";
    }
    if (evidence.validated_window_owner_thread_id &&
        (evidence.validated_window_owner_thread_id !=
             evidence.observed_window_owner_thread_id ||
         evidence.validated_window_owner_thread_id !=
             evidence.current_thread_id))
        return "validated_window_owner_expected_observed_mismatch";
    if (evidence.window_owner_conflict)
        return "validated_window_owner_conflict";
    if (evidence.inside_serialized_route)
        return "active_serialized_route_identity_mismatch";
    return "no_active_serialized_window_or_natural_owner";
}

static int FinalizeContentReportsOnGameThread(
    bool exit_game_owner,
    std::uint32_t observed_exit_owner_calls) noexcept
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    if (!g_initialized) return 1;

    const char* failure_reason = nullptr;
    bool finalized = false;
    bool diagnostic_reports_finalized = false;
    const LONG validated_window_owner =
        dluma_engine_game_frame_window_owner_thread_id(
            &g_dluma.engine);
    DlumaNaturalShutdownOwnerProof natural_owner = {};
    DlumaContentFinalizationAuthorityEvidence authority = {};
    if (exit_game_owner)
        (void)dluma_shutdown_snapshot_natural_exit_owner(
            observed_exit_owner_calls, &natural_owner);
    const bool authority_allowed =
        dluma_engine_current_thread_can_finalize_content_ex(
            &g_dluma.engine, validated_window_owner,
            exit_game_owner ? &natural_owner : nullptr,
            &authority) != 0;
    ReportContentFinalizationAuthority(authority);
    if (!authority_allowed) {
        failure_reason = ContentFinalizationAuthorityFailure(
            authority, exit_game_owner);
        goto failed;
    }

    dluma_atomic_exchange(&g_trace_stopping, 1);
    dluma_atomic_exchange(&g_trace_live, 0);
    dluma_atomic_exchange(&g_frontend_reset_stopping, 1);
    /* Orderly process exit is report-only. Never execute project cleanup from
     * this path, but stop every custom-content producer before the last fold. */
    dluma_atomic_exchange(&g_content_live, 0);

    if (dluma_atomic_compare_exchange(&g_trace_stopping, 0, 0) == 0 ||
        dluma_atomic_compare_exchange(&g_trace_live, 0, 0) != 0 ||
        dluma_atomic_compare_exchange(&g_frontend_reset_stopping, 0, 0) == 0 ||
        dluma_atomic_compare_exchange(&g_content_live, 0, 0) != 0) {
        failure_reason = "publication_close_failed";
        goto failed;
    }

    if (exit_game_owner) {
        if (!WaitForExitGameOwnerCalls(
                observed_exit_owner_calls, &failure_reason))
            goto failed;
    } else if (!WaitForActiveCalls() || !WaitForConsumerCalls()) {
        failure_reason = "other_active_calls_timeout";
        goto failed;
    }

    DrainContentDiagnostics();
    finalized = FinalizeCustomContentReports();
    diagnostic_reports_finalized =
        DrainColdRebootCriticalDiagnostics(true);
    if (!finalized || !diagnostic_reports_finalized ||
        !g_report_finalized ||
        g_trace_summary_sequence != g_ledger_snapshot_sequence) {
        failure_reason = "report_write_failed";
        goto failed;
    }
    return 1;

failed:
    dluma_log_pair(
        "WARN", "content_report_finalization_failed",
        failure_reason ? failure_reason : "report_write_failed");
    (void)PinLoaderIfNeeded(true);
    return 0;
}

extern "C" int
dluma_custom_map_asset_trace_game_thread_finalize(void)
{
    return FinalizeContentReportsOnGameThread(false, 0);
}

extern "C" int
dluma_custom_map_asset_trace_game_thread_finalize_from_exit_game_owner(
    unsigned int observed_exit_owner_calls)
{
    return FinalizeContentReportsOnGameThread(
        true, observed_exit_owner_calls);
}

extern "C" DlumaStartupB0PumpStatus
dluma_custom_map_startup_b0_pump_status(void)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    if (!g_dluma.config.custom_map_asset_isolation_enabled)
        return DLUMA_STARTUP_B0_PUMP_DISABLED;
    if (!ContentTrackingLive() || g_dluma.stop_requested)
        return DLUMA_STARTUP_B0_PUMP_UNAVAILABLE;
    StartupB0WriterGuard startup_reader;
    if (!startup_reader.locked())
        return DLUMA_STARTUP_B0_PUMP_STATE_BUSY;
    cold::StartupB0Diagnostics startup = {};
    if (!cold::SnapshotStartupB0Diagnostics(
            &g_startup_b0_session, &startup))
        return DLUMA_STARTUP_B0_PUMP_UNAVAILABLE;
    if (cold::StartupB0StateRequiresOnFramePump(
            startup.startup_b0_state))
        return DLUMA_STARTUP_B0_PUMP_REQUIRED;
    switch (startup.startup_b0_state) {
    case cold::StartupB0State::CompleteAuthorized:
        return DLUMA_STARTUP_B0_PUMP_COMPLETE_AUTHORIZED;
    case cold::StartupB0State::MissedBeforeFirstCustomEpoch:
        return DLUMA_STARTUP_B0_PUMP_MISSED_BEFORE_FIRST_CUSTOM_EPOCH;
    case cold::StartupB0State::PermanentFailure:
    default:
        return DLUMA_STARTUP_B0_PUMP_PERMANENT_FAILURE;
    }
}

extern "C" int
dluma_custom_map_startup_b0_frontend_identity_latched(void)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    if (!ContentTrackingLive() || g_dluma.stop_requested)
        return 0;
    StartupB0WriterGuard startup_reader;
    if (!startup_reader.locked())
        return 0;
    cold::StartupB0Diagnostics startup = {};
    return cold::SnapshotStartupB0Diagnostics(
               &g_startup_b0_session, &startup) &&
           startup.startup_b0_frontend_level_pointer != 0 &&
           startup.startup_b0_frontend_level_vtable != 0 &&
           startup.startup_b0_frame_route_token != 0;
}

extern "C" void
dluma_custom_map_startup_b0_note_authority_failure(
    unsigned int conflict_reason)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    if (!ContentTrackingLive() || g_dluma.stop_requested ||
        conflict_reason ==
            DLUMA_GAME_FRAME_AUTHORITY_CONFLICT_NONE)
        return;
    StartupB0WriterGuard startup_writer;
    if (!startup_writer.locked())
        return;
    if (cold::RecordStartupB0AuthorityLoss(
            &g_startup_b0_session)) {
        g_component_status.baseline =
            ComponentRuntimeState::RuntimeFailed;
        g_component_status.frontend_cold_reboot =
            ComponentRuntimeState::RuntimeFailed;
        MarkContentDirty();
    }
}

extern "C" int dluma_custom_map_project_admission_evidence(
    DlumaCustomProjectAdmissionEvidence* evidence_out)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    if (!evidence_out) return 0;
    std::memset(evidence_out, 0, sizeof(*evidence_out));
    evidence_out->admission =
        DLUMA_CUSTOM_PROJECT_ADMISSION_BLOCKED_RESTART_REQUIRED;
    CopyLoaderText(
        evidence_out->startup_b0_state,
        sizeof(evidence_out->startup_b0_state), "Unavailable");
    evidence_out->isolation_enabled =
        g_dluma.config.custom_map_asset_isolation_enabled ? 1U : 0U;
    if (dluma_frontend_error_blocks_project_launch()) {
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            "project_exit_cleanup_failed");
        return 1;
    }
    if (!g_dluma.config.custom_map_asset_isolation_enabled) {
        CopyLoaderText(
            evidence_out->startup_b0_state,
            sizeof(evidence_out->startup_b0_state),
            "IsolationDisabled");
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            "content_isolation_disabled");
        evidence_out->admission =
            DLUMA_CUSTOM_PROJECT_ADMISSION_ALLOWED;
        return 1;
    }
    const DlumaGameFrameAuthorityStatus authority_status =
        dluma_engine_game_frame_authority_status(
            &g_dluma.engine, GetTickCount64());
    if (authority_status !=
            DLUMA_GAME_FRAME_AUTHORITY_STATUS_AUTHORITATIVE) {
        const char* authority_reason =
            authority_status ==
                    DLUMA_GAME_FRAME_AUTHORITY_STATUS_PENDING
                ? "game_frame_authority_selection_pending"
                : authority_status ==
                          DLUMA_GAME_FRAME_AUTHORITY_STATUS_TIMEOUT
                    ? "game_frame_authority_selection_timeout_restart_required"
                    : authority_status ==
                              DLUMA_GAME_FRAME_AUTHORITY_STATUS_OWNERSHIP_LOST
                        ? "game_frame_authority_ownership_lost_restart_required"
                        : "game_frame_authority_conflict_restart_required";
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            authority_reason);
        evidence_out->admission =
            authority_status ==
                    DLUMA_GAME_FRAME_AUTHORITY_STATUS_PENDING
            ? DLUMA_CUSTOM_PROJECT_ADMISSION_DEFERRED
            : DLUMA_CUSTOM_PROJECT_ADMISSION_BLOCKED_RESTART_REQUIRED;
        return 1;
    }
    if (!ContentTrackingLive() || g_dluma.stop_requested) {
        CopyLoaderText(
            evidence_out->startup_b0_state,
            sizeof(evidence_out->startup_b0_state), "TrackingUnavailable");
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            "content_tracking_unavailable_restart_required");
        return 1;
    }
    StartupB0WriterGuard startup_reader;
    if (!startup_reader.locked()) {
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            "startup_b0_state_busy");
        evidence_out->admission =
            DLUMA_CUSTOM_PROJECT_ADMISSION_DEFERRED;
        return 1;
    }
    cold::StartupB0Diagnostics startup = {};
    if (!cold::SnapshotStartupB0Diagnostics(
            &g_startup_b0_session, &startup)) {
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            "startup_b0_unavailable_restart_required");
        return 1;
    }
    CopyLoaderText(
        evidence_out->startup_b0_state,
        sizeof(evidence_out->startup_b0_state),
        cold::StartupB0StateName(startup.startup_b0_state));
    evidence_out->startup_b0_complete_authorized =
        startup.startup_b0_state ==
                cold::StartupB0State::CompleteAuthorized &&
            startup.startup_b0_cold_reboot_baseline_authorized
        ? 1U : 0U;
    evidence_out->startup_b0_generation =
        g_startup_b0_session.session_generation;
    evidence_out->frame_route_token =
        startup.startup_b0_frame_route_token;
    evidence_out->restart_registry_can_admit =
        cold::CanAdmitCustomProject(&g_cold_reboot) ? 1U : 0U;
    evidence_out->startup_b0_permanent_source_failure =
        startup.startup_b0_permanent_failure &&
            startup.startup_b0_first_permanent_source_failure
        ? 1U : 0U;
    if (evidence_out->startup_b0_permanent_source_failure) {
        CopyLoaderText(
            evidence_out->startup_b0_source_failure_reason,
            sizeof(
                evidence_out->
                    startup_b0_source_failure_reason),
            dluma_native_companion_owner_validation_result_name(
                static_cast<
                    DlumaNativeCompanionOwnerValidationResult>(
                    startup.
                        startup_b0_first_permanent_source_failure)));
        const DlumaNativeCompanionOwnerValidationDiagnostic&
            owner_failure =
                g_startup_source_classification.
                    first_owner_validation_failure;
        CopyLoaderText(
            evidence_out->startup_b0_rejected_source,
            sizeof(
                evidence_out->startup_b0_rejected_source),
            owner_failure.registered.module_name[0]
                ? owner_failure.registered.module_name
                : owner_failure.registered.module_id[0]
                    ? owner_failure.registered.module_id
                    : "native mod");
    }
    const bool registry_allows =
        evidence_out->startup_b0_complete_authorized &&
        evidence_out->restart_registry_can_admit;
    const cold::StartupB0ProjectAdmissionDisposition disposition =
        cold::EvaluateStartupB0ProjectAdmission(
            startup.startup_b0_state, true, true, registry_allows);
    if (disposition ==
        cold::StartupB0ProjectAdmissionDisposition::Allow) {
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            "complete_authorized");
        evidence_out->admission =
            DLUMA_CUSTOM_PROJECT_ADMISSION_ALLOWED;
        return 1;
    }
    if (disposition ==
        cold::StartupB0ProjectAdmissionDisposition::Defer) {
        CopyLoaderText(
            evidence_out->reason, sizeof(evidence_out->reason),
            "b0_preparing");
        evidence_out->admission =
            DLUMA_CUSTOM_PROJECT_ADMISSION_DEFERRED;
        return 1;
    }
    const char* reason =
        evidence_out->startup_b0_permanent_source_failure
            ? "b0_permanent_source_failure"
            : g_player_audio_b0_retry_gate.attempts_stopped &&
                      g_player_audio_b0_permanent_failure_reason[0]
                ? g_player_audio_b0_permanent_failure_reason
                : "b0_restart_required";
    CopyLoaderText(
        evidence_out->reason, sizeof(evidence_out->reason), reason);
    return 1;
}

extern "C" DlumaCustomProjectAdmission
dluma_custom_map_project_admission(
    char* reason_out, unsigned int reason_capacity)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    DlumaCustomProjectAdmissionEvidence evidence = {};
    if (!dluma_custom_map_project_admission_evidence(&evidence)) {
        if (reason_out && reason_capacity)
            CopyLoaderText(
                reason_out, reason_capacity,
                "project_admission_evidence_unavailable");
        return DLUMA_CUSTOM_PROJECT_ADMISSION_BLOCKED_RESTART_REQUIRED;
    }
    if (reason_out && reason_capacity)
        CopyLoaderText(
            reason_out, reason_capacity, evidence.reason);
    return evidence.admission;
}

extern "C" void
dluma_custom_map_asset_isolation_note_premount_original(void)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    CapturePlayerPublicationCheckpoint(
        playerpublication::Checkpoint::
            BeforeProjectPremountOriginal,
        true);
    const std::uint64_t admission_sequence =
        content::NextSequence(&g_content_ledger);
    const std::uint32_t admission_epoch =
        content::CurrentEpochId(&g_content_ledger);
    if (dluma_atomic_compare_exchange(
            &g_player_publication_timeline_lock, 1, 0) != 0) {
        dluma_atomic_increment(
            &g_player_publication_timeline_critical_contention);
        return;
    }
    if (playerpublication::HasCheckpoint(
            g_player_publication_timeline,
            playerpublication::Checkpoint::StartupB0Commit))
        playerpublication::RecordProjectAdmissionBoundary(
            &g_player_publication_timeline,
            admission_sequence, admission_epoch);
    dluma_atomic_exchange(
        &g_player_publication_timeline_lock, 0);
    _InterlockedExchange64(
        &g_player_di_on_create_entry_sequence, 0);
    _InterlockedExchange64(
        &g_player_di_on_create_return_sequence, 0);
    dluma_atomic_pointer_exchange(
        &g_player_di_on_create_object, nullptr);
    dluma_atomic_pointer_exchange(
        &g_player_di_on_create_state, nullptr);
}

extern "C" int dluma_custom_map_content_frontend_restore_allowed(void)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    std::uint32_t epoch_id = 0;
    content::CustomContentEpoch epoch = {};
    if (!g_initialized || g_cold_reboot.restart_required ||
        g_cold_reboot.active_epoch_quarantined ||
        dluma_atomic_compare_exchange(&g_frontend_reset_active, 0, 0) != 0 ||
        !content::TryGetCurrentEpochId(&g_content_ledger, &epoch_id) ||
        content::CountActiveCustomSources(&g_content_ledger) != 0)
        return 0;
    if (!epoch_id)
        return 1;
    return content::SnapshotEpoch(&g_content_ledger, epoch_id, &epoch) &&
        !epoch.active && !epoch.frontend_reset_pending &&
        epoch.sources_removed && g_last_verified_reset_epoch == epoch_id;
}

extern "C" int dluma_custom_map_asset_mods_project_boundary(int after_mount)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    static thread_local bool incoming_project_sources_owned = false;
    if (!after_mount) {
        incoming_project_sources_owned = false;
        if (!dluma_asset_mod_runtime_pending() &&
            dluma_asset_mods_snapshot_sources(nullptr, 0, nullptr) == 0)
            return 1;
        if (!dluma_custom_map_content_frontend_restore_allowed()) {
            /* A map within the same project keeps its existing global
             * consumers. Preserve that revision until the project exits. */
            dluma_log_pair("INFO", "asset_mod_stack_change", "waiting_for_project_unload");
            return 1;
        }
        if (!dluma_asset_mod_runtime_apply(1)) return 0;
        incoming_project_sources_owned = true;
        return 1;
    }
    const bool owned = incoming_project_sources_owned;
    incoming_project_sources_owned = false;
    return !owned || AssetModBindSourceInventory();
}

extern "C" void dluma_custom_map_content_game_thread_tick(
    const char* map_name, void* level, ULONG_PTR level_vtable,
    ULONGLONG now_ms,
    unsigned int tick_source, int query_succeeded)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    (void)now_ms;
    const std::uint64_t player_audio_capture_now_ms =
        static_cast<std::uint64_t>(GetTickCount64());
    if (!ContentTrackingLive() || g_dluma.stop_requested) return;
    StartupB0WriterGuard startup_writer;
    if (!startup_writer.locked()) return;

    const LONG current_thread_id = static_cast<LONG>(GetCurrentThreadId());
    const cold::StartupB0TickSource source =
        tick_source == DLUMA_CUSTOM_MAP_TICK_SOURCE_ON_FRAME
            ? cold::StartupB0TickSource::OnFrame
            : tick_source == DLUMA_CUSTOM_MAP_TICK_SOURCE_FALLBACK_TIMER
                ? cold::StartupB0TickSource::FallbackTimer
                : cold::StartupB0TickSource::Unknown;
    const std::uint64_t frame_route_token =
        dluma_engine_game_frame_route_token(&g_dluma.engine);
    const bool exact_frame_route =
        source == cold::StartupB0TickSource::OnFrame &&
        frame_route_token != 0 &&
        dluma_engine_game_frame_dispatch_active_on_current_thread(
            &g_dluma.engine);
    if (exact_frame_route)
        dluma_atomic_exchange(
            &g_cold_reboot_game_thread_id, current_thread_id);

    /* The startup window controls capture, not completion of hashes over
     * its already-frozen, read-share-only native file pins. Large banks can
     * finish on later authoritative frames without adopting later content. */
    if (exact_frame_route && g_audio_baseline_content.frozen_revision &&
        !g_audio_baseline_content.inventory_joined &&
        dluma_atomic_compare_exchange(&g_audio_baseline_content.phase, 0, 0) !=
            static_cast<LONG>(audio_baseline_content::Phase::Failed))
        (void)AdvanceFrozenAudioBaselineContent(g_audio_baseline_content.baseline_generation);

    std::uint32_t current_epoch = 0;
    const bool epoch_query_succeeded = content::TryGetCurrentEpochId(
        &g_content_ledger, &current_epoch);
    const std::uint32_t counted_sources =
        content::CountActiveCustomSources(&g_content_ledger);
    const bool source_query_succeeded = counted_sources != UINT32_MAX;
    const std::uint32_t active_custom_source_count =
        source_query_succeeded ? counted_sources : 0;

    std::uint32_t local_project_lua_count = 0;
    std::uint64_t global_lua_hash = 0;
    std::uint32_t global_lua_count = 0;
    dluma_lua_registry_lock();
    global_lua_hash = g_dluma.lua_discovery.global_registry_hash;
    global_lua_count = g_dluma.lua_discovery.global_count;
    local_project_lua_count = g_dluma.lua_discovery.local_count;
    dluma_lua_registry_unlock();

    std::uintptr_t observed_level_vtable = 0;
    const bool level_identity_valid = level && level_vtable != 0 &&
        ReadBytes(reinterpret_cast<std::uintptr_t>(level),
                  &observed_level_vtable,
                  sizeof(observed_level_vtable)) &&
        observed_level_vtable == level_vtable;
    const bool level_query_succeeded = query_succeeded != 0 && map_name &&
        map_name[0] && level_identity_valid;
    const bool frontend = level_query_succeeded &&
        dluma_frontend_level_name_is_frontend(map_name);
    const std::uintptr_t frontend_vtable =
        frontend ? observed_level_vtable : 0;
    const bool frontend_identity_valid =
        frontend && frontend_vtable != 0;
    if (exact_frame_route && level_query_succeeded && !frontend &&
        epoch_query_succeeded && current_epoch &&
        source_query_succeeded && active_custom_source_count)
        CapturePlayerPublicationCheckpoint(
            playerpublication::Checkpoint::
                FirstStableGameplayFrame);
    if (exact_frame_route && level_query_succeeded && !frontend)
        CaptureRuntime15InventoryTree(
            DLUMA_PLAYER_INVENTORY_PHASE_STABLE_GAMEPLAY, 0,
            frame_route_token, nullptr, level);
    /* The retained report key means "frontend seen on the validated exact
     * OnFrame route". Its Windows dispatcher may migrate between callbacks;
     * the window timer remains read-only diagnostic evidence. */
    if (frontend_identity_valid && exact_frame_route &&
        source == cold::StartupB0TickSource::OnFrame) {
        dluma_atomic_exchange(&g_startup_b0_on_frame_frontend_seen, 1);
        dluma_atomic_pointer_exchange(
            &g_startup_b0_on_frame_frontend_level, level);
        dluma_atomic_pointer_exchange(
            &g_startup_b0_on_frame_frontend_vtable,
            reinterpret_cast<void*>(frontend_vtable));
        CopyLoaderText(
            g_startup_b0_on_frame_frontend_name,
            sizeof(g_startup_b0_on_frame_frontend_name), map_name);
    }
    LARGE_INTEGER qpc = {};
    (void)QueryPerformanceCounter(&qpc);

    const LONG latched_close_reason = dluma_atomic_compare_exchange(
        &g_startup_b0_irreversible_close_reason, 0, 0);
    if (latched_close_reason != 0)
        (void)cold::CloseStartupB0Window(
            &g_startup_b0_session,
            static_cast<cold::StartupB0Blocker>(latched_close_reason));

    cold::StartupB0Diagnostics startup_diagnostics = {};
    (void)cold::SnapshotStartupB0Diagnostics(
        &g_startup_b0_session, &startup_diagnostics);
    std::uintptr_t latched_frontend_vtable = 0;
    const bool latched_frontend_identity_readable =
        !level_query_succeeded &&
        startup_diagnostics.startup_b0_frontend_level_pointer &&
        ReadBytes(
            startup_diagnostics.startup_b0_frontend_level_pointer,
            &latched_frontend_vtable,
            sizeof(latched_frontend_vtable)) &&
        latched_frontend_vtable != 0;
    cold::StartupB0AdmissionSample sample = {};
    sample.sequence = content::NextSequence(&g_content_ledger);
    sample.qpc = qpc.QuadPart > 0
        ? static_cast<std::uint64_t>(qpc.QuadPart) : 0;
    sample.frame_route_token = frame_route_token;
    sample.thread_id = static_cast<std::uint32_t>(current_thread_id);
    sample.tick_source = source;
    sample.query_succeeded = level_query_succeeded;
    sample.frontend_active = frontend_identity_valid;
    sample.validated_frame_route = exact_frame_route;
    sample.non_frontend_level_active = level_query_succeeded && !frontend;
    sample.returned_frontend = frontend_identity_valid &&
        dluma_atomic_compare_exchange(
            &g_startup_b0_custom_staging_seen, 0, 0) != 0;
    sample.latched_frontend_identity_readable =
        latched_frontend_identity_readable;
    sample.frontend_level_pointer = frontend_identity_valid
        ? reinterpret_cast<std::uintptr_t>(level) : 0;
    sample.frontend_level_vtable = frontend_vtable;
    sample.latched_frontend_vtable = latched_frontend_vtable;
    sample.current_epoch = epoch_query_succeeded ? current_epoch : 0;
    sample.active_custom_sources = active_custom_source_count;
    sample.local_lua_states = local_project_lua_count;
    sample.source_registry_reported_count =
        g_startup_filesystem_inventory.reported_count;
    sample.source_registry_observed_count =
        g_startup_filesystem_inventory.source_count;
    sample.source_inventory_result =
        startup_diagnostics.startup_b0_source_inventory_result;
    sample.player_inventory_authoritative =
        g_player_restart_adapter.coverage_started_before_first_allocation &&
        g_player_state_known_creator_sites_validated &&
        dluma_atomic_compare_exchange(
            &g_player_restart_adapter.inventory_loss_latched, 0, 0) == 0 &&
        dluma_atomic_compare_exchange(
            &g_player_restart_adapter.inventory_overflow_latched, 0, 0) == 0;
    sample.player_snapshot_result =
        startup_diagnostics.startup_b0_player_snapshot_result;
    sample.audio_snapshot_result =
        startup_diagnostics.startup_b0_audio_snapshot_result;
    sample.global_snapshot_result =
        startup_diagnostics.startup_b0_global_snapshot_result;
    sample.frontend_snapshot_result =
        startup_diagnostics.startup_b0_frontend_snapshot_result;
    sample.loader_pak_result =
        startup_diagnostics.startup_b0_loader_pak_result;
    sample.loader_xui_result =
        startup_diagnostics.startup_b0_loader_xui_result;
    if (!epoch_query_succeeded || !source_query_succeeded)
        sample.transient_blocker = cold::StartupB0Blocker::LedgerBusy;

    const cold::StartupB0AdvanceResult admission_result =
        cold::AdvanceStartupB0Admission(
            &g_startup_b0_session, &sample);
    if (ExpireUnresolvedPlayerAudioB0OnFrame(
            sample, player_audio_capture_now_ms))
        return;
    if (admission_result.window_closed) {
        cold::CloseIncompleteStartupBaselineCapture(
            &g_frontend_startup_baseline);
        AbandonStartupFilesystemInventory();
        g_component_status.baseline =
            ComponentRuntimeState::RuntimePartial;
        MarkContentDirty();
        return;
    }
    const bool current_frontend_matches_latched =
        frontend_identity_valid &&
        reinterpret_cast<std::uintptr_t>(level) ==
            startup_diagnostics.startup_b0_frontend_level_pointer &&
        frontend_vtable ==
            startup_diagnostics.startup_b0_frontend_level_vtable;
    const bool fresh_latched_frontend =
        !level_query_succeeded &&
        latched_frontend_identity_readable &&
        g_startup_b0_session.last_valid_frontend_qpc != 0 &&
        sample.qpc >= g_startup_b0_session.last_valid_frontend_qpc &&
        sample.qpc - g_startup_b0_session.last_valid_frontend_qpc <=
            g_startup_b0_session.maximum_candidate_age_qpc &&
        latched_frontend_vtable ==
            startup_diagnostics.startup_b0_frontend_level_vtable;
    const bool authorized_optional_fill =
        startup_diagnostics.startup_b0_state ==
            cold::StartupB0State::CompleteAuthorized &&
        startup_diagnostics.
            startup_b0_cold_reboot_baseline_authorized &&
        sample.validated_frame_route &&
        (current_frontend_matches_latched ||
         fresh_latched_frontend) &&
        !sample.returned_frontend && !latched_close_reason &&
        !current_epoch && !active_custom_source_count &&
        !local_project_lua_count;
    if (!admission_result.admission_ready &&
        !authorized_optional_fill)
        return;

    const std::uint64_t baseline_generation =
        g_startup_b0_session.session_generation;
    if (!g_frontend_startup_baseline.generation) {
        cold::StartupBaselineAdmission baseline_admission = {};
        baseline_admission.stable_frontend = true;
        baseline_admission.first_startup_frontend = true;
        baseline_admission.game_thread_owner =
            sample.validated_frame_route;
        baseline_admission.custom_epoch_count = current_epoch ? 1U : 0U;
        baseline_admission.active_custom_source_count =
            active_custom_source_count;
        baseline_admission.local_project_lua_count =
            local_project_lua_count;
        if (!cold::BeginStartupBaselineCapture(
                &g_frontend_startup_baseline, &baseline_admission,
                baseline_generation, sample.sequence, sample.qpc,
                sample.thread_id)) {
            cold::FailStartupB0Permanently(
                &g_startup_b0_session,
                cold::StartupB0Blocker::PermanentCaptureFailure);
            return;
        }
        if (!g_player_audio_b0_retry_gate.retry_deadline_ms &&
            !cold::InitializeStartupB0PlayerAudioRetryGate(
                &g_player_audio_b0_retry_gate,
                player_audio_capture_now_ms,
                kPlayerAudioB0RetryWindowMs)) {
            cold::FailStartupB0Permanently(
                &g_startup_b0_session,
                cold::StartupB0Blocker::PermanentCaptureFailure);
            return;
        }
    }

    char loader_pack_path[DLUMA_MAX_WPATH * 2] = {};
    char normalized_loader_pack_path[content::kSourcePathCapacity] = {};
    const bool loader_pack_mounted = dluma_content_pack_snapshot(
        loader_pack_path,
        static_cast<unsigned int>(sizeof(loader_pack_path))) != 0;
    const bool loader_pack_snapshot_matches = loader_pack_mounted &&
        content::NormalizePhysicalPath(
            loader_pack_path, normalized_loader_pack_path,
            sizeof(normalized_loader_pack_path)) &&
        g_normalized_loader_pack_path[0] &&
        content::PathsEqual(normalized_loader_pack_path,
                            g_normalized_loader_pack_path);
    const bool loader_xui_operational =
        dluma_ui_main_menu_redirect_is_applied() != 0;

    const std::size_t vfs_domain_index = static_cast<std::size_t>(
        cold::StartupB0Domain::VfsSourceInventory);
    if (!g_startup_b0_session.domains[vfs_domain_index].ready) {
        const StartupVfsInventoryCaptureResult vfs_result =
            CaptureStartupFilesystemInventory();
        if (vfs_result == StartupVfsInventoryCaptureResult::Retry) {
            const bool changed = g_startup_vfs_inventory_failure ==
                vfs::FilesystemSourceInventoryFailure::
                    RegistryChangedDuringCapture;
            (void)cold::RecordStartupB0DomainResult(
                &g_startup_b0_session,
                cold::StartupB0Domain::VfsSourceInventory,
                changed ? cold::StartupB0DomainCaptureResult::RetryChanged
                        : cold::StartupB0DomainCaptureResult::RetryBusy,
                changed ? cold::StartupB0Blocker::SourceRegistryChanged
                        : cold::StartupB0Blocker::SourceRegistryBusy,
                sample.sequence, baseline_generation, 0);
        } else if (vfs_result == StartupVfsInventoryCaptureResult::Ready) {
            std::uint64_t loader_source_identity = 0;
            bool complete = CommitStartupFilesystemInventory();
            if (complete)
                complete = PopulateBaselineSourceInventory(
                    loader_pack_snapshot_matches,
                    &loader_source_identity);
            const bool owner_validation_failed = !complete &&
                g_startup_source_classification.
                    first_owner_validation_failure_available;
            const DlumaNativeCompanionOwnerValidationResult
                owner_validation_result = owner_validation_failed
                    ? g_startup_source_classification.
                        first_owner_validation_failure.result
                    : DLUMA_COMPANION_ARCHIVE_OWNER_VALID;
            if (!complete) {
                AbandonStartupFilesystemInventory();
                if (g_startup_vfs_inventory_failure ==
                        vfs::FilesystemSourceInventoryFailure::None)
                    g_startup_vfs_inventory_failure =
                        vfs::FilesystemSourceInventoryFailure::
                            ClassificationUnavailable;
            }
            g_frontend_startup_baseline.custom_source_count =
                active_custom_source_count;
            g_frontend_startup_baseline.source_inventory_complete = complete;
            g_frontend_startup_baseline.loader.loader_pak_identity =
                complete ? loader_source_identity : 0;
            const bool registry_changed = !complete &&
                g_startup_vfs_inventory_failure ==
                    vfs::FilesystemSourceInventoryFailure::
                        RegistryChangedDuringCapture;
            if (owner_validation_failed) {
                (void)cold::RecordStartupB0SourceOwnerFailure(
                    &g_startup_b0_session,
                    static_cast<std::uint32_t>(
                        owner_validation_result),
                    dluma_native_companion_owner_validation_result_retryable(
                        owner_validation_result) != 0,
                    GetTickCount64(),
                    kStartupSourceOwnerPublicationRetryWindowMs);
            } else {
                (void)cold::RecordStartupB0DomainResult(
                    &g_startup_b0_session,
                    cold::StartupB0Domain::VfsSourceInventory,
                    complete ? cold::StartupB0DomainCaptureResult::Ready
                             : registry_changed
                                 ? cold::StartupB0DomainCaptureResult::
                                       RetryChanged
                                 : cold::StartupB0DomainCaptureResult::
                                       Incomplete,
                    complete ? cold::StartupB0Blocker::None
                             : registry_changed
                                 ? cold::StartupB0Blocker::
                                       SourceRegistryChanged
                                 : cold::StartupB0Blocker::
                                       SourceInventoryIncomplete,
                    sample.sequence, baseline_generation,
                    complete ? loader_source_identity : 0);
            }
        } else {
            AbandonStartupFilesystemInventory();
            (void)cold::RecordStartupB0DomainResult(
                &g_startup_b0_session,
                cold::StartupB0Domain::VfsSourceInventory,
                cold::StartupB0DomainCaptureResult::Incomplete,
                cold::StartupB0Blocker::SourceInventoryIncomplete,
                sample.sequence, baseline_generation, 0);
        }
    }

    const std::size_t loader_domain_index = static_cast<std::size_t>(
        cold::StartupB0Domain::LoaderState);
    if (!g_startup_b0_session.domains[loader_domain_index].ready) {
        g_baseline_global_lua_hash = global_lua_hash;
        g_baseline_global_lua_count = global_lua_count;
        g_frontend_startup_baseline.loader.global_lua_fingerprint =
            global_lua_hash;
        g_frontend_startup_baseline.loader.approved_global_lua_count =
            global_lua_count;
        g_frontend_startup_baseline.loader.local_project_lua_count =
            local_project_lua_count;
        g_frontend_startup_baseline.loader.loader_pak_state_known = true;
        g_frontend_startup_baseline.loader.loader_pak_present =
            loader_pack_snapshot_matches;
        g_frontend_startup_baseline.loader.loader_xui_state_known = true;
        g_frontend_startup_baseline.loader.loader_xui_operational =
            loader_xui_operational;
        const bool loader_ready = loader_pack_snapshot_matches &&
            loader_xui_operational && !local_project_lua_count &&
            g_frontend_startup_baseline.loader.loader_pak_identity;
        (void)cold::RecordStartupB0DomainResult(
            &g_startup_b0_session,
            cold::StartupB0Domain::LoaderState,
            loader_ready ? cold::StartupB0DomainCaptureResult::Ready
                         : cold::StartupB0DomainCaptureResult::Incomplete,
            loader_ready ? cold::StartupB0Blocker::None
                         : cold::StartupB0Blocker::LoaderStateIncomplete,
            sample.sequence, baseline_generation,
            loader_ready
                ? g_frontend_startup_baseline.loader.loader_pak_identity
                : 0);
    }

    (void)CaptureProductionCraftingBaseline(baseline_generation, sample.thread_id);
    {
        cold::RestartContext xui_context={};
        xui_context.baseline_generation=baseline_generation;
        xui_context.owner_thread_id=sample.thread_id;
        (void)ColdXuiBaseline(nullptr,&xui_context);
    }
    if (g_curve_hooks_available && !g_curve_owner.baseline_captured) {
        cold::RestartContext curve_context = {};
        curve_context.baseline_generation = baseline_generation;
        curve_context.owner_thread_id = sample.thread_id;
        (void)ColdCurvesBaseline(nullptr, &curve_context);
    }
    if(g_native_resources.available&&!g_native_resources.baseline_generation){
        cold::RestartContext resource_context={};resource_context.baseline_generation=baseline_generation;
        resource_context.owner_thread_id=sample.thread_id;
        (void)ColdResourcesBaseline(nullptr,&resource_context);
        (void)ColdMaterialsBaseline(nullptr,&resource_context);
    }

    if (g_text_hooks_available && !g_text_baseline_owner.baseline.complete) {
        cold::RestartContext text_context = {};
        text_context.baseline_generation = baseline_generation;
        text_context.owner_thread_id = sample.thread_id;
        (void)ColdTextsBaseline(nullptr, &text_context);
    }

    const std::size_t player_domain_index = static_cast<std::size_t>(
        cold::StartupB0Domain::Player);
    const std::size_t audio_domain_index = static_cast<std::size_t>(
        cold::StartupB0Domain::Audio);
    if (!g_startup_b0_session.domains[player_domain_index].ready) {
        cold::RestartContext player_context = {};
        player_context.baseline_generation = baseline_generation;
        player_context.sequence = sample.sequence;
        player_context.owner_thread_id = sample.thread_id;
        cold::DomainResult player_result = cold::DomainResult::Failed;
        if (PrepareProductionPlayerB0SnapshotContext()) {
            player_result =
                playerrestart::CapturePlayerGameplayParamsBaseline(
                    &g_player_restart_adapter, &player_context);
            /* The registry-owned Player B0 is authoritative for the Player
             * transaction.  The legacy combined frontend projection remains
             * best-effort because optional progression/provider observers
             * may be absent; failure must not discard the direct snapshot. */
            if (player_result == cold::DomainResult::Succeeded)
                (void)PublishProductionPlayerB0ToFrontendBaseline();
            if (player_result == cold::DomainResult::Succeeded &&
                !ProductionPlayerPublishedEvidenceStable(
                    g_production_player_b0_context)) {
                (void)cold::AbandonBaselinePlayerSnapshot(
                    &g_frontend_startup_baseline);
                (void)playerrestart::
                    AbandonPlayerGameplayParamsBaseline(
                        &g_player_restart_adapter);
                player_result = cold::DomainResult::Failed;
            }
            if (player_result == cold::DomainResult::Succeeded &&
                g_player_restart_adapter.baseline_kind ==
                    playerrestart::PlayerStartupBaselineKind::Absent) {
                const bool absent_owner_ready =
                    (g_player_absent_reset_adapter.baseline_captured &&
                     g_player_absent_reset_adapter.baseline_generation ==
                         baseline_generation) ||
                    (!g_player_absent_reset_adapter.baseline_captured &&
                     CaptureProductionPlayerAbsentBaseline(
                         baseline_generation));
                if (!absent_owner_ready) {
                    (void)cold::AbandonBaselinePlayerSnapshot(
                        &g_frontend_startup_baseline);
                    (void)playerrestart::
                        AbandonPlayerGameplayParamsBaseline(
                            &g_player_restart_adapter);
                    player_result = cold::DomainResult::Failed;
                }
            }
        }
        if (player_result == cold::DomainResult::Succeeded)
            CapturePlayerPublicationB0Commit(sample.sequence);
        else
            RecordFirstPlayerB0FailureDiagnostics();
        (void)cold::RecordStartupB0DomainResult(
            &g_startup_b0_session, cold::StartupB0Domain::Player,
            player_result == cold::DomainResult::Succeeded
                ? cold::StartupB0DomainCaptureResult::Ready
                : cold::StartupB0DomainCaptureResult::Incomplete,
            player_result == cold::DomainResult::Succeeded
                ? cold::StartupB0Blocker::None
                : sample.player_inventory_authoritative
                    ? cold::StartupB0Blocker::PlayerSnapshotIncomplete
                    : cold::StartupB0Blocker::PlayerInventoryIncomplete,
            sample.sequence, baseline_generation,
            player_result == cold::DomainResult::Succeeded
                ? g_player_restart_adapter.
                      baseline_gameplay_cache_fingerprint
                : 0);
    }

    const ULONGLONG audio_capture_now = GetTickCount64();
    const ULONGLONG audio_capture_next_retry =
        static_cast<ULONGLONG>(_InterlockedCompareExchange64(
            &g_audio_startup_capture_next_retry_ms, 0, 0));
    const bool raw_audio_capture_due =
        dluma_atomic_compare_exchange(
            &g_audio_startup_capture_terminal, 0, 0) == 0 &&
        audio_capture_now >= audio_capture_next_retry;
    const bool minimum_audio_capture_due =
        !g_audio_minimum_semantic_state.baseline_captured;
    if (!g_startup_b0_session.domains[audio_domain_index].ready &&
        (minimum_audio_capture_due || raw_audio_capture_due)) {
        const bool minimum_audio_ready =
            CaptureProductionAudioMinimumBaseline(
                baseline_generation);
        StartupAudioCaptureResult audio_result =
            static_cast<StartupAudioCaptureResult>(
                dluma_atomic_compare_exchange(
                    &g_audio_startup_capture_result, 0, 0));
        if (raw_audio_capture_due) {
            audio_result = CaptureStartupAudioRawInventory();
            dluma_atomic_exchange(
                &g_audio_startup_capture_result,
                static_cast<LONG>(audio_result));
        }
        const bool retry =
            audio_result == StartupAudioCaptureResult::Retry;
        const bool observational =
            audio_result ==
                StartupAudioCaptureResult::ObservationalCaptured;
        if (raw_audio_capture_due && retry)
            _InterlockedExchange64(
                &g_audio_startup_capture_next_retry_ms,
                static_cast<LONGLONG>(
                    audio_capture_now + kAudioStartupCaptureRetryMs));
        else if (raw_audio_capture_due)
            dluma_atomic_exchange(&g_audio_startup_capture_terminal, 1);
        (void)cold::RecordStartupB0DomainResult(
            &g_startup_b0_session, cold::StartupB0Domain::Audio,
            minimum_audio_ready
                ? cold::StartupB0DomainCaptureResult::Ready
                : retry ||
                          minimum_audio_capture_due
                    ? cold::StartupB0DomainCaptureResult::RetryBusy
                    : cold::StartupB0DomainCaptureResult::Incomplete,
            minimum_audio_ready
                ? cold::StartupB0Blocker::None
                : cold::StartupB0Blocker::
                      AudioMinimumSemanticSnapshotIncomplete,
            sample.sequence, baseline_generation,
            minimum_audio_ready
                ? g_audio_minimum_semantic_state.baseline.
                    script.semantic_fingerprint
                : observational
                ? g_audio_baseline_windows_snapshot.
                    raw_snapshot_fingerprint
                : 0);
    }

    /* Holding and hashing native bank input may span multiple clean startup
     * frames. The minimum semantic snapshot becoming ready must not stop it. */
    (void)AdvanceProductionAudioBaselineContent(baseline_generation);

    const cold::StartupB0Domain unresolved_domains[] = {
        cold::StartupB0Domain::GlobalData,
        cold::StartupB0Domain::FrontendResources,
    };
    for (cold::StartupB0Domain domain : unresolved_domains) {
        const std::size_t index = static_cast<std::size_t>(domain);
        if (g_startup_b0_session.domains[index].ready) continue;
        const cold::StartupB0Blocker blocker =
            domain == cold::StartupB0Domain::GlobalData
                ? cold::StartupB0Blocker::GlobalDataIncomplete
                : cold::StartupB0Blocker::FrontendResourcesIncomplete;
        (void)cold::RecordStartupB0DomainResult(
            &g_startup_b0_session, domain,
            cold::StartupB0DomainCaptureResult::Incomplete, blocker,
            sample.sequence, baseline_generation, 0);
    }

    /* Close the read-only capture window against staging that began after
     * the admission sample.  Counts in the discovery/ownership ledgers are
     * not sticky, so the hook/discovery latches above are authoritative;
     * these direct reads provide a second fail-closed check before registry
     * authorization. */
    const LONG post_capture_latched_reason = dluma_atomic_compare_exchange(
        &g_startup_b0_irreversible_close_reason, 0, 0);
    std::uint32_t post_capture_epoch = 0;
    const bool post_capture_epoch_read = content::TryGetCurrentEpochId(
        &g_content_ledger, &post_capture_epoch);
    const std::uint32_t post_capture_sources =
        content::CountActiveCustomSources(&g_content_ledger);
    std::uint32_t post_capture_local_lua = 0;
    dluma_lua_registry_lock();
    post_capture_local_lua = g_dluma.lua_discovery.local_count;
    dluma_lua_registry_unlock();
    cold::StartupB0Blocker post_capture_close_reason =
        post_capture_latched_reason != 0
            ? static_cast<cold::StartupB0Blocker>(
                  post_capture_latched_reason)
            : post_capture_epoch
                ? cold::StartupB0Blocker::ActiveCustomEpoch
                : post_capture_sources != UINT32_MAX &&
                          post_capture_sources != 0
                    ? cold::StartupB0Blocker::ActiveCustomSource
                    : post_capture_local_lua
                        ? cold::StartupB0Blocker::LocalLuaPresent
                        : cold::StartupB0Blocker::None;
    if (post_capture_close_reason != cold::StartupB0Blocker::None) {
        LatchStartupB0IrreversibleClose(post_capture_close_reason);
        (void)cold::CloseStartupB0Window(
            &g_startup_b0_session, post_capture_close_reason);
        cold::CloseIncompleteStartupBaselineCapture(
            &g_frontend_startup_baseline);
        AbandonStartupFilesystemInventory();
        g_component_status.baseline =
            ComponentRuntimeState::RuntimePartial;
        MarkContentDirty();
        return;
    }
    if (!post_capture_epoch_read || post_capture_sources == UINT32_MAX)
        return;

    cold::StartupB0Diagnostics after_capture = {};
    (void)cold::SnapshotStartupB0Diagnostics(
        &g_startup_b0_session, &after_capture);
    const std::size_t core_vfs = static_cast<std::size_t>(
        cold::StartupB0Domain::VfsSourceInventory);
    const std::size_t core_loader = static_cast<std::size_t>(
        cold::StartupB0Domain::LoaderState);
    const std::size_t core_player = static_cast<std::size_t>(
        cold::StartupB0Domain::Player);
    const std::size_t core_audio = static_cast<std::size_t>(
        cold::StartupB0Domain::Audio);
    const bool transaction_b0_ready =
        g_startup_b0_session.domains[core_vfs].ready &&
        g_startup_b0_session.domains[core_loader].ready &&
        g_startup_b0_session.domains[core_player].ready &&
        g_startup_b0_session.domains[core_audio].ready &&
        g_player_restart_adapter.baseline_captured &&
        g_player_restart_adapter.baseline_kind !=
            playerrestart::PlayerStartupBaselineKind::Unavailable &&
        g_audio_minimum_semantic_state.baseline_captured;
    const cold::ContentDomainMask player_ready_bit = cold::DomainBit(
        cold::ContentDomainId::PlayerGameplayParams);
    if (transaction_b0_ready && !g_cold_reboot.baseline_captured) {
        cold::RestartContext baseline_context = {};
        baseline_context.baseline_generation = baseline_generation;
        baseline_context.owner_thread_id = sample.thread_id;
        const cold::RestartResult registry_result =
            cold::CaptureColdRebootBaseline(
                &g_cold_reboot, &baseline_context);
        if (registry_result == cold::RestartResult::Verified) {
            g_component_status.frontend_cold_reboot =
                ComponentRuntimeState::Armed;
            g_component_status.baseline =
                ComponentRuntimeState::Armed;
            g_component_status.player_preset =
                !g_player_restart_adapter.mutation_operations.
                         production_enabled
                    ? ComponentRuntimeState::UnsupportedBuild
                    : (g_cold_reboot_registry.baseline_ready_mask &
                       player_ready_bit) != 0
                        ? ComponentRuntimeState::Armed
                        : ComponentRuntimeState::RuntimePartial;
        }
    }
    if (g_cold_reboot.baseline_captured &&
        g_player_restart_adapter.baseline_captured &&
        g_startup_b0_session.domains[player_domain_index].ready &&
        (g_cold_reboot_registry.baseline_ready_mask &
         player_ready_bit) == 0) {
        cold::RestartContext optional_context = {};
        optional_context.baseline_generation = baseline_generation;
        optional_context.owner_thread_id = sample.thread_id;
        const cold::RestartResult fill_result =
            cold::ExtendRegistryBaseline(
                &g_cold_reboot_registry, &optional_context,
                player_ready_bit);
        if (fill_result == cold::RestartResult::Verified)
            g_component_status.player_preset =
                g_player_restart_adapter.mutation_operations.
                        production_enabled
                    ? ComponentRuntimeState::Armed
                    : ComponentRuntimeState::UnsupportedBuild;
    }
    const auto curve_ready_bit = cold::DomainBit(cold::ContentDomainId::Curves);
    if (g_cold_reboot.baseline_captured && g_curve_owner.baseline_captured &&
        !(g_cold_reboot_registry.baseline_ready_mask & curve_ready_bit)) {
        cold::RestartContext curve_context = {};
        curve_context.baseline_generation = baseline_generation;
        curve_context.owner_thread_id = sample.thread_id;
        (void)cold::ExtendRegistryBaseline(&g_cold_reboot_registry, &curve_context, curve_ready_bit);
    }
    const auto text_ready_bit = cold::DomainBit(cold::ContentDomainId::LocalizedTexts);
    if (g_cold_reboot.baseline_captured && g_text_baseline_owner.baseline.complete &&
        g_text_baseline_owner.phase == texts::TextPhase::BaselineCaptured &&
        !(g_cold_reboot_registry.baseline_ready_mask & text_ready_bit)) {
        cold::RestartContext text_context = {};
        text_context.baseline_generation = baseline_generation;
        text_context.owner_thread_id = sample.thread_id;
        (void)cold::ExtendRegistryBaseline(&g_cold_reboot_registry, &text_context, text_ready_bit);
    }
    if (after_capture.startup_b0_full_b0_captured &&
        !after_capture.
            startup_b0_cold_reboot_baseline_authorized) {
        cold::RestartContext baseline_context = {};
        baseline_context.baseline_generation = baseline_generation;
        baseline_context.owner_thread_id = sample.thread_id;
        const cold::RestartResult registry_result =
            g_cold_reboot.baseline_captured
                ? g_cold_reboot.last_registry_result
                : cold::CaptureColdRebootBaseline(
                      &g_cold_reboot, &baseline_context);
        const bool authorized =
            (registry_result == cold::RestartResult::Verified ||
             registry_result == cold::RestartResult::RuntimePartial) &&
            cold::AuthorizeStartupB0RegistryBaseline(
                &g_startup_b0_session, baseline_generation);
        (void)content::MarkBaselineCaptured(
            &g_content_ledger, authorized, baseline_generation);
        if (!authorized &&
            registry_result == cold::RestartResult::RuntimeFailed)
            cold::FailStartupB0Permanently(
                &g_startup_b0_session,
                cold::StartupB0Blocker::RegistryBaselineIncomplete);
    }
    if (!g_cold_reboot.baseline_captured) {
        if (g_component_status.frontend_cold_reboot !=
                ComponentRuntimeState::RuntimeFailed)
            g_component_status.frontend_cold_reboot =
                ComponentRuntimeState::RuntimePartial;
        if (g_component_status.baseline !=
                ComponentRuntimeState::RuntimeFailed)
            g_component_status.baseline =
                ComponentRuntimeState::RuntimePartial;
    }
    MarkContentDirty();

    if (g_last_frontend_reset_epoch &&
        g_last_frontend_reset_epoch != g_last_verified_reset_epoch)
        VerifyFrontendBaseline(g_last_frontend_reset_epoch);
}

extern "C" const char* dluma_custom_map_asset_trace_status_text(void)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    if (!g_dluma.config.custom_map_asset_isolation_enabled)
        return "Custom Map Content Isolation\nDisabled";
    if (!ContentTrackingLive())
        return "Custom Map Content Isolation\nUnsupported/ApplyFailed - tracking inactive; no cleanup enabled";
    g_component_status_text[0] = 0;
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "Custom Map Content Isolation\nOverall: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   FixStateName(AggregateState()));
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "\nSources: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   ComponentStateName(g_component_status.sources));
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "\nLevel resources: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   ComponentStateName(g_component_status.level_resources));
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "\nGlobal Data: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   ComponentStateName(g_component_status.global_data));
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "\nFrontend cold reboot: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   ComponentStateName(
                       g_component_status.frontend_cold_reboot));
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "\nPlayer gameplay params: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   ComponentStateName(g_component_status.player_preset));
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "\nAudio banks: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   ComponentStateName(g_component_status.audio_banks));
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   "\nLast frontend reset: ");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   g_component_status.last_reset_epoch
                       ? ComponentStateName(g_component_status.baseline)
                       : "Not run");
    dluma_str_append(g_component_status_text,
                   DLUMA_ARRAY_COUNT(g_component_status_text),
                   dluma_atomic_compare_exchange(&g_trace_live, 0, 0) != 0
                       ? "\nDetailed trace: active"
                       : "\nDetailed trace: off");
    return g_component_status_text;
}

extern "C" void
dluma_custom_map_asset_isolation_note_local_lua_active(void)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    if (!ContentTrackingLive()) return;
    /* Discovery can run outside the validated capture owner. Publish only the
     * sticky POD close fact here; the validated OnFrame/timer thread owns the
     * state transition and report drain. */
    LatchStartupB0IrreversibleClose(
        cold::StartupB0Blocker::LocalLuaPresent);
}

extern "C" DlumaProjectOwnerProofStatus
dluma_custom_map_exact_project_owner_snapshot(
    const char* map_name,
    DlumaProjectOwnerProofSnapshot* snapshot_out)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    if (!snapshot_out)
        return DLUMA_PROJECT_OWNER_PROOF_REJECTED;
    std::memset(snapshot_out, 0, sizeof(*snapshot_out));
    snapshot_out->status = DLUMA_PROJECT_OWNER_PROOF_UNAVAILABLE;
    snapshot_out->reason =
        DLUMA_PROJECT_OWNER_REASON_TRACKING_UNAVAILABLE;
    ActiveConsumerCall consumer_call;
    if (!ContentTrackingLive() || g_dluma.stop_requested)
        return DLUMA_PROJECT_OWNER_PROOF_UNAVAILABLE;

    content::ExactMapOwnerProofSnapshot proof = {};
    const content::ExactMapOwnerProofStatus status =
        content::SnapshotExactMapOwnerProof(
            &g_content_ledger, map_name,
            trace::GlobalTransitionGeneration(), &proof);
    switch (status) {
    case content::ExactMapOwnerProofStatus::Ready:
        snapshot_out->status = DLUMA_PROJECT_OWNER_PROOF_READY;
        break;
    case content::ExactMapOwnerProofStatus::Pending:
        snapshot_out->status = DLUMA_PROJECT_OWNER_PROOF_PENDING;
        break;
    default:
        snapshot_out->status = DLUMA_PROJECT_OWNER_PROOF_REJECTED;
        break;
    }
    switch (proof.reason) {
    case content::ExactMapOwnerProofReason::None:
        snapshot_out->reason = DLUMA_PROJECT_OWNER_REASON_NONE;
        break;
    case content::ExactMapOwnerProofReason::NoEvidence:
        snapshot_out->reason = DLUMA_PROJECT_OWNER_REASON_NO_EVIDENCE;
        break;
    case content::ExactMapOwnerProofReason::MapMismatch:
        snapshot_out->reason = DLUMA_PROJECT_OWNER_REASON_MAP_MISMATCH;
        break;
    case content::ExactMapOwnerProofReason::TransitionMismatch:
        snapshot_out->reason =
            DLUMA_PROJECT_OWNER_REASON_TRANSITION_MISMATCH;
        break;
    case content::ExactMapOwnerProofReason::Consumed:
        snapshot_out->reason =
            DLUMA_PROJECT_OWNER_REASON_CONSUMED;
        break;
    case content::ExactMapOwnerProofReason::AmbiguousEvidence:
        snapshot_out->reason =
            DLUMA_PROJECT_OWNER_REASON_AMBIGUOUS_EVIDENCE;
        break;
    case content::ExactMapOwnerProofReason::NoActiveEpoch:
        snapshot_out->reason =
            DLUMA_PROJECT_OWNER_REASON_NO_ACTIVE_EPOCH;
        break;
    case content::ExactMapOwnerProofReason::OwnershipIncomplete:
        snapshot_out->reason =
            DLUMA_PROJECT_OWNER_REASON_OWNERSHIP_INCOMPLETE;
        break;
    case content::ExactMapOwnerProofReason::SourceInvalid:
        snapshot_out->reason =
            DLUMA_PROJECT_OWNER_REASON_SOURCE_INVALID;
        break;
    case content::ExactMapOwnerProofReason::LedgerBusy:
        snapshot_out->reason = DLUMA_PROJECT_OWNER_REASON_LEDGER_BUSY;
        break;
    default:
        snapshot_out->reason =
            DLUMA_PROJECT_OWNER_REASON_INVALID_PATH;
        break;
    }
    if (status == content::ExactMapOwnerProofStatus::Ready) {
        snapshot_out->epoch = proof.epoch;
        snapshot_out->source_record_index =
            proof.source_record_index;
        snapshot_out->source_add_ordinal =
            proof.source_add_ordinal;
        snapshot_out->transition_generation =
            proof.transition_generation;
        std::memcpy(snapshot_out->map_name, proof.map_name,
                    sizeof(snapshot_out->map_name));
        std::memcpy(snapshot_out->project_root,
                    proof.project_root,
                    sizeof(snapshot_out->project_root));
    }
    return static_cast<DlumaProjectOwnerProofStatus>(
        snapshot_out->status);
}

extern "C" int dluma_custom_map_exact_project_owner_consume(
    const DlumaProjectOwnerProofSnapshot* snapshot)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    char project_root_utf8[content::kSourcePathCapacity];
    if (!snapshot ||
        snapshot->status != DLUMA_PROJECT_OWNER_PROOF_READY)
        return 0;
    ActiveConsumerCall consumer_call;
    if (!ContentTrackingLive() || g_dluma.stop_requested)
        return 0;
    content::ExactMapOwnerProofSnapshot proof = {};
    proof.status = content::ExactMapOwnerProofStatus::Ready;
    proof.reason = content::ExactMapOwnerProofReason::None;
    proof.epoch = snapshot->epoch;
    proof.source_record_index = snapshot->source_record_index;
    proof.source_add_ordinal = snapshot->source_add_ordinal;
    proof.transition_generation =
        snapshot->transition_generation;
    std::memcpy(proof.map_name, snapshot->map_name,
                sizeof(proof.map_name));
    if (!dluma_wide_to_utf8(
            snapshot->project_root, project_root_utf8,
            static_cast<unsigned int>(
                sizeof(project_root_utf8))) ||
        !content::NormalizeProjectRoot(
            project_root_utf8,
            proof.normalized_project_root,
            sizeof(proof.normalized_project_root)))
        return 0;
    return content::ConsumeExactMapOwnerProof(
               &g_content_ledger, &proof)
               ? 1
               : 0;
}

extern "C" void dluma_custom_map_asset_trace_active_level_observed(
    const char* map_name, void* level, const char* project_root,
    ULONGLONG worker_timestamp_ms)
{
    using namespace dluma::fixes::custom_map_asset_isolation;
    ActiveConsumerCall consumer_call;
    if (!map_name || !map_name[0] || !level)
        return;
    if (dluma_frontend_level_name_is_frontend(map_name)) {
        const bool first_worker_frontend =
            dluma_atomic_compare_exchange(
                &g_startup_b0_worker_frontend_seen, 1, 0) == 0;
        dluma_atomic_pointer_exchange(
            &g_startup_b0_worker_frontend_level, level);
        if (first_worker_frontend) {
            dluma_atomic_exchange(
                &g_startup_b0_worker_frontend_frame_count,
                dluma_atomic_compare_exchange(
                    &g_dluma.engine.game_frame_hook_call_count, 0, 0));
            dluma_atomic_exchange(
                &g_startup_b0_worker_frontend_pump_count,
                dluma_atomic_compare_exchange(
                    &g_dluma.engine.startup_b0_onframe_pump_call_count,
                    0, 0));
            dluma_atomic_exchange(
                &g_startup_b0_worker_frontend_query_count,
                dluma_atomic_compare_exchange(
                    &g_dluma.engine.
                        startup_b0_active_level_query_call_count,
                    0, 0));
            dluma_atomic_exchange(
                &g_startup_b0_worker_frontend_query_success_count,
                dluma_atomic_compare_exchange(
                    &g_dluma.engine.
                        startup_b0_active_level_query_success_count,
                    0, 0));
            dluma_atomic_exchange(
                &g_startup_b0_worker_frontend_query_null_count,
                dluma_atomic_compare_exchange(
                    &g_dluma.engine.
                        startup_b0_active_level_query_null_count,
                    0, 0));
            dluma_atomic_exchange(
                &g_startup_b0_worker_frontend_query_invalid_count,
                dluma_atomic_compare_exchange(
                    &g_dluma.engine.
                        startup_b0_active_level_query_invalid_count,
                    0, 0));
        }
    }
    if (dluma_atomic_compare_exchange(&g_trace_live, 0, 0) == 0)
        return;
    SourceLabelSnapshot previous = {};
    char normalized_previous[content::kSourcePathCapacity];
    char normalized_current[content::kSourcePathCapacity];
    const std::uint32_t current_epoch =
        content::CurrentEpochId(&g_content_ledger);
    const bool same_project_transition = current_epoch &&
        ReadSourceLabels(&previous) && previous.epoch == current_epoch &&
        previous.level &&
        (previous.level != level ||
         !AsciiEqualsInsensitive(previous.map, map_name)) &&
        previous.project_complete && previous.project[0] &&
        previous.project[0] != '<' && project_root && project_root[0] &&
        content::NormalizeProjectRoot(
            previous.project, normalized_previous,
            sizeof(normalized_previous)) &&
        content::NormalizeProjectRoot(
            project_root, normalized_current,
            sizeof(normalized_current)) &&
        content::PathsEqual(normalized_previous, normalized_current);
    if (same_project_transition)
        QueueContentDiagnostic(
            content::LedgerDiagnosticType::
                SameProjectTransitionNoSourceReset,
            current_epoch, 1,
            reinterpret_cast<std::uintptr_t>(level),
            reinterpret_cast<std::uintptr_t>(previous.level),
            worker_timestamp_ms, previous.map, map_name);
    WriteSourceLabels(map_name, level,
                      project_root && project_root[0]
                          ? project_root
                          : "<unknown>",
                      current_epoch);
    PublishSimple(AssetTraceEventType::ActiveLevelObserved,
                  reinterpret_cast<std::uintptr_t>(level), 0, 0,
                  worker_timestamp_ms, 0, map_name,
                  project_root && project_root[0]
                      ? project_root
                      : "<unknown>");
}

